-- ----------------------------
-- Table structure for discount
-- ----------------------------
DROP TABLE IF EXISTS `discount`;
CREATE TABLE `discount`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `ebookID` int NULL DEFAULT NULL,
  `percent` decimal(5, 2) NULL DEFAULT NULL,
  `startDate` datetime NULL DEFAULT NULL,
  `endDate` datetime NULL DEFAULT NULL,
  `isActive` tinyint(1) NULL DEFAULT 1,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ebookID`(`ebookID` ASC) USING BTREE,
  CONSTRAINT `discount_ibfk_1` FOREIGN KEY (`ebookID`) REFERENCES `ebook` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of discount
-- ----------------------------

-- ----------------------------
-- Table structure for ebook
-- ----------------------------
DROP TABLE IF EXISTS `ebook`;
CREATE TABLE `ebook`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `ebookCode` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `price` decimal(10, 2) NOT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `categoryID` int NULL DEFAULT NULL,
  `fileID` int NULL DEFAULT NULL,
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `deletedAt` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `categoryID`(`categoryID` ASC) USING BTREE,
  INDEX `fileID`(`fileID` ASC) USING BTREE,
  CONSTRAINT `ebook_ibfk_1` FOREIGN KEY (`categoryID`) REFERENCES `category` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `ebook_ibfk_2` FOREIGN KEY (`fileID`) REFERENCES `files` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 301 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of ebook
-- ----------------------------
INSERT INTO `ebook` VALUES (1, 'T1.0', 'Clean Code — Robert C. Martin (Uncle Bob)', 250000.00, 'Cuốn Clean Code: A Handbook of Agile Software Craftsmanship của Robert C. Martin (thường gọi là \"Uncle Bob\") là một trong những cuốn sách kinh điển dành cho lập trình viên muốn nâng cao chất lượng mã nguồn.\n\nMô tả ngắn gọn:\n\nMục tiêu chính: Giúp lập trình viên viết mã sạch, dễ đọc, dễ bảo trì và dễ mở rộng.', 1, 1, 'active', NULL);
INSERT INTO `ebook` VALUES (2, 'T2.0', 'The Pragmatic Programmer — Andrew Hunt & David Thomas', 300000.00, 'Cung cấp các nguyên tắc, mẹo và triết lý giúp lập trình viên trở nên chuyên nghiệp và hiệu quả hơn.\n\nTập trung vào tư duy linh hoạt, chủ động, và khả năng giải quyết vấn đề trong phát triển phần mềm.\n', 1, 2, 'active', NULL);
INSERT INTO `ebook` VALUES (3, 'T3.0', 'Design Patterns: Elements of Reusable Object-Oriented Software — Gamma et al.', 400000.00, 'Xuất bản lần đầu năm 1994, cuốn sách giới thiệu 23 mẫu thiết kế phần mềm (design patterns) giúp giải quyết các vấn đề phổ biến trong phát triển phần mềm hướng đối tượng.\n\nCuốn sách không chỉ giúp bạn viết mã tái sử dụng, dễ bảo trì, mà còn nâng cao tư duy thiết kế phần mềm chuyên nghiệp.', 1, 3, 'active', NULL);
INSERT INTO `ebook` VALUES (4, 'T4.0', 'Refactoring — Martin Fowler', 280000.00, 'Mục tiêu chính: Giúp bạn cải thiện thiết kế của mã hiện có mà không phá vỡ chức năng.\nCuốn sách này rất phù hợp cho những ai đang làm việc với mã legacy, hoặc muốn nâng cao kỹ năng viết mã sạch và có cấu trúc tốt.', 1, 4, 'active', NULL);
INSERT INTO `ebook` VALUES (5, 'T5.0', 'Code Complete — Steve McConnell', 400000.00, 'Thiết kế hàm và module có độ kết dính cao, ít phụ thuộc.\n\nTái cấu trúc mã, kiểm thử đơn vị, và quản lý độ phức tạp.\n\nSo sánh các phong cách lập trình và cách chọn giải pháp phù hợp.\n\nCuốn sách không chỉ dành cho người mới học mà còn là tài liệu tham khảo lâu dài cho lập trình viên có kinh nghiệm.', 1, 5, 'active', NULL);
INSERT INTO `ebook` VALUES (6, 'T6.0', 'Continuous Delivery — Jez Humble & David Farley', 400000.00, 'Mô tả ngắn gọn\nMục tiêu chính: Giúp các nhóm phát triển phần mềm tự động hóa quy trình build, kiểm thử và triển khai, để có thể phát hành phần mềm nhanh chóng, an toàn và thường xuyên.\nCuốn sách này đã giành Jolt Excellence Award năm 2011, và được xem là kim chỉ nam cho các tổ chức muốn áp dụng CI/CD (Continuous Integration / Continuous Delivery).', 1, 6, 'active', NULL);
INSERT INTO `ebook` VALUES (7, 'T7.0', 'Release It! — Michael T. Nygard', 450000.00, 'Không chỉ là triển khai phần mềm, mà là thiết kế để vận hành lâu dài trong môi trường sản xuất — nơi có lỗi mạng, tải cao, và các tình huống không lường trước.', 1, 7, 'active', NULL);
INSERT INTO `ebook` VALUES (8, 'T8.0', 'Designing Data-Intensive Applications — Martin Kleppmann', 970000.00, 'Cung cấp các nguyên lý thiết kế hệ thống dữ liệu hiện đại — từ cơ chế lưu trữ, phân tán, đến xử lý batch và stream.\nGiúp người đọc hiểu cách cân bằng giữa độ tin cậy, hiệu suất và khả năng mở rộng.\nLà cuốn “kinh thánh” cho kỹ sư hệ thống, backend, data engineer.\nPhong cách viết sâu sắc, có ví dụ từ thực tế của LinkedIn và Google.', 1, 8, 'active', NULL);
INSERT INTO `ebook` VALUES (9, 'T9.0', 'Site Reliability Engineering (SRE) — Google (tập hợp bài viết)', 0.00, 'Tổng hợp các bài viết từ Google mô tả cách vận hành hạ tầng quy mô toàn cầu.\nTrình bày nguyên tắc SRE, tự động hóa, và đo lường độ tin cậy hệ thống.\nKết hợp giữa triết lý DevOps và thực tiễn sản xuất thực.\nLà tài liệu nền tảng cho mọi kỹ sư vận hành hệ thống lớn.', 1, 9, 'active', NULL);
INSERT INTO `ebook` VALUES (10, 'T10.0', 'The Phoenix Project — Gene Kim, Kevin Behr, George Spafford', 630000.00, 'Một tiểu thuyết mô phỏng câu chuyện chuyển đổi DevOps trong doanh nghiệp.\nGiúp người đọc hiểu cách tổ chức, quản lý và tối ưu quy trình CNTT.\nDễ đọc, thực tế, truyền cảm hứng cho lãnh đạo kỹ thuật.\nPhù hợp cho ai muốn hiểu DevOps không chỉ là công nghệ, mà là văn hóa.', 1, 10, 'active', NULL);
INSERT INTO `ebook` VALUES (11, 'T11.0', 'The DevOps Handbook — Gene Kim et al.', 840000.00, 'Hướng dẫn chi tiết các kỹ thuật triển khai DevOps: CI/CD, automation, monitoring.\nGiải thích cách kết hợp giữa phát triển và vận hành để tăng tốc độ và độ tin cậy.\nCó ví dụ thực tế từ Google, Etsy, Amazon.\nLà “cuốn giáo trình” DevOps chuẩn mực cho kỹ sư phần mềm và quản lý kỹ thuật.', 1, 11, 'active', NULL);
INSERT INTO `ebook` VALUES (12, 'T12.0', 'Introduction to Algorithms — Cormen, Leiserson, Rivest, Stein', 0.00, 'Tác phẩm kinh điển về thuật toán – được dùng trong hầu hết các trường đại học hàng đầu.\nTrình bày chi tiết và chặt chẽ về phân tích độ phức tạp, thiết kế thuật toán.\nCung cấp nền tảng vững chắc để hiểu sâu về lập trình và cấu trúc dữ liệu.\nKhuyên đọc song song với sách bài tập và code mẫu.', 1, 12, 'active', NULL);
INSERT INTO `ebook` VALUES (13, 'T13.0', 'Algorithms (Robert Sedgewick & Kevin Wayne)', 0.00, 'Giới thiệu thuật toán theo hướng trực quan, có hình ảnh minh họa và ví dụ Java.\nThích hợp cho sinh viên và lập trình viên thực hành.\nBao gồm sorting, searching, graph, string, và performance analysis.\nĐi kèm khóa học online nổi tiếng trên Coursera của Princeton.', 1, 13, 'active', NULL);
INSERT INTO `ebook` VALUES (14, 'T14.0', 'Database System Concepts — Silberschatz, Korth, Sudarshan', 0.00, 'Giới thiệu toàn diện các khái niệm cơ bản về hệ quản trị cơ sở dữ liệu.\nBao gồm SQL, thiết kế lược đồ, tối ưu truy vấn, transaction và bảo mật.\nLà tài liệu tiêu chuẩn trong chương trình đại học ngành CNTT.\nGiúp người đọc hiểu sâu cách hoạt động của các hệ DBMS như MySQL, PostgreSQL.', 1, 14, 'active', NULL);
INSERT INTO `ebook` VALUES (15, 'T15.0', 'Designing Distributed Systems — Brendan Burns', 840000.00, 'Trình bày các mẫu thiết kế hệ thống phân tán hiện đại, đặc biệt trong Kubernetes.\nTập trung vào xây dựng dịch vụ cloud-native có khả năng chịu lỗi cao.\nCung cấp các pattern như sidecar, sharding, scatter-gather.\nHữu ích cho kỹ sư Cloud, DevOps, và backend.', 1, 15, 'active', NULL);
INSERT INTO `ebook` VALUES (16, 'T16.0', 'Operating Systems: Three Easy Pieces — Remzi & Andrea Arpaci-Dusseau. UW Computer Sciences', 920000.00, 'Sách kinh điển miễn phí giảng dạy về hệ điều hành.\nGiải thích trực quan cách CPU, bộ nhớ và file system phối hợp.\nCó ví dụ và bài tập thực hành dễ hiểu, được dùng rộng rãi ở nhiều đại học.\nRất phù hợp cho sinh viên IT muốn hiểu OS từ gốc.', 1, 16, 'active', NULL);
INSERT INTO `ebook` VALUES (17, 'T17.0', 'Computer Networks — Andrew S. Tanenbaum / Kurose & Ross', 0.00, 'Giới thiệu cấu trúc mạng máy tính từ tầng vật lý đến ứng dụng.\nBao gồm TCP/IP, routing, bảo mật và các giao thức truyền thông hiện đại.\nLà giáo trình tiêu chuẩn trong lĩnh vực mạng.\nPhong cách viết dễ hiểu, kết hợp lý thuyết và thực hành.', 1, 17, 'active', NULL);
INSERT INTO `ebook` VALUES (18, 'T18.0', 'TCP/IP Illustrated (Vol 1) — W. Richard Stevens', 0.00, 'Trình bày chi tiết cách hoạt động của giao thức TCP/IP với hình minh họa gói tin thực tế.\nGiải thích rõ từng tầng mạng, từ IP, TCP đến ICMP.\nCực kỳ hữu ích cho sinh viên, kỹ sư mạng, và bảo mật.\nPhong cách viết kỹ lưỡng, thực hành và mang tính nghiên cứu sâu.', 1, 18, 'active', NULL);
INSERT INTO `ebook` VALUES (19, 'T19.0', 'The Linux Programming Interface — Michael Kerrisk', 0.00, 'Cẩm nang toàn diện về lập trình hệ thống trong Linux/UNIX.\nTrình bày từ lời gọi hệ thống, tiến trình, thread, IPC, signal đến quản lý bộ nhớ.\nLà tài liệu chuẩn cho lập trình viên hệ thống và backend cấp thấp.\nĐược xem như “Kinh Thánh” cho Linux programmers.', 1, 19, 'active', NULL);
INSERT INTO `ebook` VALUES (20, 'T20.0', 'Practical Object-Oriented Design in Ruby (or equivalent SOLID patterns)', 0.00, 'Giải thích SOLID và nguyên lý thiết kế hướng đối tượng qua ví dụ Ruby dễ hiểu.\nGiúp lập trình viên viết mã linh hoạt, mở rộng dễ dàng, giảm phụ thuộc.\nÁp dụng tốt cho cả Python, Java hoặc bất kỳ ngôn ngữ OOP nào.\nLà tài liệu gối đầu cho ai muốn học clean design thực chiến.', 1, 20, 'active', NULL);
INSERT INTO `ebook` VALUES (21, 'T21.0', 'Patterns of Enterprise Application Architecture — Martin Fowler', 0.00, 'Tổng hợp hơn 40 mẫu thiết kế dành cho các ứng dụng doanh nghiệp lớn.\nBao gồm ORM, transaction, layer separation, repository, service layer.\nLà nền tảng cho các framework như Spring, Hibernate, Django.\nGiúp hiểu sâu hơn về cách thiết kế ứng dụng có khả năng bảo trì và mở rộng cao.', 1, 21, 'active', NULL);
INSERT INTO `ebook` VALUES (22, 'T22.0', 'Domain-Driven Design — Eric Evans', 0.00, 'Giới thiệu triết lý DDD giúp phát triển phần mềm phức tạp bằng mô hình miền rõ ràng.\nTập trung vào ngôn ngữ chung (Ubiquitous Language) và thiết kế hướng miền nghiệp vụ.\nCung cấp kỹ thuật chia nhỏ hệ thống và quản lý phụ thuộc.\nPhù hợp cho kiến trúc sư phần mềm, kỹ sư backend và domain modeler.', 1, 22, 'active', NULL);
INSERT INTO `ebook` VALUES (23, 'T23.0', 'Head First Design Patterns — Eric Freeman et al.', 0.00, 'Cách học Design Patterns bằng hình ảnh, ví dụ thực tế và phong cách vui nhộn.\nGiúp dễ hiểu các pattern nổi tiếng như Singleton, Factory, Observer, Strategy.\nPhiên bản mới đã cập nhật code cho Java 8+.\nCực kỳ hữu ích cho sinh viên và lập trình viên junior.', 1, 23, 'active', NULL);
INSERT INTO `ebook` VALUES (24, 'T24.0', 'Modern Operating Systems — Andrew S. Tanenbaum', 0.00, 'Giới thiệu toàn diện các thành phần của hệ điều hành hiện đại: tiến trình, đồng bộ, bộ nhớ, file system.\nSo sánh chi tiết giữa Windows, UNIX, Android.\nPhù hợp cho sinh viên và người muốn nắm nền tảng vững chắc về OS.\nĐược biên soạn từ kinh nghiệm giảng dạy hàng chục năm của Tanenbaum.', 1, 24, 'active', NULL);
INSERT INTO `ebook` VALUES (25, 'T25.0', 'High Performance Browser Networking — Ilya Grigorik', 920000.00, 'Hướng dẫn tối ưu hiệu suất mạng cho ứng dụng web và mobile.\nGiải thích chi tiết HTTP/2, TLS, WebSockets, và latency optimization.\nCực kỳ phù hợp cho frontend và full-stack developer.\nGiúp hiểu rõ cơ chế truyền dữ liệu giữa trình duyệt và server.', 1, 25, 'active', NULL);
INSERT INTO `ebook` VALUES (26, 'T26.0', 'Systems Performance — Brendan Gregg', 0.00, 'Phân tích hiệu năng hệ thống từ CPU, memory, disk đến network.\nBao gồm kỹ thuật benchmark, tracing, và profiling trên Linux.\nPhù hợp cho DevOps, SRE, cloud engineer muốn tối ưu hiệu năng.\nĐược xem là tài liệu bắt buộc trong lĩnh vực system tuning.', 1, 26, 'active', NULL);
INSERT INTO `ebook` VALUES (27, 'T27.0', 'Effective Java — Joshua Bloch', 0.00, 'Tập hợp hơn 90 lời khuyên thực hành cho lập trình viên Java hiện đại.\nGiải thích kỹ thuật về generics, immutability, concurrency, và lambda.\nĐược viết bởi kiến trúc sư chính của Java Collections.\nLà cuốn “bắt buộc phải đọc” cho mọi Java developer.', 1, 27, 'active', NULL);
INSERT INTO `ebook` VALUES (28, 'T28.0', 'Programming Pearls — Jon Bentley', 0.00, 'Tập hợp các bài viết kinh điển về tư duy lập trình và tối ưu hóa.\nGiúp bạn học cách giải quyết bài toán theo hướng sáng tạo và hiệu quả.\nKết hợp giữa lý thuyết thuật toán và kỹ năng thực hành.\nLà cuốn gối đầu cho lập trình viên yêu thích tư duy sâu.', 1, 28, 'active', NULL);
INSERT INTO `ebook` VALUES (29, 'T29.0', 'Fundamentals of Database Systems — Elmasri & Navathe', 0.00, 'Trình bày chi tiết nguyên lý thiết kế và triển khai cơ sở dữ liệu.\nGiới thiệu ER model, SQL, normalization, transaction và concurrency.\nPhù hợp cho sinh viên và kỹ sư dữ liệu.\nLà giáo trình chuẩn trong nhiều chương trình đại học CNTT.', 1, 29, 'active', NULL);
INSERT INTO `ebook` VALUES (30, 'A1.0', 'Pattern Recognition and Machine Learning — Christopher M. Bishop', 0.00, 'Cung cấp nền tảng toàn diện về học máy và nhận dạng mẫu từ góc Bayesian — phù hợp cho sinh viên cao học hoặc kỹ sư ML. \nBarnes & Noble.\nTrình bày mô hình đồ họa, inference xấp xỉ và nhiều bài tập thực hành: lý thuyết + ứng dụng. \nYêu cầu bạn đã có kiến thức về xác suất và đại số tuyến tính — nhưng vẫn có phần giới thiệu cơ bản. \nPhong cách viết hơi học thuật, phù hợp nếu bạn muốn sâu vào ML nền tảng trước khi đến ứng dụng.', 2, 30, 'active', NULL);
INSERT INTO `ebook` VALUES (31, 'A2.0', 'Machine Learning: A Probabilistic Perspective — Kevin P. Murphy', 0.00, 'Là tài liệu tham khảo toàn diện cho học máy hiện đại theo phương pháp xác suất: mô hình thống kê, graphical models, inference, learning. \n\nDung lượng lớn (~1100 trang) và dành cho người nghiêm túc nghiên cứu hoặc làm ML chuyên nghiệp.\n\nBao gồm nhiều ví dụ thực hành, minh hoạ rõ ràng và thể hiện cách tiếp cận xác suất thống kê trong ML.\n\nPhong cách viết chuyên sâu, nên kết hợp với thực hành code hoặc bài tập để hiểu tốt hơn.', 2, 31, 'active', NULL);
INSERT INTO `ebook` VALUES (32, 'A3.0', 'Hands-On Machine Learning with Scikit-Learn, Keras, and TensorFlow — urélien Géron', 1050000.00, 'Hướng dẫn thực hành ML từ đầu tới nâng cao bằng Python, Scikit-Learn, Keras và TensorFlow. Bao gồm các ví dụ thực tế, dự án mini và workflow toàn diện từ dữ liệu → mô hình → deployment. Phù hợp cho sinh viên, lập trình viên muốn học ML ứng dụng.', 2, 32, 'active', NULL);
INSERT INTO `ebook` VALUES (33, 'A4.0', 'Reinforcement Learning: An Introduction — Richard S. Sutton & Andrew G. arto.', 950000.00, 'Cuốn sách nền tảng về học tăng cường, trình bày lý thuyết, thuật toán và bài toán ứng dụng. Bao gồm MDP, Q-learning, Policy Gradient. Phù hợp cho sinh viên và kỹ sư AI muốn hiểu sâu cơ chế RL.', 2, 33, 'active', NULL);
INSERT INTO `ebook` VALUES (34, 'A5.0', 'Probabilistic Graphical Models — Daphne Koller.', 1200000.00, 'Hướng dẫn xây dựng và áp dụng mô hình đồ thị xác suất trong học máy. Trình bày Bayesian Networks, Markov Random Fields, inference và learning. Dành cho học viên cao học và kỹ sư AI chuyên sâu.', 2, 34, 'active', NULL);
INSERT INTO `ebook` VALUES (35, 'A6.0', 'Bayesian Reasoning and Machine Learning — David Barber (lecture notes / book)', 890000.00, 'Giới thiệu lý thuyết Bayesian và ứng dụng trong học máy. Bao gồm lý thuyết xác suất, inference, mô hình probabilistic. Phong cách học thuật nhưng vẫn minh họa ví dụ dễ hiểu.', 2, 35, 'active', NULL);
INSERT INTO `ebook` VALUES (36, 'A7.0', 'Neural Networks and Deep Learning — Michael Nielsen (online book)', 0.00, 'Cuốn sách online miễn phí, giải thích mạng nơ-ron, backpropagation và deep learning từ cơ bản. Có ví dụ minh họa Python để thực hành. Phù hợp cho người mới bắt đầu muốn tiếp cận DL.', 2, 36, 'active', NULL);
INSERT INTO `ebook` VALUES (37, 'A8.0', 'Natural Language Processing with Transformers — (practical guides)', 980000.00, 'Hướng dẫn xử lý ngôn ngữ tự nhiên hiện đại bằng Transformers. Bao gồm tokenization, fine-tuning, ứng dụng NLP thực tế như chatbots, text classification, và question answering.', 2, 37, 'active', NULL);
INSERT INTO `ebook` VALUES (38, 'A9.0', 'Speech and Language Processing — Jurafsky & Martin', 1100000.00, 'Cung cấp kiến thức cơ bản và nâng cao về NLP và speech processing. Bao gồm n-gram, probabilistic models, deep learning cho NLP, ứng dụng thực tế. Dành cho sinh viên và kỹ sư AI.', 2, 38, 'active', NULL);
INSERT INTO `ebook` VALUES (39, 'A10.0', 'Deep Reinforcement Learning Hands-On — Maxim Lapan', 1020000.00, 'Thực hành học tăng cường sâu với Python và PyTorch. Bao gồm triển khai DQN, Policy Gradient, Actor-Critic. Phù hợp cho lập trình viên muốn xây dựng dự án RL thực tế.', 2, 39, 'active', NULL);
INSERT INTO `ebook` VALUES (40, 'A11.0', 'Computer Vision: Algorithms and Applications — Richard Szeliski (ebook vailable from author/site)', 1200000.00, 'Giới thiệu thuật toán và ứng dụng computer vision: nhận dạng hình ảnh, phát hiện đối tượng, segmentation. Có ví dụ minh họa và thuật toán chi tiết. Phù hợp cho sinh viên và kỹ sư CV.', 2, 40, 'active', NULL);
INSERT INTO `ebook` VALUES (41, 'A12.0', 'Practical Statistics for Data Scientists — Peter Bruce, Andrew Bruce', 850000.00, 'Cung cấp kiến thức thống kê thực hành cho khoa học dữ liệu. Bao gồm descriptive statistics, probability, inference, regression, và visualization. Hướng dẫn trực tiếp áp dụng Python/R.', 2, 41, 'active', NULL);
INSERT INTO `ebook` VALUES (42, 'A13.0', 'The Elements of Statistical Learning — Hastie, Tibshirani, Friedman', 1350000.00, 'Giới thiệu các phương pháp học máy và thống kê hiện đại: regression, classification, boosting, ensemble. Phù hợp cho sinh viên cao học và kỹ sư muốn hiểu nền tảng ML chuyên sâu.', 2, 42, 'active', NULL);
INSERT INTO `ebook` VALUES (43, 'A14.0', 'Introduction to Statistical Learning — Gareth James et al. ', 980000.00, 'Phiên bản dễ tiếp cận hơn của \"The Elements of Statistical Learning\", sử dụng R và ví dụ thực tế. Giúp người mới học ML hiểu cơ bản các thuật toán thống kê.', 2, 43, 'active', NULL);
INSERT INTO `ebook` VALUES (44, 'A15.0', 'Applied Predictive Modeling — Max Kuhn & Kjell Johnson', 950000.00, 'Hướng dẫn xây dựng mô hình dự đoán thực tế, từ dữ liệu thô đến đánh giá mô hình. Bao gồm kỹ thuật preprocessing, feature selection, validation.', 2, 44, 'active', NULL);
INSERT INTO `ebook` VALUES (45, 'A16.0', 'Mathematics for Machine Learning — Marc Peter Deisenroth, A. Aldo Faisal, Cheng Soon Ong.', 880000.00, 'Cung cấp nền tảng toán học cần thiết cho ML: đại số tuyến tính, xác suất, giải tích, tối ưu hóa. Phù hợp cho sinh viên và lập trình viên muốn nắm vững cơ sở lý thuyết.', 2, 45, 'active', NULL);
INSERT INTO `ebook` VALUES (46, 'A17.0', 'Deep Learning for Computer Vision — Adrian Rosebrock (practical)', 1020000.00, 'Thực hành Deep Learning cho Computer Vision: CNN, transfer learning, object detection, segmentation. Có ví dụ Python/PyTorch.', 2, 46, 'active', NULL);
INSERT INTO `ebook` VALUES (47, 'A18.0', 'Generative Deep Learning — David Foster', 1050000.00, 'Giới thiệu mạng sinh tạo (GANs), VAE, và các kỹ thuật tạo dữ liệu mới. Phù hợp cho lập trình viên DL muốn thử nghiệm dự án sáng tạo.', 2, 47, 'active', NULL);
INSERT INTO `ebook` VALUES (48, 'A19.0', 'Reinforcement Learning by Example — (various practical books)', 950000.00, 'Hướng dẫn RL qua ví dụ Python thực hành: Q-learning, DQN, Policy Gradient. Phù hợp cho người muốn làm dự án RL nhanh.', 2, 48, 'active', NULL);
INSERT INTO `ebook` VALUES (49, 'A20.0', 'Bayesian Data Analysis — Gelman et al.', 1200000.00, 'Cung cấp lý thuyết và ứng dụng phân tích dữ liệu theo phương pháp Bayesian. Bao gồm inference, MCMC, model checking. Dành cho nghiên cứu sinh và kỹ sư dữ liệu nâng cao.', 2, 49, 'active', NULL);
INSERT INTO `ebook` VALUES (50, 'A21.0', 'Feature Engineering for Machine Learning — (various)', 890000.00, 'Hướng dẫn tạo, chọn và xử lý feature để nâng cao hiệu quả mô hình ML. Bao gồm numeric, categorical, text, và thời gian.', 2, 50, 'active', NULL);
INSERT INTO `ebook` VALUES (51, 'A22.0', 'Machine Learning Yearning — Andrew Ng (free ebook/notes)', 0.00, 'Ebook miễn phí của Andrew Ng, hướng dẫn cách thiết kế hệ thống ML hiệu quả. Bao gồm chiến lược thu thập dữ liệu, cải thiện mô hình, ưu tiên dự án ML.', 2, 51, 'active', NULL);
INSERT INTO `ebook` VALUES (52, 'A23.0', 'Hands-On Reinforcement Learning with Python — (practical)', 1020000.00, 'Thực hành RL với Python, bao gồm DQN, Policy Gradient và Actor-Critic. Có hướng dẫn dự án thực tế. Phù hợp lập trình viên muốn xây dựng mô hình RL ứng dụng.', 2, 52, 'active', NULL);
INSERT INTO `ebook` VALUES (53, 'A24.0', 'Applied Deep Learning — Umberto Michelucci (or similar)', 1080000.00, 'Giới thiệu các kỹ thuật deep learning nâng cao và ứng dụng thực tế. Bao gồm CNN, RNN, LSTM và deployment mô hình.', 2, 53, 'active', NULL);
INSERT INTO `ebook` VALUES (54, 'A25.0', 'Introduction to Information Retrieval — Manning, Raghavan, Schütze.', 950000.00, 'Hướng dẫn xây dựng hệ thống tìm kiếm thông tin, xử lý văn bản và indexing. Bao gồm các thuật toán IR, ranking, evaluation metrics.', 2, 54, 'active', NULL);
INSERT INTO `ebook` VALUES (55, 'A26.0', 'Algorithms for Optimization — (useful for ML)', 880000.00, 'Giới thiệu các thuật toán tối ưu hóa sử dụng trong học máy và AI. Bao gồm gradient descent, convex optimization, heuristic search.', 2, 55, 'active', NULL);
INSERT INTO `ebook` VALUES (56, 'A27.0', 'Foundations of Machine Learning — Mohri, Rostamizadeh, Talwalkar', 970000.00, 'Cung cấp nền tảng lý thuyết học máy: supervised, unsupervised, generalization, PAC learning. Phù hợp cho sinh viên và kỹ sư muốn hiểu cơ bản ML.', 2, 56, 'active', NULL);
INSERT INTO `ebook` VALUES (57, 'A28.0', 'An Introduction to Statistical Learning with Applications in R.', 980000.00, 'Phiên bản thực hành bằng R của \"Introduction to Statistical Learning\". Bao gồm regression, classification, resampling, model selection.', 2, 57, 'active', NULL);
INSERT INTO `ebook` VALUES (58, 'A29.0', 'Practical Deep Learning for Cloud, Mobile, and Edge.', 1050000.00, 'Hướng dẫn triển khai deep learning trên cloud, thiết bị di động và edge. Bao gồm model compression, TensorFlow Lite, ONNX.', 2, 58, 'active', NULL);
INSERT INTO `ebook` VALUES (59, 'S1.0', 'University Physics (OpenStax) — Giải tích/đại cương\n', 0.00, 'Giáo trình vật lý đại cương, bao gồm cơ học, điện từ, nhiệt động lực học, sóng và quang học. Miễn phí PDF, phù hợp sinh viên đại học.', 3, 59, 'active', NULL);
INSERT INTO `ebook` VALUES (60, 'S2.0', 'College Physics (OpenStax).\n', 0.00, 'Vật lý đại cương dành cho sinh viên, bao gồm cơ học, nhiệt, điện, từ, quang học. Phiên bản dễ tiếp cận, miễn phí PDF.', 3, 60, 'active', NULL);
INSERT INTO `ebook` VALUES (61, 'S3.0', 'A Brief History of Time — Stephen Hawking.\n', 620000.00, 'Giải thích các khái niệm vật lý phức tạp như vũ trụ, thời gian, lỗ đen, Big Bang bằng ngôn ngữ dễ hiểu. Phù hợp độc giả phổ thông yêu thích khoa học.', 3, 61, 'active', NULL);
INSERT INTO `ebook` VALUES (62, 'S4.0', 'The Selfish Gene — Richard Dawkins.\n', 580000.00, 'Giải thích cơ chế tiến hóa và gene bằng ngôn ngữ dễ hiểu, giới thiệu khái niệm “gene ích kỷ”. Phù hợp độc giả phổ thông và sinh viên sinh học.', 3, 62, 'active', NULL);
INSERT INTO `ebook` VALUES (63, 'S5.0', 'The Gene: An Intimate History — Siddhartha Mukherjee\n', 680000.00, 'Lịch sử khám phá gene và di truyền học, từ Mendel đến CRISPR. Kể chuyện sinh động, kết hợp khoa học và câu chuyện cá nhân.', 3, 63, 'active', NULL);
INSERT INTO `ebook` VALUES (64, 'S6.0', 'Principles of Neural Science — Kandel et al.', 1800000.00, 'Giáo trình chuẩn về khoa học thần kinh, giải thích cấu trúc, chức năng và cơ chế của hệ thần kinh. Dành cho sinh viên, nghiên cứu sinh và chuyên gia.', 3, 64, 'active', NULL);
INSERT INTO `ebook` VALUES (65, 'S7.0', 'Molecular Biology of the Cell — Alberts et al.\n', 1750000.00, 'Giáo trình chi tiết về sinh học phân tử và tế bào: DNA, RNA, protein, signaling pathways. Phù hợp sinh viên đại học và nghiên cứu sinh.', 3, 65, 'active', NULL);
INSERT INTO `ebook` VALUES (66, 'S8.0', 'Physical Chemistry — Atkins (textbook)\n', 1600000.00, 'Textbook về hóa lý, bao gồm thermodynamics, kinetics, quantum chemistry và spectroscopy. Dành cho sinh viên hóa học và kỹ sư.', 3, 66, 'active', NULL);
INSERT INTO `ebook` VALUES (67, 'S9.0', 'The Structure of Scientific Revolutions — Thomas S. Kuhn\n', 520000.00, 'Phân tích cách các lý thuyết khoa học thay đổi theo thời gian, giới thiệu khái niệm “paradigm shift”. Phù hợp độc giả khoa học và triết học.', 3, 67, 'active', NULL);
INSERT INTO `ebook` VALUES (68, 'S10.0', 'Chaos: Making a New Science — James Gleick\n', 550000.00, 'Giới thiệu khoa học hỗn loạn (chaos theory), fractals, và các ứng dụng trong vật lý, sinh học, khí tượng. Viết lôi cuốn cho độc giả phổ thông.', 3, 68, 'active', NULL);
INSERT INTO `ebook` VALUES (69, 'S11.0', 'Six Easy Pieces — Richard Feynman (free/part of Feynman Lectures)\n', 0.00, 'Tuyển tập bài giảng cơ bản về vật lý của Richard Feynman, giải thích dễ hiểu các nguyên lý cơ bản. Miễn phí PDF có sẵn.', 3, 69, 'active', NULL);
INSERT INTO `ebook` VALUES (70, 'S12.0', 'Conceptual Physics — Paul G. Hewitt\n', 450000.00, 'Giới thiệu vật lý cơ bản bằng cách trực quan, tập trung vào khái niệm hơn là toán học. Phù hợp học sinh và sinh viên mới bắt đầu.', 3, 70, 'active', NULL);
INSERT INTO `ebook` VALUES (71, 'S13.0', 'Theoretical Minimum series — Leonard Susskind (modern physics primers)\n', 520000.00, 'Phân tích các hiện tượng khoa học trong Star Trek, giải thích cơ học, năng lượng và lý thuyết vũ trụ. Vừa học vừa giải trí cho độc giả yêu khoa học.', 3, 71, 'active', NULL);
INSERT INTO `ebook` VALUES (72, 'S14.0', 'Statistical Mechanics — Kerson Huang (textbook)\n', 980000.00, 'Textbook chi tiết về cơ học thống kê: phân bố Boltzmann, ensembles, phase transitions. Phù hợp sinh viên vật lý và kỹ sư.', 3, 72, 'active', NULL);
INSERT INTO `ebook` VALUES (73, 'S15.0', 'Introduction to Electrodynamics — David J. Griffiths\n', 950000.00, 'Giáo trình cơ bản về điện từ học: Maxwell equations, fields, potentials, waves. Phù hợp sinh viên vật lý đại học và kỹ sư điện.', 3, 73, 'active', NULL);
INSERT INTO `ebook` VALUES (74, 'S16.0', 'Classical Mechanics — John R. Taylor\n', 890000.00, 'Textbook về cơ học cổ điển: Newton, Lagrangian, Hamiltonian, motion, dynamics. Phù hợp sinh viên vật lý và kỹ sư cơ khí.', 3, 74, 'active', NULL);
INSERT INTO `ebook` VALUES (75, 'S17.0', 'Evolution: The Modern Synthesis — Julian Huxley (or modern equivalents)', 600000.00, 'Tác phẩm kinh điển của Charles Darwin, giải thích thuyết chọn lọc tự nhiên. Phù hợp độc giả phổ thông và sinh viên sinh học.', 3, 75, 'active', NULL);
INSERT INTO `ebook` VALUES (76, 'S18.0', 'On the Origin of Species — Charles Darwin.', 580000.00, 'Câu chuyện về khám phá cấu trúc DNA của James D. Watson, kể về hành trình khoa học, cạnh tranh và con người phía sau nghiên cứu.', 3, 76, 'active', NULL);
INSERT INTO `ebook` VALUES (77, 'S19.0', 'The Double Helix — James D. Watson.\n', 620000.00, 'Câu chuyện về khám phá cấu trúc DNA của James D. Watson, kể về hành trình khoa học, cạnh tranh và con người phía sau nghiên cứu.', 3, 77, 'active', NULL);
INSERT INTO `ebook` VALUES (78, 'S20.0', 'The Immortal Life of Henrietta Lacks — Rebecca Skloot.\n', 590000.00, 'Kể câu chuyện về Henrietta Lacks và tế bào HeLa, kết hợp y học, đạo đức và lịch sử khoa học. Phù hợp độc giả phổ thông.', 3, 78, 'active', NULL);
INSERT INTO `ebook` VALUES (79, 'S21.0', 'Biochemistry — Berg, Tymoczko, Stryer.\n', 1750000.00, 'Textbook chi tiết về sinh hóa học: enzyme, metabolism, DNA/RNA, protein structure. Dùng cho sinh viên đại học và nghiên cứu sinh.', 3, 79, 'active', NULL);
INSERT INTO `ebook` VALUES (80, 'S22.0', 'Astronomy: Principles and Practice — (various textbooks).\n', 900000.00, 'Giáo trình thiên văn học cơ bản, bao gồm hệ mặt trời, sao, thiên hà, vũ trụ học. Phù hợp sinh viên và độc giả yêu thích thiên văn.', 3, 80, 'active', NULL);
INSERT INTO `ebook` VALUES (81, 'S23.0', 'The Physics of Star Trek — Lawrence Krauss (popular science)\n', 520000.00, 'Phân tích các hiện tượng khoa học trong Star Trek, giải thích cơ học, năng lượng và lý thuyết vũ trụ. Vừa học vừa giải trí.', 3, 81, 'active', NULL);
INSERT INTO `ebook` VALUES (82, 'S24.0', 'Physical Biology of the Cell — Rob Phillips et al.\n', 1600000.00, 'Kết hợp sinh học và vật lý để giải thích cơ chế tế bào, cytoskeleton, membrane, signaling và energy. Phù hợp sinh viên sinh học và kỹ sư y sinh.', 3, 82, 'active', NULL);
INSERT INTO `ebook` VALUES (83, 'S25.0', 'Introduction to Quantum Mechanics — David J. Griffiths (textbook)\n', 980000.00, 'Giáo trình cơ bản về cơ học lượng tử, bao gồm Schrodinger equation, operators, quantum states. Dành cho sinh viên vật lý đại học và cao học.', 3, 83, 'active', NULL);
INSERT INTO `ebook` VALUES (84, 'S26.0', ' Transport Phenomena — Bird, Stewart, Lightfoot (engineering text)\n', 1400000.00, 'Textbook kỹ thuật về truyền nhiệt, truyền khối và động lực chất lỏng. Bao gồm lý thuyết, ví dụ thực tế và bài tập. Phù hợp sinh viên kỹ thuật hóa học và cơ khí.', 3, 84, 'active', NULL);
INSERT INTO `ebook` VALUES (85, 'S27.0', 'General Chemistry — OpenStax (PDF available)\n', 0.00, 'Giáo trình hóa học đại cương miễn phí, bao gồm hóa học vô cơ, hữu cơ cơ bản, thermodynamics và kinetics. Thích hợp sinh viên đại học mới học.', 3, 85, 'active', NULL);
INSERT INTO `ebook` VALUES (86, 'S28.0', 'Common Science & other historical science texts — available at Project \n', 0.00, 'Tập hợp các văn bản khoa học cổ điển và lịch sử, bao gồm các công trình của Newton, Galileo, v.v. Dùng cho nghiên cứu lịch sử khoa học và giáo dục.', 3, 86, 'active', NULL);
INSERT INTO `ebook` VALUES (87, 'S29.0', 'Science: A Collection Of Quotes From Albert Einstein, Carl Sagan, Charles Darwin, Michio Kaku, Neil deGrasse Tyson, Nikola Tesla, Richard Dawkins, Richard Feynman, Stephen Hawking And Many More!', 550000.00, 'Tuyển tập các bài viết và bài giảng phổ biến về khoa học từ Sagan, Dawkins, v.v. Giúp người đọc phổ thông hiểu các khái niệm khoa học phức tạp.', 3, 87, 'active', NULL);
INSERT INTO `ebook` VALUES (88, 'S30.0', 'Special Relativity and Classical Field Theory The Theoretical Minimum', 0.00, 'Cuốn sách này thuộc loạt \"The Theoretical Minimum\" của Leonard Susskind, cung cấp một nền tảng toán học vững chắc về thuyết tương đối rộng, phù hợp cho những ai muốn hiểu sâu về vật lý lý thuyết. ', 3, 88, 'active', NULL);
INSERT INTO `ebook` VALUES (89, 'S31.0', 'Introduction to Statistical Physics', 0.00, 'Kerson Huang giới thiệu về vật lý thống kê, bao gồm các chủ đề như entropy, phân bố Boltzmann, và lý thuyết chuyển pha, với ứng dụng trong các hệ vi mô và vĩ mô.   ', 3, 89, 'active', NULL);
INSERT INTO `ebook` VALUES (90, 'S32.0', 'Classical Mechanics: A Modern Perspective', 950000.00, 'Cuốn sách của Herbert Goldstein cung cấp cái nhìn hiện đại về cơ học cổ điển, bao gồm lý thuyết Lagrangian và Hamiltonian, với nhiều bài tập minh họa và ứng dụng thực tế.', 3, 90, 'active', NULL);
INSERT INTO `ebook` VALUES (91, 'T1.0', 'Pons General Reference – Trilingual Visual Dictionary', 304000.00, '“Từ điển cung cấp trên 16.000 từ, cụm từ cùng 3.000 hình màu minh họa. Các từ và cụm từ được sắp xếp theo chủ đề gắn liền với các lĩnh vực quan trọng trong cuộc sống. … Tất cả các từ vựng đều có phần phiên âm để giúp bạn phát âm chính xác. Mục ‘Các cách diễn đạt cần thiết’ trang bị cho bạn những mẫu câu quan trọng nhất, kèm theo đó là danh mục khoảng 2.000 động từ để hỗ trợ bạn đặt câu.”', 4, 91, 'active', NULL);
INSERT INTO `ebook` VALUES (92, 'T2.0', 'Vietnamese‑English Dictionary', 300000.00, '“A handy and affordable Vietnamese to English and English to Vietnamese reference dictionary for everyday use, including short grammars of Vietnamese and English. … 30,000 translations. Designed for all those studying Vietnamese and English… Offers comprehensive and up-to-date coverage of Vietnamese and English.”', 4, 92, 'active', NULL);
INSERT INTO `ebook` VALUES (93, 'T3.0', 'A History of the Vietnamese', 0.00, 'Sách chuyên sâu về lịch sử người Việt – sách nhập khẩu', 4, 93, 'active', NULL);
INSERT INTO `ebook` VALUES (94, 'T4.0', 'Collins Vietnamese Dictionary Essential Edition', 260000.00, '“Extensive and up-to-date coverage of Vietnamese and English in a portable format, with a handy supplement of essential grammar points for each language. Designed for all those studying Vietnamese and English, whether at school, for travel or for business.”', 4, 94, 'active', NULL);
INSERT INTO `ebook` VALUES (95, 'T5.0', 'The Rough Guide to Vietnam: Travel Guide with eBook', 620000.00, 'This practical travel guide to Vietnam features detailed factual travel tips and points-of-interest structured lists of all iconic must-see sights as well as some off-the-beaten-track treasures… The guide book has been fully updated post-COVID-19 and it comes with a free eBook.', 4, 95, 'active', NULL);
INSERT INTO `ebook` VALUES (96, 'T6.0', 'Pons General Reference ‑ Trilingual Visual Dictionary', 300000.00, 'Từ điển hình ảnh 3-ngôn ngữ (Anh-Việt-…)', 4, 96, 'active', NULL);
INSERT INTO `ebook` VALUES (97, 'T7.0', 'The Elements of Style', 128000.00, '“This style manual offers practical advice on improving writing skills. Throughout, the emphasis is on promoting a plain English style… It is a timeless guide to effective writing, offering clear and concise rules for clarity, brevity, and effective communication.”', 4, 97, 'active', NULL);
INSERT INTO `ebook` VALUES (98, 'T8.0', 'Introduction to Algorithms (CLRS)', 0.00, 'Introduction to Algorithms uniquely combines rigor and comprehensiveness. The book covers a broad range of algorithms in depth, yet makes their design and analysis accessible.', 4, 98, 'active', NULL);
INSERT INTO `ebook` VALUES (99, 'T9.0', 'How to Solve It – George Pólya', 0.00, 'How to Solve It is a small volume … describing methods of problem solving.', 4, 99, 'active', NULL);
INSERT INTO `ebook` VALUES (100, 'T10.0', 'Oxford English Dictionary', 560000.00, 'The Oxford Collocations Dictionary shows which words work together. It helps students express their ideas naturally and convincingly and it is particularly useful for academic and report writing.\r\nWith the Oxford Collocations Dictionary, students learn the most frequently used word combinations in British and American English. The dictionary also guides them to the right combination for their context. The two-year app access includes the complete dictionary.', 4, 100, 'active', NULL);
INSERT INTO `ebook` VALUES (101, 'T11.0', 'Oxf Essential Dictionary (3rd Edition)', 37000.00, 'Oxford Essential Dictionary gives all the essential help and information elementary and pre-intermediate learners need.', 4, 101, 'active', NULL);
INSERT INTO `ebook` VALUES (102, 'T12.0', 'Oxford Phrasal Verbs Dictionary', 171000.00, 'Presents the information students need to understand common British and American phrasal verbs. This dictionary shows common subjects and objects to help learners use the verbs. It includes 25 pages of tips and photocopiable exercises for practice. \'Guide to the Particles\' explains the important meanings of the main adverbs and prepositions.', 4, 102, 'active', NULL);
INSERT INTO `ebook` VALUES (103, 'T13.0', 'Oxford Basic English Dictionary 5th Edition', 158000.00, 'An easy, illustrated dictionary for students beginning to learn English. Updated with hundreds of new words, the Oxford Student\'s Dictionary is a corpus-based dictionary with the curricular, academic and general English vocabulary students need to know to study other subjects in English. It helps students prepare for international exams such as TOEFL(R) and IELTS. The CD-ROM includes the complete dictionary and allows students to search for words by subject or topic and to create their own word lists in the My Topics Dictionary. NEW on the CD-ROM: the iGuide, an interactive tutorial to help students explore dictionary entries.', 4, 103, 'active', NULL);
INSERT INTO `ebook` VALUES (104, 'T14.0', 'Oxford Learner\'s Spanish Dictionary', 285000.00, 'This new edition has been fully revised and updated to offer up -to-date vocabulary and language support for student\'s learning Spanish at GCSE and beyond. All the current exam board vocabulary is included and curriculum words are flagged with a key symbol. Word Tips provide information on common grammatical errors and confusable words, while interesting cultural information is specially picked out in Culture boxes. To support students building their range of vocabulary and get them using it confidently, all words are also given in appropriate example sentences so that students can see how to use them correctly. Extra grammar support is given with full verb tables, including English translations of the different tenses, to help with translating to and from Spanish. In the centre of the dictionary, the illustrated thematic supplement includes questions, answers, comments and phrases and photocard activities to model those faced by students in their exams, It has a contemporary look and feel and covers topics such as technology, free-time activities, customs and festivals, social and global issues, travel and tourism, current and future study and employment.', 4, 104, 'active', NULL);
INSERT INTO `ebook` VALUES (105, 'T15.0', 'Macmillan Dictionary Vietnam ED', 398000.00, 'Macmillan English Dictionary helps students with words that are needed for communicating in English, and offers invaluable support for those who want to write and speak accurate and contemporary English… Over 100,000 references and 80,000 examples.', 4, 105, 'active', NULL);
INSERT INTO `ebook` VALUES (106, 'T16.0', 'My First Picture Dictionary', 820500.00, '“Includes over 900 words and definitions organized by situations common to a preschooler’s world… Designed to educate and entertain, My First Picture Dictionary will help develop early learning skills and launch your children’s interest in reading and the world around them.”', 4, 106, 'active', NULL);
INSERT INTO `ebook` VALUES (107, 'T17.0', 'Oxford Essential Dictionary - New Ed - W/CD-Rom', 305000.00, 'Oxford Essential Dictionary gives all the essential help and information elementary and pre-intermediate learners need. Updated with 200 NEW words, Oxford Essential Dictionary includes over 24,000 words, phrases, and meanings. 2,000 of the most important words in English are marked as keywords, so students know which words to learn first. Notes give extra help with grammar, pronunciation, and spelling. The CD-ROM includes the full dictionary, Picture Dictionary, exam preparation (KET) exercises, language games, a Speaking Dictionary, and NEW iGuide, an interactive tutorial to help students explore dictionary entries.', 4, 107, 'active', NULL);
INSERT INTO `ebook` VALUES (108, 'T18.0', 'Oxford Picture Dictionary Third Edition: English - Vietnamese Edition', 390450.00, 'Illustrations present over 4,000 English words and phrases within meaningful, real-life contexts 11 new and expanded topics including Job Search, Career Planning, and Digital Literacy prepare students to meet the requirements of their daily lives Updated activities prepare students for work, academic study, and citizenship Oxford 3000™ vocabulary ensures students learn the most useful and important words', 4, 108, 'active', NULL);
INSERT INTO `ebook` VALUES (109, 'T19.0', 'Global Success - Tiếng Anh 12 - Sách Học Sinh (2024)', 67200.00, 'Global Success - Tiếng Anh 12 - Sách Học Sinh được Nhà xuất bản Giáo dục Việt Nam tổ chức biên soạn theo “Chương trình giáo dục phổ thông: Chương trình môn Tiếng Anh” (từ lớp 3 đến lớp 12) ban hành theo Thông tư 32/2018/TT-BGDĐT ngày 26 tháng 12 năm 2018 của Bộ Giáo dục và Đào tạo, nối tiếp bộ sách tiếng Anh bậc tiểu học (Tiếng Anh 3, Tiếng Anh 4, Tiếng Anh 5), bộ sách tiếng Anh trung học cơ sở (Tiếng Anh 6, Tiếng Anh 7, Tiếng Anh 8, Tiếng Anh 9, Tiếng Anh 10) và Tiếng Anh 11.', 4, 109, 'active', NULL);
INSERT INTO `ebook` VALUES (110, 'T20.0', '500 Bài Toán Cơ Bản Và Nâng Cao Lớp 5', 61500.00, 'Cuốn sách \"500 BÀI TOÁN CƠ BẢN VÀ N NG CAO, ĐÁNH GIÁ NĂNG LỰC PHÁT TRIỂN TƯ DUY LỚP 5” nhằm giúp các em học sinh khá, giỏi lớp 5 có một tài liệu Toán nâng cao giúp đánh giá năng lực, khơi dậy tư duy Toán học và phát triển trí thông minh.', 4, 110, 'active', NULL);
INSERT INTO `ebook` VALUES (111, 'T21.0', 'Principles of Mathematical Analysis — Walter Rudin', 0.00, 'Cuốn sách này — thường được biết đến dưới biệt danh “Baby Rudin” — là một giáo trình kinh điển về phân tích thực, dành cho sinh viên toán nâng cao và năm đầu cao học. Nội dung gồm hệ số thực (construction of the real numbers), không gian metric, chuỗi và séries, hàm số, đạo hàm, tích phân, và đôi khi mở rộng tới lý thuyết Lebesgue. Phong cách thể hiện rất cô đọng và nghiêm túc — ít hình minh họa, nhiều chứng minh ngắn gọn nhưng đòi hỏi người đọc phải suy nghĩ sâu. Đây là lựa chọn lý tưởng nếu bạn muốn rèn kỹ năng chứng minh và hiểu bản chất toán học, nhưng không phải cuốn nhẹ nhàng cho người mới bắt đầu.', 4, 111, 'active', NULL);
INSERT INTO `ebook` VALUES (112, 'T22.0', 'Advanced Engineering Mathematics', 0.00, 'Đây là cuốn giáo trình toàn diện hướng tới sinh viên kỹ thuật, vật lý, khoa học máy tính và các ngành liên quan. Nội dung rất đa dạng: từ phương trình vi phân thường, đại số tuyến tính, tới phân tích phức, Fourier, phương trình đạo hàm riêng (PDE), số học số và các ứng dụng thực tiễn. Cuốn sách được đánh giá cao vì phạm vi rộng, bài tập phong phú và tính ứng dụng mạnh — phù hợp để sử dụng như giáo trình hoặc tài liệu tham khảo dài hạn. Nếu bạn học ngành kỹ thuật hoặc khoa học ứng dụng và muốn một nguồn “tất cả trong một” để ôn tập toán cao cấp, đây là lựa chọn rất đáng cân nhắc.', 4, 112, 'active', NULL);
INSERT INTO `ebook` VALUES (113, 'T23.0', 'Artificial Intelligence: A Modern Approach — Russell & Norvig', 0.00, 'Đây là giáo trình chuẩn mực và toàn diện nhất về trí tuệ nhân tạo. Sách giới thiệu khái niệm “tác nhân thông minh” và cách chúng học hỏi, lập kế hoạch, ra quyết định và tương tác với môi trường. Nội dung bao quát từ tìm kiếm, logic, suy luận, xác suất, học máy, mạng nơ-ron, đến xử lý ngôn ngữ tự nhiên. Phong cách trình bày hệ thống, chặt chẽ nhưng dễ hiểu. Cuốn sách này được giảng dạy tại hầu hết các chương trình đại học về AI và là nền tảng cho bất kỳ ai muốn nghiên cứu hoặc làm việc trong lĩnh vực này.', 4, 113, 'active', NULL);
INSERT INTO `ebook` VALUES (114, 'T24.0', 'The Lean Startup – Eric Ries', 450000.00, 'Most startups fail. But many of those failures are preventable. The Lean Startup is a new approach being adopted across the globe, changing the way companies are built and new products are launched. … Eric Ries defines a startup as an organization dedicated to creating something new under conditions of extreme uncertainty.', 4, 114, 'active', NULL);
INSERT INTO `ebook` VALUES (115, 'T25.0', 'Principles – Ray Dalio', 750000.00, 'Ray Dalio, nhà sáng lập quỹ đầu tư Bridgewater Associates, chia sẻ những nguyên tắc sống và làm việc đã giúp ông đạt được thành công lớn. Ông nhấn mạnh tầm quan trọng của “minh bạch triệt để” và “trung thực triệt để” trong tổ chức, cũng như việc ra quyết định dựa trên dữ liệu và phản hồi thực tế. Cuốn sách được chia thành hai phần: nguyên tắc sống và nguyên tắc công việc, kết hợp triết lý cá nhân với kinh nghiệm lãnh đạo. Đây là tác phẩm mang tính hướng dẫn tư duy chiến lược và phát triển bản thân sâu sắc.', 4, 115, 'active', NULL);
INSERT INTO `ebook` VALUES (116, 'T26.0', 'Thinking, Fast and Slow – Daniel Kahneman', 600000.00, 'Nhà tâm lý học đạt giải Nobel Daniel Kahneman giới thiệu hai hệ thống tư duy chi phối mọi quyết định của con người: hệ thống 1 – nhanh, trực giác và cảm tính; hệ thống 2 – chậm, lý trí và có chủ đích. Qua hàng chục năm nghiên cứu, ông chỉ ra cách những sai lệch nhận thức và “bẫy tư duy” khiến ta ra quyết định thiếu chính xác. Cuốn sách vừa sâu sắc vừa dễ tiếp cận, giúp người đọc hiểu rõ hơn về hành vi, đánh giá rủi ro và cải thiện cách suy nghĩ trong công việc và cuộc sống.', 4, 116, 'active', NULL);
INSERT INTO `ebook` VALUES (117, 'T27.0', 'Physics for Scientists and Engineers – Serway & Jewett', 0.00, 'Giáo trình vật lý nổi tiếng dành cho sinh viên các ngành khoa học và kỹ thuật. Sách trình bày toàn diện về cơ học, nhiệt động lực học, điện từ học, quang học và vật lý hiện đại. Mỗi chương được thiết kế với phần lý thuyết rõ ràng, ví dụ minh họa cụ thể và bài tập đa dạng giúp người học củng cố kiến thức. Điểm mạnh của sách là tính logic, chính xác và khả năng kết nối giữa công thức với hiện tượng vật lý thực tế. Đây là tài liệu nền tảng cho nhiều khóa học vật lý đại học.', 4, 117, 'active', NULL);
INSERT INTO `ebook` VALUES (118, 'T28.0', 'Campbell Biology – Reece et al.', 0.00, 'Cuốn sách sinh học phổ biến nhất thế giới dành cho sinh viên đại học, được mệnh danh là “kinh thánh” của ngành sinh học. Tác phẩm trình bày từ cấp độ phân tử, tế bào đến sinh thái học và tiến hóa. Cách viết sinh động, minh họa đẹp, dễ hiểu và cập nhật các phát hiện khoa học mới nhất. Campbell Biology không chỉ giúp người đọc nắm vững kiến thức cơ bản mà còn khơi dậy niềm yêu thích nghiên cứu sinh học. Sách thường được dùng trong các chương trình đại học hàng đầu về khoa học tự nhiên.', 4, 118, 'active', NULL);
INSERT INTO `ebook` VALUES (119, 'T29.0', 'Mechanics of Materials – Hibbeler', 0.00, 'Cuốn sách chuyên sâu về cơ học vật liệu, tập trung vào mối quan hệ giữa ứng suất, biến dạng và đặc tính cơ học của vật thể. Nội dung bao gồm lý thuyết về thanh dầm, xoắn, uốn, ổn định cột và năng lượng biến dạng. Phong cách trình bày dễ hiểu, trực quan và giàu ví dụ thực tiễn, giúp sinh viên kỹ thuật nắm chắc nền tảng cơ học kết cấu. Đây là giáo trình tiêu chuẩn tại các trường kỹ thuật, được đánh giá cao nhờ tính chính xác, hệ thống bài tập đa dạng và khả năng áp dụng vào thiết kế thực tế.', 4, 119, 'active', NULL);
INSERT INTO `ebook` VALUES (120, 'T30.0', 'Pedagogy of the Oppressed – Paulo Freire', 450000.00, 'Tác phẩm kinh điển trong lĩnh vực giáo dục và xã hội học, nhấn mạnh vai trò của giáo dục như một công cụ giải phóng con người khỏi áp bức. Paulo Freire phê phán mô hình giáo dục “ngân hàng”, nơi học sinh chỉ tiếp thu thụ động, và đề xuất phương pháp “đối thoại” – nơi người học cùng tham gia sáng tạo tri thức. Sách mang tính nhân văn sâu sắc, kêu gọi sự thức tỉnh, hợp tác và tự nhận thức trong quá trình học tập. Đây là nền tảng của giáo dục tiến bộ và tư tưởng phản kháng hiện đại.', 4, 120, 'active', NULL);
INSERT INTO `ebook` VALUES (121, 'T31.0', 'Atomic Habits – James Clear', 400000.00, 'Atomic Habits by James Clear is a comprehensive, practical guide on how to change your habits and get 1% better every day. Using a framework called the Four Laws of Behavior Change, Atomic Habits teaches readers a simple set of rules for creating good habits and breaking bad ones. Read the full summary to glean 3 key lessons from Atomic Habits, learn how to build a habit in 4 simple steps, and get a handy reference guide for the strategies recommended throughout the book.', 4, 121, 'active', NULL);
INSERT INTO `ebook` VALUES (122, 'T1.0', 'Merriam‑Webster’s Advanced Learner’s English Dictionary   ', 736000.00, 'Từ điển tiếng Anh nâng cao được biên soạn đặc biệt cho người học tiếng Anh như ngôn ngữ thứ hai. Sách cung cấp hơn 100.000 từ và cụm từ, cùng cách phát âm, ví dụ sử dụng trong ngữ cảnh thực tế và giải thích nghĩa rõ ràng. Phần hướng dẫn ngữ pháp, collocation và idioms giúp người học cải thiện khả năng sử dụng tiếng Anh tự nhiên hơn. Từ điển này phù hợp cho học sinh, sinh viên, giáo viên và những ai muốn mở rộng vốn từ học thuật và giao tiếp chuyên nghiệp.', 5, 122, 'active', NULL);
INSERT INTO `ebook` VALUES (123, 'T2.0', 'Macmillan English Dictionary for Advanced Learners   ', 715000.00, 'Từ điển này được thiết kế dành riêng cho người học tiếng Anh ở trình độ trung cấp đến nâng cao. Điểm nổi bật là định nghĩa rõ ràng, sử dụng ngôn ngữ đơn giản, nhiều ví dụ thực tế và ghi chú về cách dùng từ trong ngữ cảnh học thuật, giao tiếp hoặc viết chuyên nghiệp. Ngoài ra, sách còn cung cấp thông tin về collocations, phrasal verbs, idioms và từ vựng theo chủ đề. Giao diện dễ tra cứu, phần hướng dẫn phát âm chuẩn quốc tế giúp người học mở rộng vốn từ và cải thiện khả năng diễn đạt tự nhiên.', 5, 123, 'active', NULL);
INSERT INTO `ebook` VALUES (124, 'T3.0', 'English Vocabulary in Use Upper‑Intermediate 3rd Edition  \n', 183000.00, 'Thuộc bộ sách nổi tiếng của Cambridge, cuốn “English Vocabulary in Use” ở trình độ Upper-Intermediate giúp người học mở rộng vốn từ vựng theo chủ đề và ngữ cảnh. Mỗi bài học gồm phần trình bày nghĩa, ví dụ minh họa, và bài tập tự luyện ở trang đối diện. Cấu trúc trực quan, dễ tiếp cận, phù hợp cho cả tự học và giảng dạy. Phiên bản thứ ba cập nhật thêm nhiều chủ đề hiện đại và từ vựng thực tế trong giao tiếp, học thuật và công việc. Đây là tài liệu không thể thiếu cho người học muốn nâng cao vốn từ một cách hệ thống', 5, 124, 'active', NULL);
INSERT INTO `ebook` VALUES (125, 'T4.0', 'Advanced Grammar in Use with Answers  \n', 110000.00, 'Cuốn sách ngữ pháp nâng cao này được thiết kế cho người học tiếng Anh trình độ cao (C1–C2). Mỗi đơn vị bài học gồm phần giải thích lý thuyết chi tiết và bài tập thực hành đa dạng kèm đáp án, giúp người học tự kiểm tra tiến độ. Nội dung tập trung vào các điểm ngữ pháp phức tạp như câu điều kiện, mệnh đề quan hệ, đảo ngữ, thì hoàn thành và cấu trúc học thuật. Cách trình bày rõ ràng, dễ hiểu, đồng thời cung cấp mẹo dùng tự nhiên như người bản ngữ. Đây là tài liệu luyện ngữ pháp kinh điển của Cambridge.', 5, 125, 'active', NULL);
INSERT INTO `ebook` VALUES (126, 'T5.0', 'Essential Grammar in Use with Answers  ', 115000.00, 'Được viết cho người mới học hoặc ở trình độ sơ-trung cấp (A1–B1), cuốn sách này là công cụ học ngữ pháp tự học hiệu quả nhất thế giới. Mỗi bài học gồm hai trang: một trang giải thích ngắn gọn, trang đối diện là bài tập củng cố. Toàn bộ ví dụ được minh họa sinh động, gần gũi với đời sống hàng ngày. Phiên bản có đáp án giúp người học tự kiểm tra dễ dàng. Cấu trúc khoa học, súc tích và thân thiện khiến cuốn sách này trở thành lựa chọn phổ biến cho người học tự luyện tiếng Anh.', 5, 126, 'active', NULL);
INSERT INTO `ebook` VALUES (127, 'T6.0', 'English For Everyone English Grammar Guide & Practice Book  ', 180000.00, 'Đây là hướng dẫn toàn diện về ngữ pháp tiếng Anh, được trình bày bằng đồ họa trực quan, màu sắc sinh động và giải thích rõ ràng. Sách bao gồm mọi chủ điểm ngữ pháp từ cơ bản đến nâng cao, cùng bài tập thực hành đa dạng giúp củng cố kỹ năng. Phong cách trình bày phù hợp cho người tự học mọi cấp độ, đặc biệt là người học thị giác. Ngoài phần lý thuyết, sách còn cung cấp các mẫu câu thông dụng và ghi chú về cách dùng thực tế trong giao tiếp hàng ngày.', 5, 127, 'active', NULL);
INSERT INTO `ebook` VALUES (128, 'T7.0', 'The English Grammar Workbook for Adults   ', 504000.00, 'Sách được biên soạn đặc biệt cho người trưởng thành muốn củng cố ngữ pháp tiếng Anh phục vụ giao tiếp và công việc. Nội dung đi thẳng vào những điểm ngữ pháp thường bị nhầm lẫn: thì động từ, giới từ, đại từ, câu điều kiện, câu gián tiếp… Mỗi phần đều có ví dụ rõ ràng, bài tập luyện tập thực tế và phần kiểm tra nhỏ giúp theo dõi tiến bộ. Văn phong thân thiện, dễ hiểu và ứng dụng cao, phù hợp cho người bận rộn muốn cải thiện kỹ năng tiếng Anh nhanh chóng mà không cần học theo giáo trình học thuật.', 5, 128, 'active', NULL);
INSERT INTO `ebook` VALUES (129, 'T8.0', 'Fluent Forever: How to Learn Any Language Fast and Never Forget It   ', 406000.00, 'Tác giả Gabriel Wyner, một kỹ sư kiêm ca sĩ opera, chia sẻ phương pháp học ngôn ngữ dựa trên khoa học trí nhớ. Ông khuyến khích học phát âm chuẩn ngay từ đầu, sử dụng thẻ ghi nhớ (flashcards) và kỹ thuật lặp lại ngắt quãng (spaced repetition) để ghi nhớ lâu dài. Sách giải thích cách xây dựng từ vựng qua hình ảnh, âm thanh và cảm xúc thay vì dịch sang tiếng mẹ đẻ. Phương pháp của Wyner được hàng triệu người áp dụng thành công để học nhanh hơn và nhớ lâu hơn khi chinh phục ngoại ngữ mới.', 5, 129, 'active', NULL);
INSERT INTO `ebook` VALUES (130, 'T9.0', 'English Grammar in Use: Book with Answers', 0.00, 'Cuốn sách kinh điển này là phiên bản trung cấp của bộ “Grammar in Use”, phù hợp với người học muốn củng cố ngữ pháp tiếng Anh thực tế. Mỗi bài học bao gồm phần giải thích ngắn gọn, ví dụ minh họa dễ hiểu và bài tập có đáp án giúp người học tự kiểm tra. Tác giả Raymond Murphy sử dụng ngôn ngữ đơn giản, rõ ràng, cùng cách trình bày nhất quán giúp người học dễ theo dõi. Sách phù hợp cho học sinh, sinh viên, người đi làm hoặc tự học tiếng Anh ở nhà.', 5, 130, 'active', NULL);
INSERT INTO `ebook` VALUES (131, 'T10.0', 'Practical English Grammar & Composition', 57500.00, 'Cuốn sách này kết hợp giữa lý thuyết ngữ pháp và kỹ năng viết tiếng Anh thực hành. Người học được hướng dẫn từng bước về cấu trúc câu, loại từ, dấu câu, và phong cách viết học thuật. Phần “composition” giúp rèn luyện cách viết đoạn văn, thư tín và bài luận hiệu quả. Đây là tài liệu hữu ích cho học sinh, sinh viên và người học tiếng Anh muốn cải thiện cả khả năng ngữ pháp lẫn kỹ năng viết. Cấu trúc bài giảng rõ ràng, nhiều ví dụ dễ hiểu, phù hợp cho cả dạy và tự học.', 5, 131, 'active', NULL);
INSERT INTO `ebook` VALUES (132, 'T11.0', 'The Dictionary of Lost Words', 442000.00, 'Cuốn sách này kết hợp giữa lý thuyết ngữ pháp và kỹ năng viết tiếng Anh thực hành. Người học được hướng dẫn từng bước về cấu trúc câu, loại từ, dấu câu, và phong cách viết học thuật. Phần “composition” giúp rèn luyện cách viết đoạn văn, thư tín và bài luận hiệu quả. Đây là tài liệu hữu ích cho học sinh, sinh viên và người học tiếng Anh muốn cải thiện cả khả năng ngữ pháp lẫn kỹ năng viết. Cấu trúc bài giảng rõ ràng, nhiều ví dụ dễ hiểu, phù hợp cho cả dạy và tự học.', 5, 132, 'active', NULL);
INSERT INTO `ebook` VALUES (133, 'T12.0', 'Practical English Usage — Michael Swan', 300000.00, 'Đây là cuốn sách tham khảo kinh điển về ngữ pháp và cách dùng tiếng Anh chuẩn, được sử dụng rộng rãi bởi giáo viên và người học nâng cao. Michael Swan giải thích rõ ràng những điểm ngữ pháp thường gây nhầm lẫn, lỗi phổ biến của người học và sự khác biệt giữa tiếng Anh Anh và Anh Mỹ. Sách được tổ chức theo mục tra cứu tiện lợi, giúp người đọc nhanh chóng tìm câu trả lời cho các thắc mắc thực tế. “Practical English Usage” không chỉ giúp sửa lỗi mà còn nâng cao độ chính xác và tự tin trong giao tiếp và viết học thuật.', 5, 133, 'active', NULL);
INSERT INTO `ebook` VALUES (134, 'T13.0', 'English Idioms in Use — Cambridge (Intermediate)', 250000.00, 'Bộ sách này giúp người học nắm vững các thành ngữ tiếng Anh (idioms) được sử dụng phổ biến trong giao tiếp và văn viết. Mỗi bài học trình bày ý nghĩa, ví dụ cụ thể và bài tập thực hành giúp ghi nhớ tự nhiên. Các idioms được phân loại theo chủ đề hoặc tình huống, giúp người học dễ áp dụng trong ngữ cảnh thực tế. Phiên bản Intermediate dành cho trình độ trung cấp, còn Advanced dành cho người muốn đạt khả năng gần như bản ngữ. Sách rất hữu ích để cải thiện sự linh hoạt và tự nhiên trong diễn đạt tiếng Anh.', 5, 134, 'active', NULL);
INSERT INTO `ebook` VALUES (135, 'T14.0', 'Phrasal Verbs in Use — Cambridge', 250000.00, 'Cuốn sách tập trung vào phrasal verbs – phần khó và quan trọng trong tiếng Anh. Mỗi đơn vị bài học gồm danh sách phrasal verbs theo chủ đề, định nghĩa, ví dụ minh họa và bài tập thực hành. Cách trình bày sinh động, dễ nhớ giúp người học nhanh chóng nhận ra quy tắc sử dụng và sắc thái ý nghĩa khác nhau. Hai cấp độ Intermediate và Advanced đáp ứng nhu cầu của người học từ trung cấp đến chuyên sâu. Đây là tài liệu không thể thiếu để giao tiếp tự nhiên hơn, đặc biệt trong môi trường làm việc hoặc học tập quốc tế.', 5, 135, 'active', NULL);
INSERT INTO `ebook` VALUES (136, 'T15.0', 'Oxford Word Skills (Advanced) — Stuart Redman', 380000.00, '“Oxford Word Skills” là bộ sách từ vựng nổi tiếng của Oxford University Press. Phiên bản Advanced giúp người học phát triển vốn từ vựng học thuật và chuyên sâu, tập trung vào cách dùng từ trong ngữ cảnh thực tế. Mỗi bài học có phần giải thích rõ ràng, ví dụ tự nhiên và bài tập ứng dụng để củng cố. Ngoài ra, sách còn tích hợp kỹ năng nói và viết, giúp người học sử dụng từ vựng linh hoạt hơn. Đây là tài liệu lý tưởng cho người đã đạt trình độ trung cấp muốn mở rộng vốn từ ở mức cao cấp.', 5, 136, 'active', NULL);
INSERT INTO `ebook` VALUES (137, 'T16.0', 'Cambridge Academic English (Course for Students)', 450000.00, 'Bộ giáo trình này được thiết kế đặc biệt cho sinh viên học tập trong môi trường đại học quốc tế. Sách tập trung phát triển kỹ năng học thuật: đọc tài liệu nghiên cứu, ghi chú, viết luận, thuyết trình và nghe giảng. Mỗi đơn vị bài học phản ánh tình huống thật trong lớp học đại học, giúp người học tự tin hơn khi theo học chương trình bằng tiếng Anh. Cấu trúc bài học rõ ràng, kèm hướng dẫn ngữ pháp, từ vựng và kỹ năng tư duy phản biện. Đây là tài liệu tiêu chuẩn cho sinh viên chuẩn bị du học hoặc học bằng tiếng Anh.', 5, 137, 'active', NULL);
INSERT INTO `ebook` VALUES (138, 'T17.0', 'Academic Writing for Graduate Students — Swales & Feak', 500000.00, 'Cuốn sách hướng dẫn cách viết học thuật chuyên nghiệp dành cho sinh viên cao học và nghiên cứu sinh. Tác giả trình bày quy trình viết bài báo, luận văn và báo cáo nghiên cứu theo chuẩn quốc tế. Nội dung bao gồm cách xây dựng đoạn mở bài, trình bày luận điểm, trích dẫn, lập luận và chỉnh sửa văn phong học thuật. Sách có nhiều ví dụ thực tế từ bài viết khoa học thật, cùng bài tập giúp người học luyện kỹ năng từng bước. Đây là tài liệu bắt buộc ở nhiều khóa viết học thuật và nghiên cứu quốc tế.', 5, 138, 'active', NULL);
INSERT INTO `ebook` VALUES (139, 'T18.0', 'Collins COBUILD Advanced Learner’s Dictionary', 500000.00, 'Từ điển này được xây dựng dựa trên kho ngữ liệu (corpus) COBUILD nổi tiếng, cung cấp hàng chục nghìn ví dụ thực tế trích từ các nguồn ngôn ngữ hiện đại. Định nghĩa ngắn gọn, dễ hiểu, tập trung vào cách dùng từ trong ngữ cảnh thật. Ngoài từ vựng cơ bản, sách còn bao gồm collocations, idioms và phrasal verbs. Phần giải thích ngữ pháp và cấu trúc câu giúp người học hiểu sâu hơn về cách sử dụng tự nhiên. Đây là công cụ hữu ích cho học sinh, sinh viên và giáo viên tiếng Anh nâng cao.', 5, 139, 'active', NULL);
INSERT INTO `ebook` VALUES (140, 'T19.0', 'Longman Dictionary of Contemporary English', 450000.00, 'Đây là một trong những từ điển tiếng Anh hiện đại và đầy đủ nhất, được thiết kế cho người học tiếng Anh toàn cầu. Từ vựng được giải thích bằng ngôn ngữ đơn giản, mỗi định nghĩa đều kèm ví dụ rõ ràng và hướng dẫn phát âm. Ngoài nghĩa thông thường, sách còn cung cấp thông tin về ngữ pháp, collocation, cụm động từ và cách dùng theo ngữ cảnh. Phiên bản mới còn có phần học từ vựng học thuật và kỹ năng giao tiếp. Đây là tài liệu chuẩn được dùng trong nhiều trường học quốc tế.', 5, 140, 'active', NULL);
INSERT INTO `ebook` VALUES (141, 'T20.0', 'English Pronunciation in Use (Advanced) — Cambridge', 300000.00, 'Cuốn sách luyện phát âm tiếng Anh ở trình độ nâng cao, giúp người học hoàn thiện khả năng phát âm chuẩn và tự nhiên. Mỗi bài học tập trung vào một nhóm âm hoặc hiện tượng ngữ âm như nối âm, ngữ điệu, trọng âm và âm yếu. Sách kèm bài nghe giúp người học nhận biết sự khác biệt giữa các âm khó và thực hành theo giọng chuẩn Anh hoặc Mỹ. Cách trình bày khoa học, dễ hiểu và giàu ví dụ thực tế giúp người học đạt được khả năng phát âm chính xác trong giao tiếp chuyên nghiệp.', 5, 141, 'active', NULL);
INSERT INTO `ebook` VALUES (142, 'T21.0', 'Ship or Sheep? — Minimal Pairs Practice for Pronunciation', 200000.00, 'Cuốn sách nổi tiếng giúp người học luyện phân biệt các cặp âm tiếng Anh tương tự (minimal pairs) như /ɪ/ và /iː/, /ʌ/ và /ɑː/. Bằng cách luyện nghe – nói – lặp lại, người học cải thiện khả năng phát âm, nghe hiểu và tự tin khi giao tiếp. Mỗi bài học gồm bài nghe, từ vựng mẫu và bài tập luyện phát âm. Sách được biên soạn dễ hiểu, vui nhộn và rất phù hợp cho người học ở trình độ trung cấp trở lên muốn chỉnh phát âm chuẩn hơn và tránh hiểu nhầm trong giao tiếp thực tế.', 5, 142, 'active', NULL);
INSERT INTO `ebook` VALUES (143, 'T22.0', 'Clear Speech — Pronunciation and Listening Comprehension in North American English', 250000.00, 'Đây là cuốn sách kinh điển giúp người học cải thiện phát âm và khả năng nghe hiểu tiếng Anh kiểu Bắc Mỹ. Tác giả Judy Gilbert sử dụng phương pháp luyện theo nhịp điệu, trọng âm và ngữ điệu tự nhiên, giúp người học nói rõ ràng, dễ hiểu hơn. Sách kèm bài nghe thực tế, minh họa các lỗi phát âm phổ biến và hướng dẫn cách sửa chi tiết. Phần thực hành phong phú, dễ áp dụng trong lớp học hoặc tự học. “Clear Speech” là tài liệu tiêu chuẩn trong nhiều chương trình ESL và phát âm quốc tế.', 5, 143, 'active', NULL);
INSERT INTO `ebook` VALUES (144, 'T23.0', 'Speakout (Upper-Intermediate) Course Book', 400000.00, '“Speakout” là giáo trình học tiếng Anh giao tiếp hiện đại, do BBC kết hợp với Pearson phát hành. Phiên bản Upper-Intermediate giúp người học phát triển toàn diện bốn kỹ năng: nghe, nói, đọc và viết, thông qua các chủ đề thực tế và video phỏng vấn sinh động. Sách có cấu trúc rõ ràng, chú trọng vào kỹ năng giao tiếp tự tin và tự nhiên trong đời sống hàng ngày hoặc môi trường làm việc. Mỗi bài học còn kèm phần luyện phát âm và ngữ pháp, giúp người học sử dụng tiếng Anh một cách chính xác và linh hoạt.', 5, 144, 'active', NULL);
INSERT INTO `ebook` VALUES (145, 'T24.0', 'New Headway (Upper-Intermediate) — Coursebook', 380000.00, '“New Headway” là một trong những giáo trình tiếng Anh phổ biến nhất thế giới, được biên soạn cẩn thận và khoa học. Phiên bản Upper-Intermediate cung cấp nội dung ngữ pháp nâng cao, từ vựng phong phú và các hoạt động giao tiếp thực tế. Mỗi bài học được thiết kế cân đối giữa lý thuyết và thực hành, giúp người học tiến bộ vững chắc. Bên cạnh đó, phần nghe và nói được biên tập tự nhiên, giúp học viên luyện phản xạ giao tiếp hiệu quả. Đây là giáo trình tiêu chuẩn được sử dụng rộng rãi trong các trung tâm Anh ngữ quốc tế.', 5, 145, 'active', NULL);
INSERT INTO `ebook` VALUES (146, 'T25.0', 'Official Cambridge Guide to IELTS', 480000.00, 'Cuốn hướng dẫn toàn diện này giúp thí sinh chuẩn bị cho kỳ thi IELTS ở cả bốn kỹ năng: Listening, Reading, Writing và Speaking. Sách bao gồm chiến lược làm bài, mẹo thi, bài mẫu band cao và 8 bài test thực hành. Các chuyên gia của Cambridge biên soạn nội dung dựa trên đề thi thật, giúp người học hiểu rõ cấu trúc và yêu cầu từng phần. Ngoài ra, phần hướng dẫn viết và nói có nhiều ví dụ thực tế cùng ghi chú tiêu chí chấm điểm. Đây là tài liệu “must-have” cho bất kỳ ai muốn đạt điểm IELTS cao.', 5, 146, 'active', NULL);
INSERT INTO `ebook` VALUES (147, 'T26.0', 'Cambridge IELTS Trainer (with answers)', 300000.00, '“IELTS Trainer” là bộ tài liệu luyện thi chuyên sâu gồm sáu bài test IELTS hoàn chỉnh, kèm hướng dẫn chi tiết và đáp án. Hai bài đầu tiên có phần “training” giải thích chiến lược, bẫy thường gặp và cách phân tích câu hỏi, giúp người học hiểu sâu cấu trúc bài thi. Các bài còn lại được thiết kế như đề thi thật để luyện tập kỹ năng. Sách kèm phần nghe, bài mẫu Writing và Speaking để học viên tự so sánh. Đây là tài liệu rất hữu ích cho người học muốn làm quen với kỳ thi IELTS chính thức.', 5, 147, 'active', NULL);
INSERT INTO `ebook` VALUES (148, 'T27.0', 'Barron’s TOEFL iBT (with online audio)', 750000.00, 'Đây là bộ tài liệu toàn diện giúp thí sinh chuẩn bị cho kỳ thi TOEFL iBT. Sách cung cấp hướng dẫn chi tiết cho bốn kỹ năng, bài tập thực hành phong phú và sáu bài test mô phỏng đề thi thật. Ngoài ra, Barron’s còn có phần hướng dẫn chiến lược làm bài, mẹo ghi điểm và phân tích các lỗi phổ biến. Phiên bản kèm audio online giúp luyện nghe và nói hiệu quả. Sách được đánh giá cao bởi học sinh, sinh viên và giáo viên tiếng Anh học thuật trên toàn thế giới vì tính thực tiễn và độ chính xác cao.', 5, 148, 'active', NULL);
INSERT INTO `ebook` VALUES (149, 'T28.0', 'The Practice of English Language Teaching — Jeremy Harmer', 550000.00, 'Đây là cuốn cẩm nang chuyên nghiệp dành cho giáo viên tiếng Anh, cung cấp kiến thức toàn diện về lý thuyết giảng dạy và phương pháp sư phạm hiện đại. Jeremy Harmer trình bày các kỹ thuật dạy ngữ pháp, từ vựng, kỹ năng nghe – nói – đọc – viết, cùng cách thiết kế bài giảng hiệu quả. Sách cũng phân tích vai trò của giáo viên, động lực học tập và phương pháp đánh giá học viên. Với phong cách trình bày logic, dễ hiểu và thực tế, đây là tài liệu bắt buộc trong nhiều chương trình đào tạo giáo viên TESOL và CELTA.', 5, 149, 'active', NULL);
INSERT INTO `ebook` VALUES (150, 'T29.0', 'Dictionary of Phrasal Verbs', 350000.00, 'Cuốn từ điển này chuyên về phrasal verbs – những cụm động từ đặc trưng của tiếng Anh hiện đại. Mỗi mục từ gồm định nghĩa rõ ràng, ví dụ cụ thể và thông tin ngữ pháp cần thiết. Sách cũng chỉ ra sự khác biệt tinh tế giữa các phrasal verbs tương tự, giúp người học sử dụng chính xác và tự nhiên hơn trong nói và viết. Đây là tài liệu hữu ích cho sinh viên, giáo viên và người học nâng cao muốn nắm vững phần khó nhất trong tiếng Anh giao tiếp và học thuật.', 5, 150, 'active', NULL);
INSERT INTO `ebook` VALUES (151, 'T30.0', '1100 Words You Need to Know', 230000.00, 'Cuốn sách từ vựng nổi tiếng này giúp người học mở rộng vốn từ học thuật và giao tiếp thông qua 46 tuần học. Mỗi tuần bao gồm danh sách từ vựng, định nghĩa, ví dụ và bài tập củng cố. Sách sử dụng phương pháp học ngắn gọn, dễ nhớ, đồng thời lồng ghép các câu chuyện vui và câu hỏi trắc nghiệm để kiểm tra. Đây là tài liệu luyện từ vựng hữu ích cho học sinh chuẩn bị các kỳ thi như TOEFL, SAT, GRE hoặc IELTS, cũng như những người muốn cải thiện khả năng diễn đạt tiếng Anh nâng cao.', 5, 151, 'active', NULL);
INSERT INTO `ebook` VALUES (152, 'T31.0', 'English Collocations in Use (Intermediate / Advanced)', 270000.00, 'Bộ sách này tập trung vào collocations – sự kết hợp tự nhiên giữa các từ trong tiếng Anh (như “make a decision”, “take a risk”). Mỗi bài học giới thiệu nhóm collocations theo chủ đề, giải thích ý nghĩa và ngữ cảnh sử dụng, kèm bài tập thực hành. Hai cấp độ Intermediate và Advanced phù hợp cho người học muốn diễn đạt tự nhiên và giống người bản ngữ hơn. Sách rất hữu ích cho kỹ năng viết và nói học thuật, đồng thời giúp người học tránh lỗi dịch từng từ khi sử dụng tiếng Anh.', 5, 152, 'active', NULL);
INSERT INTO `ebook` VALUES (153, 'K1.0', 'Getting Things Done: The Art of Stress‑Free Productivity', 426600.00, 'Cuốn sách kinh điển về quản lý công việc và hiệu suất cá nhân. David Allen giới thiệu phương pháp GTD (Getting Things Done), tập trung vào việc ghi lại mọi nhiệm vụ, phân loại rõ ràng và xử lý theo thứ tự ưu tiên để đạt hiệu quả tối đa mà không căng thẳng. Ông hướng dẫn cách thiết lập hệ thống tổ chức công việc khoa học, duy trì trạng thái “mind like water” – đầu óc nhẹ nhõm nhưng tập trung. GTD đã trở thành triết lý sống của hàng triệu người trên thế giới trong việc kiểm soát thời gian và năng suất cá nhân.', 6, 153, 'active', NULL);
INSERT INTO `ebook` VALUES (154, 'K2.0', 'The Genius of Empathy: Practical Skills to Heal Your Sensitive Self', 765000.00, 'Tác giả Judith Orloff – bác sĩ tâm lý nổi tiếng – chia sẻ cách phát triển và sử dụng sức mạnh của sự thấu cảm để chữa lành bản thân và kết nối sâu sắc hơn với người khác. Cuốn sách hướng dẫn kỹ năng thiết lập ranh giới lành mạnh, tránh bị “kiệt sức cảm xúc”, đồng thời chuyển hóa sự nhạy cảm thành điểm mạnh. Thông qua các ví dụ thực tế, Orloff giúp người đọc hiểu cách sống đồng cảm mà vẫn bảo vệ năng lượng cá nhân. Đây là tài liệu thực hành hữu ích cho người làm trong môi trường áp lực và giàu cảm xúc.', 6, 154, 'active', NULL);
INSERT INTO `ebook` VALUES (155, 'K3.0', 'Life Skills for Teenage Boys: Practical Advice for Personal Growth', 646000.00, 'Cuốn sách này cung cấp những kỹ năng cần thiết giúp các bạn nam tuổi thiếu niên phát triển bản thân một cách toàn diện. Nội dung bao gồm quản lý cảm xúc, giao tiếp hiệu quả, xây dựng sự tự tin, chăm sóc sức khỏe và định hướng tương lai. Với ngôn ngữ gần gũi, dễ hiểu, tác giả hướng dẫn từng bước để hình thành thói quen tích cực và khả năng tự lập. Đây là tài liệu quý cho thanh thiếu niên muốn rèn luyện tư duy trưởng thành, ứng phó với thách thức và phát triển nhân cách mạnh mẽ.', 6, 155, 'active', NULL);
INSERT INTO `ebook` VALUES (156, 'K4.0', 'Essential Life Skills for Boys', 275000.00, 'Sách hướng đến việc giúp các bạn trai trẻ học cách sống độc lập, có trách nhiệm và tự tin. Tác giả trình bày các kỹ năng cơ bản như quản lý tiền bạc, chăm sóc bản thân, giao tiếp xã hội, đặt mục tiêu và giải quyết vấn đề. Mỗi chương đều có ví dụ thực tế và lời khuyên thực tiễn, giúp độc giả áp dụng ngay vào cuộc sống. Cuốn sách giúp thanh thiếu niên hiểu rằng thành công không chỉ đến từ kiến thức, mà còn từ kỹ năng sống và thái độ chủ động với cuộc đời.', 6, 156, 'active', NULL);
INSERT INTO `ebook` VALUES (157, 'K5.0', 'Practical Life Skills Big Book Gr. 9‑12+ eBook', 800000.00, 'Đây là bộ tài liệu giáo dục được thiết kế cho học sinh trung học, giúp rèn luyện kỹ năng sống thực tế như quản lý tài chính, chuẩn bị nghề nghiệp, kỹ năng giao tiếp và trách nhiệm công dân. Nội dung được trình bày dạng hoạt động, bài tập nhóm và tình huống mô phỏng, giúp học sinh học thông qua trải nghiệm. Bộ sách phù hợp cho chương trình giáo dục kỹ năng sống tại trường hoặc học tại nhà. Đây là nguồn tài liệu hữu ích cho giáo viên và học sinh muốn chuẩn bị hành trang bước vào đời.', 6, 157, 'active', NULL);
INSERT INTO `ebook` VALUES (158, 'K6.0', 'Real World Life Skills‑Self Sustainability Skills Gr. 6‑12 eBook', 399000.00, 'Cuốn sách tập trung vào kỹ năng tự lập và tự duy trì trong cuộc sống hiện đại. Học sinh được hướng dẫn cách quản lý tài chính cá nhân, chăm sóc sức khỏe, lập kế hoạch nghề nghiệp, bảo vệ môi trường và tư duy tự chịu trách nhiệm. Các bài học đi kèm hoạt động thực hành giúp người học áp dụng ngay vào đời thực. Cuốn sách khuyến khích tinh thần tự chủ, sáng tạo và trách nhiệm xã hội – những yếu tố quan trọng để thành công trong cuộc sống trưởng thành.', 6, 158, 'active', NULL);
INSERT INTO `ebook` VALUES (159, 'K7.0', 'Life Skills for Kids', 264000.00, 'Sách dạy trẻ em và thiếu niên các kỹ năng cơ bản để trở nên độc lập, tự tin và có trách nhiệm. Nội dung bao gồm kỹ năng giao tiếp, quản lý thời gian, ứng xử xã hội, tiền bạc, an toàn cá nhân và tinh thần đồng cảm. Tác giả trình bày theo phong cách vui tươi, sinh động, dễ hiểu, giúp trẻ học qua ví dụ thực tế và bài tập nhỏ. “Life Skills for Kids” là cuốn cẩm nang hữu ích cho phụ huynh, giáo viên và học sinh nhằm xây dựng nền tảng vững chắc cho sự trưởng thành của trẻ.', 6, 159, 'active', NULL);
INSERT INTO `ebook` VALUES (160, 'K8.0', 'Life Skills by Julia Laflin', 136000.00, 'Cuốn sách thực hành kỹ năng sống toàn diện, hướng dẫn cách xử lý những tình huống thực tế trong đời sống hàng ngày: nấu ăn, giặt giũ, quản lý tiền bạc, ứng xử xã hội và bảo dưỡng đồ dùng. Julia Laflin biên soạn nội dung ngắn gọn, minh họa rõ ràng, phù hợp cho người trẻ mới trưởng thành hoặc sống tự lập lần đầu. Đây là “cuốn sổ tay sinh tồn” giúp người đọc biết cách quản lý bản thân, tổ chức cuộc sống hiệu quả và tự tin đối mặt với thử thách thường nhật.', 6, 160, 'active', NULL);
INSERT INTO `ebook` VALUES (161, 'K9.0', 'Life Skills Leveled Daily Curriculum (LEVEL 1)', 160500.00, 'Giáo trình được biên soạn cho học sinh có nhu cầu đặc biệt hoặc đang phát triển kỹ năng sống ở mức cơ bản. Mỗi bài học tập trung vào một kỹ năng thực tế: tự chăm sóc, vệ sinh cá nhân, an toàn, giao tiếp xã hội và quản lý cảm xúc. Nội dung được chia nhỏ, dễ hiểu, kèm hình ảnh minh họa và hoạt động tương tác. Giáo viên có thể sử dụng linh hoạt trong lớp hoặc tại nhà. Đây là tài liệu giáo dục thực hành hữu ích giúp học sinh rèn thói quen tự lập và hòa nhập xã hội.', 6, 161, 'active', NULL);
INSERT INTO `ebook` VALUES (162, 'K10.0', 'You Can (People Skills for Life)', 40000.00, 'Tác giả John Townsend giới thiệu các kỹ năng mềm thiết yếu để giao tiếp hiệu quả và xây dựng mối quan hệ bền vững trong cuộc sống. Cuốn sách nhấn mạnh tầm quan trọng của sự chân thành, lắng nghe, tự tin và tôn trọng trong tương tác xã hội. Thông qua ví dụ thực tế, tác giả hướng dẫn cách vượt qua rào cản giao tiếp, giải quyết xung đột và thể hiện cảm xúc lành mạnh. Đây là tài liệu bổ ích cho học sinh, sinh viên và người đi làm muốn phát triển kỹ năng con người – nền tảng của thành công lâu dài.', 6, 162, 'active', NULL);
INSERT INTO `ebook` VALUES (163, 'K11.0', 'Lifeskills: 8 Simple Ways to Build Stronger Relationships…', 545000.00, 'Cuốn sách tập trung vào việc phát triển kỹ năng giao tiếp và xây dựng mối quan hệ lành mạnh trong đời sống cá nhân và công việc. Tác giả giới thiệu tám phương pháp đơn giản nhưng hiệu quả, bao gồm kỹ năng lắng nghe, đồng cảm, kiểm soát cảm xúc, giải quyết xung đột và thể hiện bản thân tự tin. Mỗi chương có ví dụ minh họa, bài tập thực hành và gợi ý áp dụng trong các tình huống thực tế. “Lifeskills” là tài liệu hữu ích cho bất kỳ ai muốn cải thiện khả năng giao tiếp và phát triển mối quan hệ tích cực, bền vững.', 6, 163, 'active', NULL);
INSERT INTO `ebook` VALUES (164, 'K12.0', 'Life Skills', 813000.00, 'Cuốn sách mang tính hướng dẫn thực tế, tập trung vào việc trang bị kỹ năng sống cho người trẻ tuổi bước vào đời. Nội dung bao gồm kỹ năng tài chính cá nhân, định hướng nghề nghiệp, quản lý thời gian, giao tiếp và tự tin xã hội. Kierstan Kindred trình bày ngắn gọn, dễ hiểu và hiện đại, giúp độc giả áp dụng ngay các kỹ năng trong đời sống hằng ngày. Cuốn sách khuyến khích tư duy độc lập, trách nhiệm và sự trưởng thành cảm xúc – nền tảng quan trọng để xây dựng thành công và hạnh phúc lâu dài.', 6, 164, 'active', NULL);
INSERT INTO `ebook` VALUES (165, 'K13.0', 'Life Skills: How to Chop Wood, Avoid a Lightning Strike …', 189360.00, 'Cuốn “Life Skills” mang phong cách vui nhộn, thực tế và hữu ích, cung cấp hàng trăm mẹo nhỏ giúp bạn xử lý các tình huống đời thường. Từ cách nấu ăn, sửa chữa cơ bản, quản lý tài chính, đến ứng xử xã hội và an toàn cá nhân – tất cả đều được trình bày ngắn gọn và dễ áp dụng. Chris Peterson giúp người đọc cảm thấy tự tin hơn trong việc tự lập, xử lý khủng hoảng nhỏ và chăm sóc bản thân. Đây là cuốn cẩm nang sinh tồn thiết thực cho người trẻ bước vào cuộc sống độc lập.', 6, 165, 'active', NULL);
INSERT INTO `ebook` VALUES (166, 'K14.0', 'The Little Book of Life Skills: How to Deal with Dinner…', 335080.00, 'Cuốn sách hướng dẫn cách giải quyết những việc nhỏ nhưng quan trọng trong cuộc sống hàng ngày. Tác giả Erin Zammett Ruddy tổng hợp lời khuyên từ các chuyên gia trong nhiều lĩnh vực – từ dọn dẹp nhà cửa, quản lý email, tổ chức công việc đến ứng xử xã hội. Mỗi kỹ năng được trình bày rõ ràng, dễ làm theo và đi kèm mẹo tiết kiệm thời gian. “The Little Book of Life Skills” là lựa chọn tuyệt vời cho những ai muốn sống ngăn nắp, hiệu quả và giảm căng thẳng trong cuộc sống hiện đại.', 6, 166, 'active', NULL);
INSERT INTO `ebook` VALUES (167, 'K15.0', 'Life Skills: How to Cook, Clean, Manage Money, Fix Your Car…', 199000.00, 'Cuốn sách này là hướng dẫn toàn diện cho người trưởng thành trẻ tuổi học cách tự lập và làm chủ cuộc sống. Nội dung bao gồm kỹ năng nấu ăn cơ bản, dọn dẹp, quản lý tài chính cá nhân, bảo dưỡng xe, và giao tiếp ứng xử xã hội. M.R. Nelson sử dụng phong cách viết gần gũi, hài hước và thực tế, giúp người đọc cảm thấy việc “trưởng thành” không còn quá khó khăn. Đây là cuốn cẩm nang sinh tồn thiết yếu dành cho sinh viên, người đi làm trẻ hoặc bất kỳ ai muốn tự tin hơn trong đời sống độc lập.', 6, 167, 'active', NULL);
INSERT INTO `ebook` VALUES (168, 'K16.0', 'The Power of Now', 480000.00, 'Một trong những tác phẩm tâm linh có ảnh hưởng sâu rộng nhất thế kỷ 21. Eckhart Tolle khuyến khích người đọc sống trọn vẹn trong hiện tại, buông bỏ quá khứ và lo lắng về tương lai để đạt đến trạng thái an lạc nội tâm. Cuốn sách kết hợp triết lý phương Đông và tư duy hiện đại, giải thích cách vượt qua “cái tôi” (ego) – nguồn gốc của đau khổ tinh thần. Với giọng văn giản dị nhưng sâu sắc, “The Power of Now” đã giúp hàng triệu người tìm thấy bình an và ý nghĩa thật sự của cuộc sống.', 6, 168, 'active', NULL);
INSERT INTO `ebook` VALUES (169, 'K17.0', 'Man’s Search for Meaning', 424000.00, 'Tác phẩm kinh điển của bác sĩ tâm thần Viktor Frankl, người sống sót sau trại tập trung Đức Quốc Xã. Ông kể lại trải nghiệm kinh hoàng của mình và rút ra triết lý sống sâu sắc: con người có thể chịu đựng bất kỳ hoàn cảnh nào nếu họ tìm thấy ý nghĩa cho cuộc đời mình. Cuốn sách giới thiệu liệu pháp “logotherapy”, tập trung vào việc tìm mục đích sống thay vì chạy trốn đau khổ. Đây là một trong những tác phẩm truyền cảm hứng mạnh mẽ nhất về ý chí, nghị lực và sức mạnh tinh thần.', 6, 169, 'active', NULL);
INSERT INTO `ebook` VALUES (170, 'K18.0', 'Mindset: The New Psychology of Success', 350000.00, 'Giáo sư tâm lý học Carol Dweck trình bày khái niệm “fixed mindset” và “growth mindset” – hai lối tư duy quyết định thành công của mỗi người. Bằng nghiên cứu khoa học và ví dụ thực tế, bà chứng minh rằng những ai tin vào khả năng phát triển của bản thân (growth mindset) sẽ thành công hơn trong học tập, công việc và cuộc sống. Cuốn sách cung cấp chiến lược giúp thay đổi tư duy, đối mặt thất bại và phát triển bản thân bền vững. Đây là tác phẩm nền tảng cho giáo dục và huấn luyện cá nhân hiện đại.', 6, 170, 'active', NULL);
INSERT INTO `ebook` VALUES (171, 'K19.0', 'The 7 Habits of Highly Effective People – Stephen R. Covey', 300000.00, 'Stephen Covey trình bày bảy thói quen cốt lõi giúp con người đạt được hiệu quả bền vững trong công việc và cuộc sống. Từ việc chủ động chịu trách nhiệm, đặt mục tiêu, sắp xếp ưu tiên, đến kỹ năng hợp tác và tự hoàn thiện – mỗi thói quen được trình bày qua ví dụ thực tế và nguyên tắc đạo đức phổ quát. Cuốn sách không chỉ dạy kỹ năng quản lý thời gian mà còn hướng con người sống có định hướng và giá trị. Đây là tài liệu phát triển cá nhân kinh điển được đọc rộng rãi trên toàn cầu.', 6, 171, 'active', NULL);
INSERT INTO `ebook` VALUES (172, 'K20.0', 'How to Win Friends and Influence People – Dale Carnegie', 220000.00, 'Cuốn sách huyền thoại về nghệ thuật giao tiếp và thuyết phục, được xuất bản lần đầu năm 1936 và vẫn giữ nguyên giá trị đến nay. Dale Carnegie chia sẻ những nguyên tắc đơn giản nhưng mạnh mẽ: lắng nghe chân thành, quan tâm thật lòng đến người khác và khơi gợi thiện cảm bằng sự tôn trọng. Sách giúp người đọc cải thiện các mối quan hệ cá nhân, thành công hơn trong công việc và giao tiếp xã hội. “Đắc Nhân Tâm” – bản dịch tiếng Việt – đã trở thành kim chỉ nam cho hàng triệu người trong phát triển nhân cách và kỹ năng ứng xử.', 6, 172, 'active', NULL);
INSERT INTO `ebook` VALUES (173, 'K21.0', 'The Subtle Art of Not Giving a F*ck – Mark Manson', 270000.00, 'Mark Manson mang đến một cách nhìn thực tế và thẳng thắn về hạnh phúc và thành công. Thay vì cố gắng “tích cực mọi lúc”, ông cho rằng cuộc sống có giới hạn và điều quan trọng là chọn điều gì đáng để quan tâm. Bằng giọng văn hài hước, sâu sắc và đôi khi châm biếm, Manson giúp người đọc học cách chấp nhận thất bại, đối mặt với khó khăn và tìm ý nghĩa thật sự. Cuốn sách phá bỏ lối sống “tích cực giả tạo”, truyền cảm hứng sống thật, tự chủ và tập trung vào giá trị cốt lõi của bản thân.', 6, 173, 'active', NULL);
INSERT INTO `ebook` VALUES (174, 'K22.0', 'Deep Work – Cal Newport', 280000.00, 'Cal Newport lập luận rằng trong thời đại ngập tràn thông tin và xao nhãng, khả năng “làm việc sâu” – tập trung hoàn toàn vào một nhiệm vụ khó – là kỹ năng quý giá nhất. Ông đưa ra các chiến lược cụ thể để rèn luyện sự tập trung, loại bỏ thói quen làm việc nông, và đạt hiệu suất vượt trội. Cuốn sách kết hợp nghiên cứu khoa học, ví dụ thực tế và lời khuyên thực hành, giúp người đọc làm việc thông minh hơn, sáng tạo hơn và đạt thành tựu lớn mà vẫn duy trì cân bằng cuộc sống.', 6, 174, 'active', NULL);
INSERT INTO `ebook` VALUES (175, 'K23.0', 'Can’t Hurt Me – David Goggins', 310000.00, 'Tự truyện của David Goggins – cựu lính SEAL Hoa Kỳ và vận động viên siêu marathon – kể hành trình vượt qua tuổi thơ khắc nghiệt, phân biệt chủng tộc và giới hạn thể chất để trở thành biểu tượng của ý chí. Goggins chia sẻ triết lý “callous the mind” – rèn luyện tâm trí cứng cỏi qua nỗi đau và thử thách. Mỗi chương kèm bài tập tư duy giúp người đọc phát triển kỷ luật, sức mạnh tinh thần và khả năng chịu đựng phi thường. Cuốn sách là lời kêu gọi dũng cảm đối mặt với chính mình và không bao giờ bỏ cuộc.', 6, 175, 'active', NULL);
INSERT INTO `ebook` VALUES (176, 'K24.0', 'The Four Agreements – Don Miguel Ruiz', 260000.00, 'Dựa trên triết lý Toltec cổ đại của Mexico, Don Miguel Ruiz trình bày bốn cam kết sống giúp con người đạt được tự do nội tâm và hạnh phúc bền vững: (1) Hãy nói năng chính trực, (2) Đừng coi mọi chuyện là cá nhân, (3) Đừng giả định điều gì, (4) Luôn nỗ lực hết mình. Cuốn sách ngắn gọn nhưng sâu sắc, giúp người đọc giải phóng bản thân khỏi niềm tin giới hạn và thói quen tiêu cực. Đây là tác phẩm tâm linh hiện đại nổi tiếng về cách sống giản đơn nhưng đầy ý nghĩa.', 6, 176, 'active', NULL);
INSERT INTO `ebook` VALUES (177, 'K25.0', 'Đắc Nhân Tâm – Dale Carnegie', 129000.00, 'Phiên bản tiếng Việt của “How to Win Friends and Influence People”, được dịch sát và biên tập phù hợp với văn hóa Á Đông. Sách dạy cách xây dựng mối quan hệ tích cực, thấu hiểu người khác và gây ảnh hưởng bằng sự chân thành. Những nguyên tắc của Carnegie vẫn mang giá trị vĩnh cửu trong giao tiếp, lãnh đạo và phát triển cá nhân. “Đắc Nhân Tâm” không chỉ là sách dạy kỹ năng mà còn là triết lý sống: muốn được yêu quý và thành công, trước hết phải thật lòng quan tâm và tôn trọng con người.', 6, 177, 'active', NULL);
INSERT INTO `ebook` VALUES (178, 'K26.0', 'Tư Duy Tích Cực – Norman Vincent Peale', 99000.00, 'Là tác phẩm kinh điển về sức mạnh của niềm tin và thái độ sống tích cực. Norman Vincent Peale khẳng định rằng khi ta thay đổi suy nghĩ, ta có thể thay đổi cuộc đời. Bằng câu chuyện truyền cảm hứng và bài học thực tế, ông hướng dẫn cách vượt qua sợ hãi, tự ti và thất bại bằng niềm tin, lòng biết ơn và hành động kiên định. Cuốn sách đã giúp hàng triệu người tìm lại hy vọng, động lực và sự bình an trong tâm hồn – trở thành nền tảng cho phong trào “tư duy tích cực” hiện đại.', 6, 178, 'active', NULL);
INSERT INTO `ebook` VALUES (179, 'K27.0', 'Bí Mật Của May Mắn – Alex Rovira & Fernando Trías de Bes', 115000.00, 'Qua một câu chuyện ngụ ngôn sâu sắc về hai người bạn cùng đi tìm “cỏ bốn lá”, tác giả truyền tải thông điệp rằng may mắn không phải là ngẫu nhiên mà do chính ta tạo ra. Cuốn sách khuyến khích người đọc thay đổi thái độ, nỗ lực chuẩn bị và hành động đúng đắn để tạo ra cơ hội. Với văn phong nhẹ nhàng, triết lý sâu sắc và dễ hiểu, “Bí Mật Của May Mắn” là cuốn sách truyền cảm hứng mạnh mẽ về sự chủ động, kiên trì và niềm tin vào cuộc sống.', 6, 179, 'active', NULL);
INSERT INTO `ebook` VALUES (180, 'K28.0', 'Khéo Ăn Nói Sẽ Có Được Thiên Hạ – Trác Nhã', 99000.00, 'Cuốn sách hướng dẫn nghệ thuật giao tiếp thông minh, khéo léo và hiệu quả trong mọi tình huống. Tác giả Trác Nhã phân tích tầm quan trọng của lời nói – công cụ thể hiện tư duy và nhân cách – đồng thời chỉ ra cách lựa chọn ngôn từ tinh tế để chinh phục lòng người. Sách bao gồm nhiều ví dụ thực tế, lời khuyên dễ áp dụng trong công việc, tình bạn, tình yêu và đàm phán. “Khéo Ăn Nói Sẽ Có Được Thiên Hạ” là bí kíp giúp người đọc giao tiếp tự tin và tạo ảnh hưởng tích cực trong xã hội.', 6, 180, 'active', NULL);
INSERT INTO `ebook` VALUES (181, 'K29.0', 'Sức Mạnh Của Thói Quen – Charles Duhigg', 145000.00, 'Charles Duhigg, phóng viên của The New York Times, giải thích khoa học đằng sau việc hình thành và thay đổi thói quen. Ông giới thiệu “vòng lặp thói quen” gồm tín hiệu, hành động và phần thưởng – cơ chế điều khiển hành vi con người. Thông qua các câu chuyện từ doanh nghiệp, vận động viên đến đời sống cá nhân, Duhigg cho thấy cách ta có thể tái lập thói quen để đạt thành công và hạnh phúc hơn. Cuốn sách là sự kết hợp giữa nghiên cứu khoa học, câu chuyện thực tế và chiến lược ứng dụng hiệu quả.', 6, 181, 'active', NULL);
INSERT INTO `ebook` VALUES (182, 'K30.0', 'Quẳng Gánh Lo Đi Và Vui Sống – Dale Carnegie', 120000.00, 'Một trong những tác phẩm truyền cảm hứng nổi tiếng nhất của Dale Carnegie, hướng dẫn cách vượt qua lo âu và sống bình an. Ông chia sẻ những nguyên tắc thực tế để giảm căng thẳng: tập trung vào hiện tại, chấp nhận điều không thể thay đổi, và hành động thay vì sợ hãi. Cuốn sách chứa đựng hàng trăm ví dụ thật từ những người đã tìm lại niềm vui sau khi thay đổi tư duy. Với giọng văn giản dị và gần gũi, đây là liều thuốc tinh thần quý giá giúp con người sống tích cực hơn mỗi ngày.', 6, 182, 'active', NULL);
INSERT INTO `ebook` VALUES (183, 'K31.0', 'Đi Tìm Lẽ Sống – Viktor E. Frankl', 135000.00, '“Đi Tìm Lẽ Sống” là bản dịch tiếng Việt của Man’s Search for Meaning, tác phẩm kinh điển của bác sĩ tâm thần người Áo Viktor E. Frankl. Dựa trên trải nghiệm thật trong trại tập trung Đức Quốc Xã, Frankl kể lại hành trình tìm ý nghĩa sống giữa đau khổ tột cùng. Ông chỉ ra rằng con người không thể tránh khỏi khổ đau, nhưng có thể lựa chọn cách đối diện với nó bằng thái độ và mục đích sống. Tác phẩm giới thiệu liệu pháp “logotherapy” – trị liệu bằng ý nghĩa – giúp con người tìm lại giá trị tinh thần và sức mạnh vượt qua nghịch cảnh. Đây là cuốn sách sâu sắc, nhân văn và có sức lay động lâu dài.', 6, 183, 'active', NULL);
INSERT INTO `ebook` VALUES (186, 'N1.0', '30 Món Ăn Chay Giàu Dinh Dưỡng (Lý Ngân Hoán)', 37000.00, 'Danh sách 30 món chay đơn giản và dễ làm, đặc biệt dành cho những người mới bắt đầu học nấu và thưởng thức ẩm thực chay.', 7, 186, 'active', NULL);
INSERT INTO `ebook` VALUES (187, 'N2.0', '170 Món Ăn Chay (Võ Thị Hòa)', 40000.00, 'Công thức chế biến của 170 món ăn chay, lý tưởng cho những người mới bắt đầu hoặc đang lập kế hoạch ăn chay định kỳ cho bản thân và gia đình. Với 170 món ăn này, bạn sẽ có một thực đơn khoa học và đầy đủ dinh dưỡng', 7, 187, 'active', NULL);
INSERT INTO `ebook` VALUES (188, 'N3.0', 'Tuyệt Kỹ 500 Công Thức Nấu Ăn Chay (Đại sứ Trí tuệ Team)', 49000.00, 'Tuyển tập 500 món chay này không chỉ là một bộ sưu tập đa dạng với từng vùng miền, mà còn là kho kiến thức ẩm thực chay hoàn hảo. Với sự tổng hợp tỉ mỉ và đầy đủ, cuốn sách nấu ăn này là nguồn cảm hứng không thể thiếu cho những ai đam mê ẩm thực chay. Dành cho cả những người ăn chay trung thành và những chủ nhà hàng chuyên kinh doanh món chay, đây chắc chắn sẽ là nguồn tài liệu hữu ích và đáng giá', 7, 188, 'active', NULL);
INSERT INTO `ebook` VALUES (189, 'N4.0', 'Bánh Tây Phương (Nguyễn Thu Dung - Nguyễn Thị Thanh)', 50000.00, 'Cách tạo ra những siêu phẩm bánh Âu, bánh ngọt, bánh kem thơm ngon ngất ngây, từ bánh bông lan mềm mịn cho đến các loại bánh mỳ đa dạng hấp dẫn', 7, 189, 'active', NULL);
INSERT INTO `ebook` VALUES (190, 'N5.0', 'Các món chè & Bánh Truyền Thống (Kim Phượng)', 25000.00, 'Là kho tàng văn hóa ẩm thực với cách pha chế tinh tế của những món chè truyền thống như chè đậu đỏ, chè đỗ đen, chè hạt sen, chè khúc bạch.... cùng những hương vị đặc trưng từ các món bánh truyền thống như bánh xèo, bánh rán, bánh nướng, bánh dẻo...', 7, 190, 'active', NULL);
INSERT INTO `ebook` VALUES (191, 'N6.0', 'Món Ngon Chế BIến Từ Chocolate (Lê Thanh Xuân)', 60000.00, 'Khám phá sức mạnh của socola trong việc tạo nên những công thức bánh ngọt, kẹo thơm ngon và đồ uống hấp dẫn, một lựa chọn lý tưởng cho những tín đồ nồng nhiệt của nghệ thuật làm bánh.', 7, 191, 'active', NULL);
INSERT INTO `ebook` VALUES (192, 'N7.0', '120 Món Súp Bổ Dưỡng Cho Trẻ Em Và Người Bệnh (Mỹ Hạnh)', 78000.00, 'Những món xúp đa dạng, bổ dưỡng phù hợp với trẻ nhỏ và người mới bình phục, chế biến từ những nguyên liệu đơn giản, dễ dàng tạo nên bữa ăn hấp dẫn và đầy dinh dưỡng.', 7, 192, 'active', NULL);
INSERT INTO `ebook` VALUES (193, 'N8.0', '150 Món Ăn Ngon Của Bé (Tạ Ngọc Ái - Phạm Quốc Bảo)', 70000.00, 'Danh sách 150 món ngon cho bé theo từng độ tuổi, đem đến sự đa dạng và phù hợp cho khẩu vị của các bé yêu trong gia đình.', 7, 193, 'active', NULL);
INSERT INTO `ebook` VALUES (194, 'N9.0', 'Ăn Dặm Bé Chỉ Huy (Gill Rapley & Tracey Murkett)', 79000.00, 'Phương pháp dặm tiên phong không cần dụng cụ truyền thống như thìa, muỗng, giúp cho bé trở nên tự chủ hơn trong việc lựa chọn thực phẩm và ăn uống. Bằng cách này, bé có thể tự do thảnh thơi thưởng thức món ăn mà mình lựa chọn, tạo ra một môi trường thoải mái và tự nhiên. Tuy nhiên, điều này vẫn cần phối hợp cùng nhiều phương pháp khác để mang lại hiệu quả tối đa.', 7, 194, 'active', NULL);
INSERT INTO `ebook` VALUES (195, 'N10.0', 'Ăn Dặm Không Nước Mắt (Nguyễn Thị Ninh - Mẹ Xoài)', 95000.00, 'Câu chuyện chăm sóc con không giống ai của mẹ Xoài tại xứ sở hoa anh đào. Bằng việc học hỏi phương pháp nuôi dạy con khoa học từ bà mẹ Nhật, mẹ Xoài đã chắc chắn thú vị trong việc chia sẻ kiến thức và kinh nghiệm trong quyển sách này, giúp nhiều bà mẹ trẻ tự tin hơn trong hành trình nuôi con nhỏ.', 7, 195, 'active', NULL);
INSERT INTO `ebook` VALUES (196, 'N11.0', 'Ăn Dặm Kiểu Nhật (Mẹ Ổi Mít)', 141000.00, 'Kho tàng những bí quyết ăn dặm độc đáo từ đất nước mặt trời mọc - Nhật Bản.', 7, 196, 'active', NULL);
INSERT INTO `ebook` VALUES (197, 'N12.0', 'Sổ Tay Ăn Dặm Của Mẹ (BS. Lê Thị Hải)', 94000.00, 'Chia sẻ vô giá về dinh dưỡng ăn dặm từ chuyên gia BS. Lê Thị Hải, người đã dày công suốt 30 năm tại Viện Dinh dưỡng Quốc Gia. Đây không chỉ là nguồn kiến thức đáng tin cậy và uy tín mà còn là hành trang quý giá giúp các bà mẹ trẻ nuôi con nhỏ một cách thông thái và hiểu biết.', 7, 197, 'active', NULL);
INSERT INTO `ebook` VALUES (198, 'N13.0', '100 Món Ăn Ngon Christine Hà (Cristine Hà - Vua Đầu Bếp  Mỹ 2012)', 100000.00, 'Khám phá bí quyết nấu ăn thông minh với 100 món ngon từ bàn tay tài năng của Christine Hà - Nữ hoàng bếp Việt tại Mỹ năm 2012.', 7, 198, 'active', NULL);
INSERT INTO `ebook` VALUES (199, 'N14.0', '555 Món Ăn Việt Nam - Kỹ Thuật Chế Biến Và Giá Trị Dinh Dưỡng (Trường Đại Học Thương Mại Hà Nội)', 50000.00, 'Là tài liệu đào tạo sinh viên chính quy các ngành nấu ăn, nhà hàng, khách sạn được tổng hợp từ nhiều nguồn bởi những giảng viên giàu kinh nghiệm. Sử dụng cuốn này sẽ những người nội trợ nâng cao kỹ năng nấu nướng; đối với người kinh doanh hoặc đầu bếp đây là tài liệu nâng cao chuyên môn.', 7, 199, 'active', NULL);
INSERT INTO `ebook` VALUES (200, 'N15.0', 'Chế Biến Món Ăn Bằng Lò Vi Sóng - Món Bò, Gà, Lợn (Thu Thủy)', 39000.00, 'Trong cuộc sống hiện đại, gần gia đình nào cũng có lò vi sóng để hâm nóng thức ăn khi cần. Tuy nhiên, lò vi sóng có khả năng nấu nướng đa dạng hơn thế. Tác giả đã tổng hợp cách chế biến món ăn bằng lò vi sóng ra 3 cuốn sách về 3 loại nguyên liệu: Bò, gà, lợn; Món điểm tâm; Món hải sản, rau, canh.', 7, 200, 'active', NULL);
INSERT INTO `ebook` VALUES (201, 'N16.0', 'Chế Biến Món Ăn Bằng Lò Vi Sóng - Món Điểm Tâm (Thu Thủy)', 39000.00, 'Trong cuộc sống hiện đại, gần gia đình nào cũng có lò vi sóng để hâm nóng thức ăn khi cần. Tuy nhiên, lò vi sóng có khả năng nấu nướng đa dạng hơn thế. Tác giả đã tổng hợp cách chế biến món ăn bằng lò vi sóng ra 3 cuốn sách về 3 loại nguyên liệu: Bò, gà, lợn; Món điểm tâm; Món hải sản, rau, canh.', 7, 201, 'active', NULL);
INSERT INTO `ebook` VALUES (202, 'N17.0', 'Chế Biến Món Ăn Bằng Lò Vi Sóng - Hải Sản, Rau, Canh (Thu Thủy)', 39000.00, 'Trong cuộc sống hiện đại, gần gia đình nào cũng có lò vi sóng để hâm nóng thức ăn khi cần. Tuy nhiên, lò vi sóng có khả năng nấu nướng đa dạng hơn thế. Tác giả đã tổng hợp cách chế biến món ăn bằng lò vi sóng ra 3 cuốn sách về 3 loại nguyên liệu: Bò, gà, lợn; Món điểm tâm; Món hải sản, rau, canh.', 7, 202, 'active', NULL);
INSERT INTO `ebook` VALUES (203, 'N18.0', 'Giáo Trình Thực Hành Chế Biến Món Ăn (Nguyễn Thị Tuyết - Uông Thị Toan)', 110000.00, 'Dùng cho sinh viên các trường cao đẳng, trung cấp, thương mại, du lịch. Là tài liệu tham khảo tốt dành cho những người đam mê nấu ăn.', 7, 203, 'active', NULL);
INSERT INTO `ebook` VALUES (204, 'N19.0', 'Kỹ Thuật Chế Biến 300 Món Ăn Ngon (Nhiều tác giả. Biên dịch: Thùy Linh)', 150000.00, 'Hướng cách cách chuẩn bị nguyên liệu, sơ chế, chế biến của 300 món ăn ngon.', 7, 204, 'active', NULL);
INSERT INTO `ebook` VALUES (205, 'N20.0', 'Kỹ Thuật Nấu Ăn Toàn Tập (Triệu Thị Chơi)', 150000.00, 'Tài liệu có độ dài 1315 trang, tổng hợp rất nhiều kỹ thuật nấu nướng, cắt tỉa, cắm hoa... Đây có thể coi là tài liệu hoàn thiện nhất tổng hợp các kỹ năng của người nấu ăn, đầu bếp nghiệp dư và chuyên nghiệp.', 7, 205, 'active', NULL);
INSERT INTO `ebook` VALUES (206, 'N21.0', 'Kỹ Thuật Chế Biến Các Món Lẩu Sốt Xúp (Lê Thanh Xuân)', 20000.00, 'Hướng dẫn chế biến các món lẩu, xốt, súp cho gia đình.', 7, 206, 'active', NULL);
INSERT INTO `ebook` VALUES (207, 'N22.0', 'Món Ngon Dễ Làm (Minh Thư)', 30000.00, 'Một số món ăn ngon với cách chế biến đơn giản cho bữa ăn gia đình.', 7, 207, 'active', NULL);
INSERT INTO `ebook` VALUES (208, 'N23.0', 'Quick & Easy (Ngọc Linh)', 80000.00, 'Tổng hợp những công thức nấu ăn đơn giản nhất và ít tốn thời gian.', 7, 208, 'active', NULL);
INSERT INTO `ebook` VALUES (209, 'N24.0', 'Hướng Dẫn Nấu Ăn 200 Món Truyền Thống (Nhiều tác giả)', 50000.00, 'Tài liệu được tổng hợp rất công phu về chuẩn bị nguyên liệu, sơ chế và công thức chế biến 200 món ăn truyền thống qua các vùng miền Việt Nam.', 7, 209, 'active', NULL);
INSERT INTO `ebook` VALUES (210, 'N25.0', '84 Món Nhậu Độc Đáo Việt Nam (Vua Đầu Bếp)', 40000.00, 'Văn hóa nhậu rất phổ biến ở Việt Nam, do đó cuốn sách này rất thích hợp trong mỗi gia đình để đãi khách hoặc liên hoan gia đình. Dĩ nhiên, không khuyến khích sử dụng rượu bia quá mức.', 7, 210, 'active', NULL);
INSERT INTO `ebook` VALUES (211, 'N26.0', 'Kỹ Thuật Chế Biến Trái Cây (Từ Triệu Hải - Cao Tích Vĩnh)', 120000.00, 'Hướng dẫn cách cắt tỉa, chế biến, bảo quản, sấy khô, làm mứt... của nhiều loại hoa quả phổ biến.', 7, 211, 'active', NULL);
INSERT INTO `ebook` VALUES (212, 'N27.0', 'Nấu Ăn Cho Người Già (Tần Trúc)', 30000.00, 'Chế độ nấu ăn cho người già cần được quan tâm. Đặc biệt cần chú trọng yếu tố cân bằng thay vì dinh dưỡng để đảm bảo sức khỏe cho người cao tuổi trong cuộc sống hiện đại.', 7, 212, 'active', NULL);
INSERT INTO `ebook` VALUES (213, 'N28.0', 'Nấu Món Ăn Hàn Quốc Thật Dễ (Tổng cục du lịch Hàn Quốc)', 50000.00, 'Quảng bá văn hóa ẩm thực Hàn Quốc với thế giới qua những món ăn Hàn Quốc truyền thống với cách chế biến đơn giản.', 7, 213, 'active', NULL);
INSERT INTO `ebook` VALUES (214, 'N29.0', 'Nghệ Thuật Nấu Ăn Vui Khỏe (Lima Ohsawa - Diệu Hạnh)', 60000.00, 'Sách dạy nấu ăn theo phương pháp thực dưỡng để cân bằng dinh dưỡng, lấy nguyên liệu chính từ gạo lứt.', 7, 214, 'active', NULL);
INSERT INTO `ebook` VALUES (215, 'N30.0', 'Sách Nấu Ăn Dưỡng Sinh Ohsawa (Nguyễn  Thị Thu Ba)', 50000.00, 'Là cuốn sách đề cập đến cân bằng âm dương trong chế biến món ăn để hòa hợp với tự nhiên, tăng cường sức khỏe, giảm bệnh tật.', 7, 215, 'active', NULL);
INSERT INTO `ebook` VALUES (217, 'T1.0', 'Ông và Cháu', 39000.00, 'Ông và Cháu là tập thơ thiếu nhi nổi bật của nhà thơ trào phúng Tú Mỡ (1900–1976), tên thật Hồ Trọng Hiếu, xuất bản lần đầu năm 1971 bởi Nhà xuất bản Kim Đồng, sau đó được tái bản nhiều lần. Đây là một trong số ít tác phẩm Tú Mỡ dành riêng cho trẻ em, thể hiện tình cảm ông cháu ấm áp, hóm hỉnh qua những vần thơ trong trẻo, gần gũi với đời sống thường ngày của các em nhỏ.\r\n\r\nTập thơ gồm nhiều bài ngắn, nổi bật như Thương Ông, Bé Nguyệt Làm Thơ, Cái Búp Tăng Gia, Con “Em Chị”… Mỗi bài là một câu chuyện nhỏ, tái hiện những khoảnh khắc giản dị, đáng yêu trong gia đình: cháu quạt cho ông, cháu tập làm thơ, cháu chăm sóc búp bê, cháu gọi em gái là “em chị”… Thơ có giọng điệu vui tươi, dí dỏm, giàu hình ảnh và nhạc điệu, lột tả thế giới hồn nhiên, ngộ nghĩnh của trẻ thơ và tình cảm yêu thương, tự hào của người ông dành cho cháu.\r\n\r\nVí dụ, trong bài Thương Ông, bé Việt thấy ông đau chân liền lon ton lại gần, ân cần đỡ ông lên thềm, rồi thủ thỉ nhắc ông “không đau! không đau! dù đau đến đâu, khỏi ngay lập tức”, khiến ông quên cả đau, sung sướng ôm cháu vào lòng. Hay ở Bé Nguyệt Làm Thơ, cô bé tập làm thơ nhưng vần điệu ngây ngô, khiến cả nhà cười nghiêng ngả. Cái Búp Tăng Gia kể về việc bé được giao nhiệm vụ “tăng gia sản xuất” bằng cách chăm sóc búp bê, nhưng lại làm mọi thứ rối tung, vừa buồn cười vừa đáng yêu. Con “Em Chị” lại là câu chuyện hài hước về cách trẻ nhỏ gọi em gái mình, thể hiện sự ngây thơ và logic riêng của trẻ.\r\n\r\nÔng và Cháu là tập thơ thiếu nhi hiếm hoi của Tú Mỡ, nơi ông tạm gác lối trào phúng sắc sảo để hóa thân thành người ông đôn hậu, hóm hỉnh, đầy tình yêu thương. Tập thơ không chỉ là những vần thơ kể chuyện, mà còn là bản đồng ca về tình cảm gia đình, sự gắn bó giữa các thế hệ, niềm vui sống trong trẻo, lạc quan của trẻ nhỏ.', 8, 217, 'active', NULL);
INSERT INTO `ebook` VALUES (218, 'T2.0', 'Lộc Biếc', 30000.00, 'Lộc Biếc là một tập thơ đặc biệt, tập hợp hơn 40 bài thơ được sáng tác bởi các học sinh trường phổ thông trung học năng khiếu Trần Phú, Hải Phòng, tuyển chọn từ cuộc thi thơ năm học 1991–1992. Tập thơ ra đời nhân dịp Xuân mới 1992, là kết quả của một sáng kiến giáo dục ý nghĩa từ Ban giám hiệu nhà trường, với mục tiêu khơi dậy, nuôi dưỡng tâm hồn, nhân cách và tinh thần sáng tạo văn chương trong thế hệ trẻ.\r\n\r\nCác bài thơ trong Lộc Biếc ghi lại dấu ấn tuổi học trò, phản ánh tâm tư, cảm xúc, hoài bão và những rung động đầu đời của những tâm hồn trẻ. Dưới ngòi bút non trẻ nhưng chân thành, các tác giả đã thể hiện cái nhìn trong trẻo, hồn nhiên về thế giới xung quanh: từ kỷ niệm gia đình, trường lớp, bạn bè, thầy cô, đến những trăn trở về cuộc sống, tương lai, lý tưởng và tình yêu tuổi mới lớn.', 8, 218, 'active', NULL);
INSERT INTO `ebook` VALUES (219, 'T3.0', 'Xứ Nevermoor Diệu Kỳ 3 - Morrigan Và Lời Triệu', 120000.00, 'Xứ Nevermoor Diệu Kỳ 3 – Morrigan Và Lời Triệu Hồi Của Wundersmith tiếp tục hành trình kỳ ảo của Morrigan Crow trong thế giới đầy bí ẩn và phép thuật của thành phố Nevermoor. Sau khi thoát khỏi lời nguyền chết chóc từ năm 11 tuổi, Morrigan đã gia nhập Hiệp hội Wundrous – tổ chức danh giá bảo vệ những người đặc biệt – và nhận huy hiệu chữ W danh giá, mở ra một cuộc đời mới đầy kỳ vọng.\r\n\r\nTrong tập này, Morrigan đối mặt với những thử thách mới: dịch bệnh bí ẩn mang tên “Bệnh Dịch Trống Rỗng” bắt đầu lan rộng, biến cư dân thành những sinh vật vô tri vô giác, gây hoang mang và đe dọa sự tồn vong của thành phố. Morrigan sớm nhận ra rằng chính cô là chìa khóa để tìm ra phương pháp chữa trị và chấm dứt dịch bệnh này. Đồng thời, cô khám phá ra sức mạnh tiềm ẩn của mình – là một Wundersmith có khả năng vô hạn, có thể điều khiển các phép thuật kỳ lạ và đối mặt với những kẻ thù nguy hiểm luôn rình rập.\r\n\r\nTrong hành trình khám phá bản thân, Morrigan phải vượt qua các thử thách trong bốn vòng thi kỳ lạ, đối mặt với những âm mưu đen tối, đồng thời giữ vững niềm tin vào chính mình và những người bạn trung thành. Liệu cô bé có thể vượt qua tất cả để bảo vệ Nevermoor và chính mình?', 8, 219, 'active', NULL);
INSERT INTO `ebook` VALUES (220, 'T4.0', 'Xứ Nevermoor Diệu Kỳ 1 – Morrigan Và Những Thử Thách Gay Cấn', 120000.00, 'Xứ Nevermoor Diệu Kỳ 1 – Morrigan Và Những Thử Thách Gay Cấn là tập mở đầu của bộ truyện kỳ ảo nổi tiếng dành cho thiếu nhi của Jessica Townsend, được ví như sự giao thoa giữa “Harry Potter” và “Alice ở xứ sở diệu kỳ”. Nhân vật chính Morrigan Crow là cô bé 11 tuổi sống tại thành phố Jackalfax, nước Cộng hòa Wintersea, mang trên mình “lời nguyền” khiến mọi người tin rằng cô là nguyên nhân của mọi tai họa và sẽ phải chết vào đúng sinh nhật lần thứ 11.\r\n\r\nTrong đêm định mệnh ấy, Morrigan bất ngờ được cứu bởi Jupiter North – một người đàn ông bí ẩn, người đã đưa cô thoát khỏi số phận nghiệt ngã và đến thành phố thần bí Nevermoor. Tại đây, Morrigan được hứa hẹn cơ hội gia nhập Hiệp hội Wundrous – tổ chức danh giá nhất xứ sở, nơi cô sẽ được bảo vệ và sống một cuộc đời mới. Tuy nhiên, để trở thành thành viên chính thức, Morrigan phải vượt qua bốn thử thách kỳ lạ và gay cấn, đòi hỏi cô phải thể hiện tài năng đặc biệt của bản thân – điều mà chính Morrigan cũng không chắc mình có.\r\n\r\nHành trình của Morrigan là chuỗi ngày khám phá bản thân, đối mặt với những thử thách: Thử thách Sách, Thử thách Săn đuổi, Thử thách Kinh hoàng và Thử thách Thể hiện. Trong quá trình ấy, cô kết bạn, phát hiện sức mạnh tiềm ẩn, đồng thời phải đối đầu với những kẻ thù nguy hiểm và những bí ẩn lớn của Nevermoor. Từ một cô bé bị ruồng bỏ, Morrigan dần trưởng thành, dũng cảm và tìm thấy giá trị của bản thân trong thế giới nhiệm màu này.', 8, 220, 'active', NULL);
INSERT INTO `ebook` VALUES (221, 'T5.0', 'Xứ Nevermoor Diệu Kỳ 2 – Morrigan Và Dịch Bệnh Trống Rỗng', 40000.00, 'Xứ Nevermoor Diệu Kỳ 2 – Morrigan Và Dịch Bệnh Trống Rỗng (tựa gốc: Wundersmith: The Calling of Morrigan Crow) tiếp nối hành trình kỳ ảo của Morrigan Crow tại thành phố Nevermoor sau khi cô vượt qua các thử thách và chính thức trở thành thành viên của Hiệp hội Wundrous. Morrigan giờ đây sở hữu huy hiệu chữ W danh giá, được bảo vệ bởi các đặc quyền, có bạn bè trung thành và một gia đình mới – điều mà cô luôn khao khát từ thuở nhỏ.\r\n\r\nTuy nhiên, Nevermoor không còn là xứ sở nhiệm màu bình yên. Một dịch bệnh bí ẩn mang tên “Trống rỗng” bất ngờ bùng phát, lây lan khắp thành phố, biến những người lai (những cư dân có khả năng đặc biệt hoặc mang dòng máu pha trộn) thành những sinh vật vô tri vô giác, mất hết ký ức và bản ngã. Sự hoang mang, hoảng loạn bao trùm Nevermoor khi dịch bệnh ngày càng lan rộng, đe dọa sự tồn vong của cả thành phố.\r\n\r\nTrong vai trò mới, Morrigan không chỉ phải học cách kiểm soát sức mạnh của mình, đối mặt với những định kiến và sự sợ hãi từ cộng đồng, mà còn dấn thân vào hành trình tìm kiếm phương pháp chữa trị, chấm dứt dịch bệnh Trống rỗng. Cô bé phải vượt qua những thử thách mới, đối đầu với kẻ thù nguy hiểm và khám phá những bí mật đen tối của Hiệp hội Wundrous cũng như chính bản thân mình. Morrigan dần nhận ra rằng, để cứu lấy Nevermoor và những người cô yêu quý, cô phải chấp nhận và phát huy năng lực đặc biệt của mình, dù điều đó khiến cô càng trở nên khác biệt và bị nghi ngờ hơn bao giờ hết.', 8, 221, 'active', NULL);
INSERT INTO `ebook` VALUES (222, 'T6.0', 'Lô Bô Chúa tể vùng Ca Răm Pô (Lobo Chúa Tể Currumpaw)', 80000.00, '“Lô Bô – Chúa tể vùng Ca Răm Pô” của tác giả Ernest Thompson Seton, được dịch bởi Nguyễn Tâm, là một câu chuyện cảm động về cuộc sống của một con sói tên là Lô Bô. Câu chuyện diễn ra vào thế kỷ 19 tại vùng Currumpaw, nơi Lô Bô trở thành đầu đàn của một bầy sói xám.\r\n\r\nLô Bô nổi tiếng với sự thông minh và khả năng lãnh đạo, nhưng cũng phải đối mặt với những khó khăn trong việc sinh tồn. Anh ta không chỉ là một kẻ săn mồi mà còn là một người bảo vệ cho bầy sói của mình. Tuy nhiên, sự xuất hiện của con người, đặc biệt là những người chăn cừu và thợ săn, đã tạo ra nhiều mối đe dọa cho cuộc sống của Lô Bô và bầy sói.\r\n\r\nCâu chuyện thể hiện cuộc chiến giữa thiên nhiên và con người, đồng thời khám phá những giá trị như lòng dũng cảm, tình yêu thương và sự hi sinh. Qua hành trình của Lô Bô, độc giả sẽ cảm nhận được nỗi cô đơn và kiêu hãnh của một con sói sống trong thế giới đầy rẫy những thử thách. Mời các bạn tải đọc sách Lô Bô – Chúa tể vùng Ca Răm Pô (Lobo Chúa Tể Currumpaw) của tác giả Ernest Thompson Seton & Nguyễn Tâm (dịch).', 8, 222, 'active', NULL);
INSERT INTO `ebook` VALUES (223, 'T7.0', 'Tôi là Coriander', 30000.00, '“Tôi là Coriander” của tác giả Sally Gardner là một cuốn tiểu thuyết thiếu nhi mang đậm yếu tố lịch sử và phép thuật, kể về cuộc đời của Coriander Hobie, một cô gái sống ở London vào thế kỷ 17. Câu chuyện bắt đầu khi Coriander được sinh ra trong một gia đình có truyền thống làm thuốc và có mối liên hệ với những bí ẩn của thế giới phép thuật.\r\n\r\nKhi mẹ cô biến mất một cách bí ẩn, Coriander phát hiện ra rằng cô có khả năng đặc biệt trong việc sử dụng ma thuật. Cô bắt đầu cuộc hành trình tìm kiếm mẹ và khám phá những bí mật về bản thân. Trong hành trình này, Coriander gặp gỡ nhiều nhân vật thú vị, từ những người bạn trung thành đến những kẻ thù nguy hiểm. Cô cũng phải đối mặt với những thử thách khó khăn, từ cuộc sống hàng ngày cho đến những âm mưu chính trị trong xã hội.\r\n\r\nCuốn sách không chỉ là một câu chuyện phiêu lưu mà còn khám phá các chủ đề như tình yêu, lòng dũng cảm và sự trưởng thành. Qua các tình huống khác nhau, Coriander học được nhiều bài học quý giá về bản thân và thế giới xung quanh.\r\n\r\nMời các bạn tải đọc sách Tôi là Coriander của tác giả Sally Gardner.', 8, 223, 'active', NULL);
INSERT INTO `ebook` VALUES (224, 'T8.0', 'Nha Sĩ Yêu Quái', 50000.00, '“Nha Sĩ Yêu Quái” của tác giả David Walliams, được dịch bởi Lâm Quốc Hoa, là một câu chuyện hài hước và kỳ thú dành cho thiếu nhi. Cuốn sách kể về một cậu bé tên là Alfie, người sống trong một thị trấn nơi mà những điều kỳ quái thường xuyên xảy ra. Thay vì nhận được những đồng xu lấp lánh từ bà tiên răng khi nhổ răng, Alfie cùng các bạn lại tìm thấy những món đồ lạ lùng như con ốc sên chết hay con nhện sống.\r\n\r\nCâu chuyện bắt đầu khi Alfie phát hiện ra rằng có một nha sĩ bí ẩn đang hoạt động trong thị trấn, người không chỉ chữa răng mà còn có những hành động kỳ quái khác. Khi những sự việc lạ lùng xảy ra, Alfie và bạn bè quyết định điều tra, dẫn đến những tình huống dở khóc dở cười và những khám phá bất ngờ về nha sĩ này.\r\n\r\nCuốn sách không chỉ mang đến những giây phút giải trí mà còn chứa đựng nhiều thông điệp về tình bạn, sự dũng cảm và việc đối mặt với nỗi sợ hãi.\r\n\r\nMời các bạn tải đọc sách Nha Sĩ Yêu Quái của tác giả David Walliams', 8, 224, 'active', NULL);
INSERT INTO `ebook` VALUES (225, 'T9.0', 'Lại thằng nhóc Emil', 50000.00, 'Tóm tắt & Review (Đánh Giá) cuốn sách Lại Thằng Nhóc Emil của tác giả Astrid Lindgren do Vũ Hương Giang dịch\r\n“Lại Thằng Nhóc Emil” của tác giả Astrid Lindgren, được dịch bởi Vũ Hương Giang, là câu chuyện hài hước và đầy màu sắc về một cậu bé nghịch ngợm tên là Emil sống tại trang trại ở làng Lönneberga. Emil là một cậu bé thông minh, nhanh nhẹn và luôn tìm cách gây rối, khiến cho mọi người xung quanh phải bất ngờ với những trò đùa của mình.\r\n\r\nCâu chuyện được xây dựng qua nhiều chương nhỏ, mỗi chương là một cuộc phiêu lưu mới của Emil, từ việc giúp đỡ cha mẹ đến những trò nghịch ngợm khiến cả làng phải dở khóc dở cười. Emil có một cô em gái dễ thương tên là Ida, và mặc dù thường xuyên gặp rắc rối, cậu vẫn luôn giữ được tình yêu thương từ gia đình, đặc biệt là từ mẹ cậu, người luôn kiên nhẫn với những trò quậy phá của con trai.\r\n\r\nLại Thằng Nhóc Emil! – đấy là câu nói cửa miệng của dân làng Lonneberga, tỉnh Smaland, Thụy Điển mỗi khi họ phát hiện ra một trò nghịch ngợm tai quái nào đó. Chẳng có ai ngoài thằng nhóc Emil ở trang trại Katthult có thể nghĩ ra những trò quái đản ấy. Như việc treo em gái Ida lên cột cờ để cho cô bé thấy được Ma-ri-anne-lu-nd; Emil nhốt bố trong nhà vệ sinh; Elim chui đầu vào liễn súp… Emil đẽo đến hình nhân số 100 ở xưởng mộc – mỗi lần bị bố phạt nhốt trong xưởng mộc Emil lại ngồi đẽo một hình nhân.\r\n\r\nNhững trò nghịch ngợm dở khóc dở cười của Emil làm mọi người tức điên. Ông bố thì bứt tóc kêu trời, bà mẹ thì cầu nguyện và ghi lại nhật ký, dân làng thì nói vợ chồng họ thật đáng thương. Bởi Emil nghịch ngợm quá thể. Nhưng nếu không có Emil ở đó, chắc là họ sẽ nhớ nó đến phát khóc mất.\r\n\r\nCuộc sống nhiều mệt nhọc, lo toan. Có lúc tưởng chừng ta không còn bước nổi và cứ mong được trở lại những ngày thơ bé. Nhưng mọi thứ sẽ được sắp xếp lại khi ta bật tiếng cười một cách hồn nhiên. Như việc ta ngồi cười ngặt nghẽo khi tìm hiểu những trò nghịch ngợm của nhóc Emil.\r\n\r\nMỗi một trang sách như một trang nhật kí, như một chuyến hành trình thi vị nên thơ dắt ta về một thời bé dại – cái thời mà ta thấy thế giới và con người thật đẹp. Có lẽ chúng ta không nên bắt mình phải nhìn mọi thứ bằng sắc hồng rực rỡ, nhưng sao ta không thử tận hưởng cuộc sống này bằng đôi mắt lạc quan của trẻ thơ. Để mỗi ngày trôi qua, chuyến xe cuộc đời sẽ luôn đầy tiếng cười hạnh phúc. Đôi khi trong cuộc sống, niềm vui không đến từ những thứ to tát, vĩ đại mà đơn giản nó đến từ những gì bình dị và gần gũi nhất. Như những niềm vui be bé, son sẻ mà ta góp nhặt được từ những trò nghịch ngợm ấu thơ của Lại Thằng Nhóc Emil!.', 8, 225, 'active', NULL);
INSERT INTO `ebook` VALUES (226, 'T10.0', 'Những Tấm Lòng Cao Cả', 40000.00, '“Những Tấm Lòng Cao Cả” (tiếng Ý: Cuore, nghĩa là “Trái tim”) là một tiểu thuyết nổi tiếng của nhà văn người Ý Edmondo De Amicis, xuất bản lần đầu vào năm 1886. Tác phẩm được viết dưới dạng nhật ký của Enrico Bottini, một cậu bé 11 tuổi học tiểu học ở Turin. Qua những trang nhật ký, Enrico ghi lại những trải nghiệm, cảm xúc và bài học quý giá trong suốt năm học của mình.\r\n\r\nCâu chuyện diễn ra trong bối cảnh nước Ý đang trong quá trình thống nhất và phản ánh những vấn đề xã hội như tình yêu thương, lòng nhân ái, sự hy sinh và tinh thần yêu nước. Enrico kể về những người bạn cùng lớp với đủ tính cách khác nhau, từ những cậu bé tốt bụng như Garone đến những cậu bé hư hỏng như Franti. Mỗi nhân vật đều mang đến cho Enrico những bài học cuộc sống quý giá.\r\n\r\nTác phẩm không chỉ dừng lại ở việc mô tả cuộc sống hàng ngày của Enrico mà còn mở rộng ra các mối quan hệ gia đình, tình thầy trò và tình bạn. Qua đó, De Amicis truyền tải thông điệp về sự cao cả của tấm lòng con người và giá trị của tình yêu thương trong cuộc sống.', 8, 226, 'active', NULL);
INSERT INTO `ebook` VALUES (227, 'T11.0', 'Bà Ngoại Phù Thủy Và Mùa Hè Tập Sự', 80000.00, '“Bà Ngoại Phù Thủy Và Mùa Hè Tập Sự” (tựa gốc: Nishi No Majo Ga Shinda) là một cuốn tiểu thuyết thiếu nhi của tác giả Kaho Nashiki, kể về cuộc phiêu lưu kỳ thú của một cô bé tên là Kanna. Câu chuyện bắt đầu khi Kanna được gửi đến sống cùng bà ngoại, một phù thủy nổi tiếng trong thế giới phép thuật.\r\n\r\nTrong suốt mùa hè, Kanna không chỉ học hỏi về phép thuật mà còn khám phá những bí mật về gia đình và nguồn gốc của sức mạnh phù thủy. Bà ngoại của Kanna đã qua đời, để lại cho cô những bài học quý giá và những kỷ niệm đáng nhớ. Thông qua những trải nghiệm này, Kanna dần trưởng thành, hiểu rõ hơn về bản thân và thế giới xung quanh. Cuốn sách không chỉ đơn thuần là một câu chuyện về phép thuật mà còn chứa đựng nhiều thông điệp sâu sắc về tình cảm gia đình, sự trưởng thành và cách đối mặt với mất mát.', 8, 227, 'active', NULL);
INSERT INTO `ebook` VALUES (228, 'T12.0', 'Charlie Và Nhà Máy Chocolate', 60000.00, '“Charlie và Nhà máy Sô-cô-la” là một tiểu thuyết thiếu nhi nổi tiếng của tác giả Roald Dahl, xuất bản lần đầu vào năm 1964. Câu chuyện xoay quanh cậu bé Charlie Bucket, sống trong cảnh nghèo khó cùng gia đình trong một ngôi nhà nhỏ. Cha cậu làm việc vất vả nhưng thu nhập không đủ nuôi sống cả gia đình, bao gồm bốn ông bà nội và mẹ cậu đang bệnh tật\r\n\r\nMột ngày, Willy Wonka, chủ sở hữu nhà máy sô-cô-la nổi tiếng, thông báo về cuộc thi giấu năm chiếc vé vàng trong các thanh sô-cô-la. Những ai tìm thấy vé sẽ được tham quan nhà máy và nhận sô-cô-la miễn phí trong một năm. Charlie, mặc dù rất nghèo, vẫn hy vọng tìm được vé vàng. Cuối cùng, cậu đã may mắn tìm thấy một chiếc vé bằng cách mua thanh sô-cô-la bằng tiền của ông nội\r\n\r\nTrong chuyến tham quan nhà máy, Charlie cùng bốn đứa trẻ khác chứng kiến những điều kỳ diệu và bí ẩn trong thế giới sô-cô-la. Tuy nhiên, từng đứa trẻ đều gặp phải những tình huống hài hước nhưng cũng đầy bài học về tính cách của mình: Augustus Gloop bị hút vào ống dẫn sô-cô-la vì tham lam; Violet Beauregarde trở thành quả việt quất do ăn kẹo cao su chưa hoàn thiện; Veruca Salt bị ném vào thùng rác bởi những con sóc; còn Mike Teavee bị teo nhỏ do mắc kẹt trong tivi. Cuối cùng, chỉ còn lại Charlie, người đã chứng minh được phẩm hạnh và sự tốt bụng của mình, và được Willy Wonka chọn làm người kế thừa nhà máy.', 8, 228, 'active', NULL);
INSERT INTO `ebook` VALUES (229, 'T13.0', 'Thay mẹ cha gánh vác sơn hà', 40000.00, '“Thay Mẹ Cha Gánh Vác Sơn Hà” là tác phẩm của tác giả Đoàn Công Lê Huy, tập hợp những bài viết sâu sắc và đầy cảm xúc về cuộc sống, gia đình và trách nhiệm của con cái đối với cha mẹ. Qua các bài viết, tác giả chia sẻ những trải nghiệm cá nhân và quan sát của mình về tình cảm gia đình, đặc biệt là lòng hiếu thảo và sự biết ơn đối với công lao của cha mẹ.\r\n\r\nCuốn sách không chỉ đơn thuần là những câu chuyện mà còn là những bài học quý giá về cách sống, cách đối diện với khó khăn trong cuộc sống. Tác giả khuyến khích độc giả hãy gánh vác trách nhiệm và không ngừng cố gắng để làm cho cha mẹ tự hào. Những hình ảnh và ngôn từ giản dị nhưng đầy sức nặng trong từng trang sách khiến người đọc dễ dàng cảm nhận được tình yêu thương và sự hy sinh của cha mẹ.', 8, 229, 'active', NULL);
INSERT INTO `ebook` VALUES (230, 'T14.0', 'Công Chúa Nhỏ Chăn Cừu', 40000.00, '“Công Chúa Nhỏ Chăn Cừu” của tác giả Nguyễn Thị Kim Hòa là một tác phẩm dành cho thiếu nhi, mang đến những câu chuyện đầy màu sắc và ý nghĩa về tình bạn, sự khám phá và những bài học cuộc sống. Cuốn sách xoay quanh cuộc sống của một cô bé chăn cừu, người có mơ ước trở thành công chúa trong lòng mọi người.\r\n\r', 8, 230, 'active', NULL);
INSERT INTO `ebook` VALUES (231, 'T15.0', 'Bông Hồng Trên Ngọn Đồi Xanh', 50000.00, 'Nhân vật Rose Campbell trong Bông Hồng Trên Ngọn Đồi Xanh – bông hồng đáng yêu, duyên dáng – có hoàn cảnh đặc biệt: mẹ không còn, cha vừa mới mất. Cô bé được các bà đưa về chăm sóc ở Ngọn đồi xanh. Ở đây, cô được làm quen với gia đình quý tộc Campbell có cỗi nguồn Scotland giàu có với nhiều thế hệ: những người bà, những người thím, các ông chú và 7 người anh em họ hiếu động, nghịch ngợm. Mặc dầu cô bé được quan hoài nuôi dưỡng quá mức cấp thiết nhưng những người lớn tỏ ra vô cùng lo lắng cho sinh linh yếu ớt và nhút nhát ấy. Cô bé được chú Alec nhận làm người giám hộ với lời cam kết sẽ thay đổi cô bé trong vòng 1 năm. Không biết cánh bướm u buồn ấy có thể hoà nhập thế nào với thế giới mới?\n\n', 8, 231, 'active', NULL);
INSERT INTO `ebook` VALUES (232, 'T16.0', 'Người Bạn Phi Thường', 40000.00, 'Cuốn sách “Người Bạn Phi Thường” là phần mở đầu trong bộ tứ tác phẩm của Elena Ferrante, mô tả tuổi thơ và tuổi teen của Elena và Lila, hai cô bé sống trong một khu phố nghèo của Napoli, Ý vào những năm 1950. Trên nền của cuộc sống khắc nghiệt ở thành phố Napoli, hai cô bé học cách dựa vào nhau để vượt qua mọi thách thức. Trên hành trình trưởng thành, qua những lần chia ly và đoàn tụ, Elena và Lila vẫn duy trì mối quan hệ đặc biệt, với số phận của mỗi người phản ánh lên cuộc sống của người kia. Elena Ferrante, qua góc nhìn của cô bé Elena, khắc họa những biến đổi của Napoli và Italy trong giai đoạn hậu chiến tranh, thể hiện sự phức tạp trong mối quan hệ giữa hai cô gái nhỏ.\r\n\r\n“Người Bạn Phi Thường” đã nhanh chóng trở thành best-seller tại Ý khi được xuất bản lần đầu vào năm 2011, và được dịch sang nhiều ngôn ngữ trên toàn thế giới. Phần đầu tiên của bộ sách đã được chuyển thể thành bộ phim truyền hình cùng tên do Saverio Costanzo đạo diễn. Elena Ferrante cũng được tạp chí Time của Mỹ xếp vào danh sách 100 nhân vật ảnh hưởng nhất trên thế giới năm 2016, thể hiện sức ảnh hưởng lớn mà tác phẩm của bà gây ra.', 8, 232, 'active', NULL);
INSERT INTO `ebook` VALUES (233, 'T17.0', 'Đếm Sao - Lois Lowry', 80000.00, '“Đếm Sao” là một tác phẩm văn học thiếu nhi nổi tiếng của nhà văn Lois Lowry, được biết đến với lối kể chuyện nhẹ nhàng, sâu lắng và những chủ đề nhân văn sâu sắc. Cuốn sách đã chạm đến trái tim của hàng triệu độc giả trên thế giới và được dịch sang nhiều ngôn ngữ, trong đó có tiếng Việt.', 8, 233, 'active', NULL);
INSERT INTO `ebook` VALUES (234, 'T18.0', 'Cô Bé Uống Ánh Trăng', 80000.00, 'Cuốn sách “Cô Bé Uống Ánh Trăng” mở đầu với một câu chuyện ở Bảo Hộ Quốc, một nơi u ám và buồn tẻ. Các nhân dân ở đó tin rằng việc hiến tế một đứa trẻ sơ sinh cho mụ phù thủy độc ác mỗi năm sẽ ngăn chặn các tai họa. Mặc dù gia đình đau khổ, không ai dám chống lại cho đến khi một bà mẹ mạnh mẽ đứng lên tận răng để bảo vệ con.\r\n\r\nCuộc sống tại Bảo Hộ Quốc cất giấu nhiều bí mật, và sau vụ việc kia, những câu chuyện kỳ diệu bắt đầu được phơi bày. Hinterland rợp mây sương, bên cạnh đầm lầy u ám và núi lửa sôi sùng sục, là một thế giới kỳ bí dành cho các đứa trẻ bị hiến tế.\r\n\r\nLuna, cô bé được cứu bởi phù thủy Xan sau khi uống ánh trăng, trở thành người mang sức mạnh ma thuật mạnh mẽ. Lo sợ sức mạnh của Luna, Xan quyết định nuôi dưỡng cô bé và đặt tên là Luna. Luna lớn lên trong một môi trường đầy hạnh phúc và yêu thương cùng Xan, và sức mạnh ma thuật của cô bắt đầu hiện lên khi cô bước vào tuổi 13.\r\n\r\nTruyện Cô Bé Uống Ánh Trăng kéo dài với sự xuất hiện của mẹ ruột của Luna, một thợ mộc trẻ tới từ Bảo Hộ Quốc để tiêu diệt phù thủy, và Xan cùng Luna, Glerk và Fyrian – một con quái vật và một chú rồng – hành động để bảo vệ hòa bình. Các nhân vật đa dạng, mỗi người mang theo quan điểm và kiến thức riêng, khiến câu chuyện trở nên cuốn hút và sâu sắc.\r\n\r\nCuối cùng, thông điệp của câu chuyện là ai cũng có thể tìm ra nơi thực sự thuộc về và hóa giải nỗi buồn và bất hạnh trong cuộc sống của mình.', 8, 234, 'active', NULL);
INSERT INTO `ebook` VALUES (235, 'T19.0', 'Crenshaw: Chú Mèo Lướt Ván', 99000.00, 'Cuốn sách “Crenshaw – Chú mèo lướt ván” là một bức tranh chân thực về cuộc sống khó khăn, nỗi lo sợ và sự đau khổ hàng ngày mà gia đình cậu bé Jackson phải đối diện. Jackson đại diện cho những gia đình đang gặp khó khăn về tài chính và đối mặt với nỗi sợ về việc trở thành người vô gia cư ở Mỹ. Cuốn sách được viết bởi nhà văn Mỹ Katherine Applegate, người đã nhận Huân chương Newbery vào năm 2013.\r\n\r\nCuốn sách Crenshaw: Chú Mèo Lướt Ván kể về cuộc sống của Jackson, một cậu bé 10 tuổi, lo lắng khi nghe thấy cha mẹ nói nhiều về tiền bạc gần đây. Vì gia đình của cậu trước đây đã trải qua cuộc mất nhà cửa và sống trong chiếc xe van chật chội suốt 12 tuần, Jackson luôn lo lắng về tương lai. Trên con đường khó khăn này, Crenshaw – một con mèo hình nhân ngưu màu đen trắng to lớn với mắt sáng quắc và tính cách kỳ quặc – đã xuất hiện. Chú mèo thích ăn kẹo dẻo tím, tắm trong bồn tắm và đặc biệt… ghét chó. Không ai khác ngoài Jackson biết về sự tồn tại của Crenshaw. Liệu một người bạn tưởng tượng như Crenshaw có thể mang lại điều gì đặc biệt cho Jackson và gia đình đang đối mặt với nguy cơ nghèo đói? Cuộc hành trình của họ sẽ như thế nào?', 8, 235, 'active', NULL);
INSERT INTO `ebook` VALUES (236, 'T20.0', 'Gấu Pooh Xinh Xắn', 66000.00, '“Winnie-the-Pooh” hoặc còn gọi là “Gấu Pooh Xinh Xắn” là một tập hợp các câu chuyện nhỏ về tình bạn và thế giới tưởng tượng mà A.A. Milne đã sáng tạo để dành tặng cho con trai yêu dấu, Christopher Robin. Nhân vật chính bước ra từ đám đồ chơi của Robin, bao gồm Gấu Pooh khờ khạo, Lừa xám Eeyore u sầu, Lợn Con nhút nhát, Cú hiểu biết, Thỏ bắng nhắng, kanguru mẹ Kanga, kanguru con Roo…\r\n\r\nTất cả những nhân vật này đã tạo nên một cuộc phiêu lưu kỳ diệu, dí dỏm và đáng yêu, để chinh phục trái tim của nhiều thế hệ trẻ em và người lớn từ khi xuất bản lần đầu vào năm 1926. Minh họa đáng yêu của E.H. Shepard đã giúp Gấu Pooh trở thành một trong những nhân vật phổ biến nhất và có sức hút lan tỏa qua nhiều thế hệ.\r\n\r\nBắt đầu từ chương đầu tiên, bạn sẽ được giới thiệu với Gấu Pooh, vài con ong và những câu chuyện đầy hấp dẫn, mà sẽ đưa bạn vào thế giới tuyệt vời của Gấu Pooh và bạn bè trong khu rừng Trăm Mẫu.', 8, 236, 'active', NULL);
INSERT INTO `ebook` VALUES (237, 'T21.0', 'Bức Chúc Thư Bằng Mật Mã ', 77000.00, '“Bức Chúc Thư Bằng Mật Mã” là một cuốn tiểu thuyết trinh thám hấp dẫn dành cho thiếu nhi trong bộ truyện Les Six Compagnons của tác giả Paul-Jacques Bonzon. Câu chuyện xoay quanh sáu người bạn trẻ đến từ Lyon tìm kiếm kho báu bị chôn vùi dưới lòng hồ trong ngôi làng Mô-bơ-rắc gần hồ nước nhân tạo. Nhờ sự thông minh, lòng dũng cảm và sự giúp đỡ của chú chó Ka-phi, họ đã vượt qua mọi khó khăn để tìm ra kho báu và vạch trần kẻ trộm.\r\n\r\nCuốn sách mang lại cuộc phiêu lưu đầy bí ẩn và những phát hiện không ngờ, lôi cuốn người đọc vào câu chuyện. Tác giả đã xây dựng các nhân vật độc đáo, mỗi người mang tính cách riêng biệt, tạo nên mối quan hệ gắn kết và sự hấp dẫn cho câu chuyện. Bối cảnh vùng nông thôn nước Pháp được miêu tả sinh động, tạo nên không gian mới lạ và thú vị.\r\n\r\nMặc dù có một số tình tiết chưa thực sự thuyết phục và logic, như việc những sự tin tưởng và hợp tác quá nhanh chóng, câu chuyện vẫn mang lại giá trị giải trí và những thông điệp ý nghĩa về tình bạn, lòng dũng cảm và sự kiên trì. “Bức Chúc Thư Bằng Mật Mã” là một cuốn sách đáng đọc, đặc biệt là với độc giả nhỏ tuổi yêu thích thể loại trinh thám và phiêu lưu.', 8, 237, 'active', NULL);
INSERT INTO `ebook` VALUES (238, 'T22.0', 'Những Cuộc Phiêu Lưu Của Tom Sawyer', 88000.00, '“Những Cuộc Phiêu Lưu của Tom Sawyer PDF” là một tiểu thuyết của nhà văn Mark Twain, đem đến câu chuyện về Tom Sawyer, một cậu bé thông minh, nghịch ngợm sống tại một ngôi làng ven sông Mississippi. Tom là một cậu bé tinh quái nhưng dũng cảm, luôn tìm cách trốn tránh những công việc nhàm chán và thích tham gia những cuộc phiêu lưu ngoài trời. Tác phẩm phản ánh một cách hài hước và sâu sắc các nét đặc trưng của tuổi thơ, cùng với sự trưởng thành và khám phá thế giới của một đứa trẻ.\r\n\r\nTom Sawyer và nhóm bạn thân của cậu thường xuyên gặp phải những tình huống dở khóc dở cười và đôi khi nguy hiểm. Từ việc khám phá hang động đến giả mạo cái chết của mình, Tom luôn có những ý tưởng táo bạo và sáng tạo để vượt qua những rắc rối, và đôi khi cậu cũng phải học hỏi từ những sai lầm của mình.\r\n\r\nCuốn sách không chỉ mang lại tiếng cười mà còn phê phán các vấn đề xã hội, đặc biệt là vấn đề giáo dục lạc hậu và lối sống chịu đựng của người dân. “Những Cuộc Phiêu Lưu của Tom Sawyer” không chỉ là một câu chuyện giải trí mà còn là một bức tranh sống động về tuổi thơ và cuộc sống.', 8, 238, 'active', NULL);
INSERT INTO `ebook` VALUES (239, 'T23.0', 'Biển Niên Sử Linh Thú Huyền Thoại: Tập 4 - Mê Cung Ma Thuật', 45000.00, 'Chủ Nhân Của Mê Cung trở lại, lợi hại hơn xưa và tính mạng một LINH THÚ HUYỀN THOẠI đang bị đe dọa!\r\n\r\nHelen và các linh thú chỉ có đúng một ngày đêm để tìm các hiện chứng chữa trị. Chu du khắp Scotland, chiến đấu với đám thằn lằn ma thuật, lũ quái dương gớm guốc, những kẻ khổng lồ ôm mộng báo thù… liệu họ có kịp cứu bạn mình và tiêu diệt vĩnh viễn gã nhân ngưu tàn bạo?', 8, 239, 'active', NULL);
INSERT INTO `ebook` VALUES (240, 'T24.0', 'Biên Niên Sử Linh Thú Huyền Thoại: Tập 3 - Khúc Hải Ca Dữ Dội', 76000.00, 'Một cơn bão dữ dội ập đến đe dọa hủy diệt thế giới của các LINH THÚ HUYỀN THOẠI.\r\n\r\nHelen và những người bạn linh thú cần giúp Rona giành ngôi vị Sứ Giả Đại Dương và tìm cách ngăn cản cuộc giao tranh của các vị thần nắm giữ sức mạnh biển khơi vô hạn. Liệu những người bạn có tìm ra kẻ mang dã tâm phá hoại cuộc thi danh giá của hải tộc? Họ phải đối phó ra sao với cơn bão khủng khiếp nhất mà thế giới ma thuật từng chứng kiến?', 8, 240, 'active', NULL);
INSERT INTO `ebook` VALUES (241, 'T25.0', 'Biên Niên Sử Linh Thú Huyền Thoại: Tập 2 - Lang Âm Và Nhạc Khí', 89000.00, 'Khi Helen cần mẫn luyện tập cho đêm nhạc Hạ chí, các Linh Thú Huyền Thoại rục rịch chuẩn bị cho một trận chiến sống còn.\r\n\r\nHelen đang vô cùng hào hứng trước viễn cảnh được dành cả mùa hè thỏa sức vẫy vùng tại trường năng khiếu thì bất ngờ những người bạn linh thú tiết lộ với cô về mối hiểm nguy mới đến từ rừng thẳm. Chớp mắt, Helen thấy mình bị cuốn vào nhiệm vụ gian nan chống lại Yêu Hậu đa mưu túc kế: Ẩu đả với phúc thần, chiến đấu với sói tộc và nỗ lực đánh lừa yêu tiên.', 8, 241, 'active', NULL);
INSERT INTO `ebook` VALUES (242, 'T26.0', 'Biên Niên Sử Linh Thú Huyền Thoại: Tập 1 - Đụng Độ Thần Thú', 39000.00, 'LINH THÚ HUYỀN THOẠI không chỉ tồn tại trong truyền thuyết. Họ có thật, và họ đang cần sự giúp đỡ.\r\n\r\nChẳng hề muốn nối nghiệp mẹ làm bác sĩ thú y nhưng Helen bất đắc dĩ chữa trị vết thương trên vó ngựa, hay nói đúng hơn, trên vó một sinh vật nửa ngựa, nửa người – một chàng nhân mã. Thế là cô bé học trò sống ở Scotland thế kỉ 21 đột ngột bị cuốn vào cuộc phiêu lưu phi thường ngập tràn bùa phép, yêu thuật, sát cánh cùng rồng, nhân mã, hoa tiên và các linh thú huyền thoại khác…', 8, 242, 'active', NULL);
INSERT INTO `ebook` VALUES (243, 'T27.0', 'Alice Lạc Vào Xứ Sở Diệu Kỳ Và Đi Qua Tấm Gương', 88000.00, 'Cuốn “Alice ở Xứ sở Diệu Kỳ” và phần tiếp theo “Alice ở Xứ sở Trong Gương” là những tác phẩm kỳ lạ của văn học thiếu nhi. Có thể chúng ta đã từng đọc một câu chuyện, một cuốn sách và lạc vào suy nghĩ vì sao những gì ta đang đọc trông như không có nghĩa lý gì. Cốt truyện trong Alice Lạc Vào Xứ Sở Diệu Kỳ Và Đi Qua Tấm Gương không có sự liên kết, nhân vật kỳ quái và không có bài học quan trọng, cũng không mang lại những cảm xúc sâu sắc. Nhưng lại có sức hấp dẫn đặc biệt và ta tự hỏi, liệu dưới những điều vô nghĩa đó có chứa một tầng nghĩa sâu mà ta chưa thể hiểu được.\r\n\r\nĐây chính là tài năng của tác giả Lewis Carroll và là điểm đặc trưng của thể loại “văn học vô nghĩa”, với hai phần trong loạt truyện Alice là ví dụ điển hình. Câu chuyện trong Alice Lạc Vào Xứ Sở Diệu Kỳ Và Đi Qua Tấm Gương bắt đầu khi cô bé Alice bảy tuổi bắt gặp một chú thỏ trắng đang đeo đồng hồ và chạy chỗ này đến chỗ khác. Theo chú thỏ, cô bé lạc vào Xứ sở Diệu Kỳ (Wonderland), một vùng đất đã trở thành nguồn cảm hứng cho nhiều tác phẩm từ hội họa, âm nhạc đến văn chương. Những nhân vật và tình huống kỳ quái mà cô bé gặp gỡ trong Xứ sở Diệu Kỳ đã trở thành những biểu tượng kinh điển và nhiều biểu ngữ, cụm từ phổ biến trong tiếng Anh cũng bắt nguồn từ đây. Khó có thể liệt kê được tất cả những ảnh hưởng sâu rộng mà Alice và những nhân vật như mèo Cheshire, Nữ hoàng của Xứ sở diệu kỳ, người dệt mũ điên… đã góp phần vào văn hóa đại chúng, chỉ từ một tác phẩm văn học thiếu nhi.\r\n\r\nTuy nhiên, tất cả những nhân vật và tình huống trong cuộc phiêu lưu của Alice hoàn toàn không có logic, giống như một giấc mộng khi khi ta đang ngủ, mọi thứ trở nên hợp lý, nhưng khi tỉnh dậy, tất cả đều trở nên hoàn toàn vô lý khi suy nghĩ lại. Cuốn sách đưa ta vào một thế giới kỳ quái, có thể nhìn sâu hơn và phân tích, nó là một tác phẩm vô cùng quái dị.', 8, 243, 'active', NULL);
INSERT INTO `ebook` VALUES (244, 'T28.0', 'Tự Truyện Một Con Heo', 76000.00, '“Tự truyện một con heo” là tác phẩm mới nhất của nhà văn Lý Lan, được xuất bản vào năm 2023. Cuốn sách kể về cuộc phiêu lưu của một chú heo nhỏ được chú chó Nô Nô ngoạm vào cổ tha về nhà bà “Trời đất ơi”, một xóm ngoại ô thành phố. Heo con không biết mình đến từ đâu, không biết ba mẹ mình là ai. Từ đây, cuộc sống hằng ngày diễn ra dưới lời “Tự truyện một con heo” vô cùng thú vị và đem đến cho người đọc một góc nhìn hoàn toàn mới lạ.', 8, 244, 'active', NULL);
INSERT INTO `ebook` VALUES (245, 'T29.0', 'Mắt Sói - Daniel Pennac', 99000.00, '“Mắt Sói” là một tác phẩm văn học thiếu nhi của tác giả Pháp Daniel Pennac, được xuất bản lần đầu tiên vào năm 2002. Cuốn sách kể về câu chuyện tình bạn bất ngờ giữa Phi Châu, một cậu bé 12 tuổi, và Sói Lam, một con sói bị giam cầm trong sở thú.', 8, 245, 'active', NULL);
INSERT INTO `ebook` VALUES (246, 'T30.0', 'Truyện Cổ Dân Gian Nga', 100000.00, 'Truyện Cổ Dân Gian Nga được tuyển chọn từ 600 truyện dân gian và cổ tích Nga danh cho thiếu nhi – một trong những bộ sưu tập văn học dân gian đồ sộ nhất thế giới, của nhà nghiên cứu văn hóa dân gian, nhà phê bình văn học người Nga Alexander Afanasyev được mệnh danh là “người đãi cát tìm vàng”.\r\n\r\nNội dung của cuốn sách “Truyện Cổ Dân Gian Nga” vô cùng phong phú và đa dạng. Tác phẩm bao gồm nhiều thể loại khác nhau như truyện cổ tích thần thoại, truyện cổ tích về loài vật, truyện cổ tích về con người, truyện cười dân gian, v.v. Mỗi câu chuyện đều mang một thông điệp riêng, thể hiện qua những hình ảnh ẩn dụ, những bài học đạo đức và những giá trị văn hóa sâu sắc.\r\n\r\n“Truyện Cổ Dân Gian Nga” không chỉ là một tập hợp những câu chuyện giải trí, mà còn là một nguồn tài liệu quý giá để nghiên cứu văn hóa và lịch sử của người Nga. Tác phẩm giúp chúng ta hiểu rõ hơn về đời sống tinh thần, quan niệm đạo đức và giá trị văn hóa của người dân Nga qua nhiều thế hệ. Bên cạnh giá trị nội dung, “Truyện Cổ Dân Gian Nga” còn được đánh giá cao bởi giá trị nghệ thuật. Tác phẩm được viết với ngôn ngữ giản dị, dễ hiểu, nhưng lại vô cùng sinh động và hấp dẫn. Các câu chuyện được kể một cách logic, mạch lạc, với nhiều tình tiết gay cấn và ly kỳ, khiến người đọc không thể rời mắt khỏi trang sách.\r\n\r\nTóm lại, “Truyện Cổ Dân Gian Nga” là một tác phẩm dành cho mọi lứa tuổi. Tác phẩm là món quà tinh thần quý giá dành cho những ai yêu thích văn học dân gian, đặc biệt là những ai muốn tìm hiểu về văn hóa và lịch sử của người Nga.', 8, 246, 'active', NULL);
INSERT INTO `ebook` VALUES (247, 'T31.0', 'HEIDI - Johanna Spyri', 56000.00, 'Heidi là một câu chuyện cảm động và thú vị về cuộc sống của cô bé Heidi trên ngọn núi Alps. Đây là một trong nhiều truyện viết dành riêng cho thiếu nhi của nữ nhà văn Johanna Spyri (Thụy Sĩ).\r\n\r\nJohanna sinh ra tại Zurich, Thụy Sĩ và mất vào năm 1901 trên chính mảnh đất quê hương của bà. Bà nổi tiếng tại Thụy Sĩ từ những năm 1880 ngay khi xuất bản quyển Heimathlos và tác phẩm này đã được tái bản nhiều lần. Ngay từ khi mới cầm bút, Johanna Spyri đã tuyên bố bà sẽ viết cho các bạn đọc trẻ tuổi và cho những người yêu trẻ. Sự cảm thông sâu sắc của bà với bản năng sống và những khát khao, mong muốn của trái tim trẻ thơ được thể hiện rõ nét qua nhân vật Heidi. Suốt nhiều năm qua, câu chuyện về thời thơ ấu của cô bé Thụy Sĩ này giữa vẻ đẹp hùng vĩ, thơ mộng của vùng núi quê hương đã là cuốn sách yêu thích của các bạn đọc trẻ tại Đức và Mỹ, rất được ưa chuộng và nổi tiếng tại Anh.\r\n\r\nGiống như Hans Andersen – nhà văn chuyên viết truyện cổ tích cho thiếu nhi, nữ nhà văn Johanna Spyri có một khả năng kì diệu tái hiện những câu chuyện giản dị, chan chứa tình người trong thế giới trẻ thơ. Các tác phẩm của Spyri đều thể hiện rõ rệt sự mong muốn gìn giữ cho lứa trẻ khỏi những bất hoà, cạnh tranh, đôi khi là những hành động tốt một cách sai lầm, vô tình cản trở niềm vui, hạnh phúc và sự phát triển hồn nhiên trong cuộc sống và tính cách của các em. Đọc sách của Johanna Spyri, chúng ta cảm thấy như được sống giữa vẻ quyến rũ tuyệt vời của phong cảnh núi non và những nhân vật được bà miêu tả một cách nghệ thuật. Câu chuyện Heidi đề cao vẻ đẹp tâm hồn nhân ái của cô bé Heidi, về cuộc sống chan hoà với thiên nhiên và sự đồng cảm giữa con người với con người.', 8, 247, 'active', NULL);
INSERT INTO `ebook` VALUES (248, 'T32.0', 'Năm Đứa Trẻ Và Nó', 67000.00, '“Năm Đứa Trẻ Và Nó” là một tác phẩm phiêu lưu kỳ ảo kinh điển của văn học thiếu nhi Anh, được viết bởi tác giả E. Nesbit. Nội dung cuốn sách Năm Đứa Trẻ Và Nó kể về câu chuyện của năm anh chị em nhà Bastable – Cyril, Anthea, Robert, Jane và em bé Cừu – trong những cuộc phiêu lưu kỳ thú cùng với một sinh vật bí ẩn tên là Psammead.', 8, 248, 'active', NULL);
INSERT INTO `ebook` VALUES (249, 'T33.0', 'Công Chúa Cá', 77000.00, 'Mặt biển rộng mênh mông, nước biển trong suốt và xanh biếc. Dưới đáy biển trong suốt và xanh-biếc ấy, có cung điện rất đẹp: Cung điện Thủy Tinh.Những bức tường bao xung quanh cung điện đều xây bằng ngọc san-hô màu hồng. Các cửa sổ đều làm bằng thứ hổ-phách trong sáng nhất. Mái nhà lợp bằng những con trai biển; vỏ trai theo chiều nước biển chuyển động, cứ tự nhiên mở ra khép lại, những hạt ngọc- trai bên trong tỏa ra những tia sáng chói nhấp-nhánh, trông thật vui mắt.Trong cung điện Thủy Tinh, có một bà cụ và sáu nàng công chúa đầu người mình cá. Sáu nàng công-chúa đều rất xinh đẹp, rất đáng yêu ; nhất là công chúa út, tươi đẹp hơn cả. Nàng có nước da hồng hào nhỏ mịn như cánh hoa hồng, đôi mắt xanh biếc và trong vắt như nước hồ thu. Nhưng tẩt cả mấy chị em nàng đều không có chân như người ; nửa mình dưới chỉ có đầy những vẫy mọc tua tủa trông giống như đuôi cá, có thể bơi lặn khắp mọi nơi. Mấy chị em đùa giởn suốt ngày, hoàn toàn tự do vui sướng.Bên cạnh cung điện có một vườn hoa rất lớn, trồng đủ các thứ hoa lạ, mềm mại thắm tươi. Mỗi khi nước biển gợn lên những làn sóng nhỏ dập dềnh, thì những cây hoa lại rung rinh uốn-éo như những chiếc nôi mây xinh-xắn. Mỗi nàng công chúa cá chiếm riêng một khu vườn, để tự ý trồng những giống hoa ưa thích. Một nàng trang-trí mảnh vườn riêng thành hình con cá sấu. Nàng khắc của mình thành hình công-chúa-Cá, giống hệt như mình. Riêng nàng công-chúa út trang-trí mãnh vườn của mình thành hình tròn như mặt trời, rồi tự trong những cây hoa đỏ thắm khắp trong đó trông rực rỡ, chói cả mắt giống y như mặt trời vậy.Mấy chị em thường rủ nhau bơi vào trong chiếc, tàu đắm, tìm những đồ dùng của loài người mà các nàng chưa trông thấy bao giờ, đem về bày trong vườn của mình cho tăng thêm vẻ đẹp. Riêng công chúa út chẳng thích thứ gì, nàng chỉ chọn lấy pho tượng một chàng trai anh tuấn bằng đá vân mẫu, đem về bày ở chính giữa mãnh vườn của nàng.Chị em công chúa Cá bồ côi mẹ đã lâu, chỉ còn một bà nội đã già nhân từ âu yếm săn sóc chị em nàng.Bà cụ cũng chẳng khác gì các cháu! Nửa mình trên giống như người, còn nửa mình dưới giống như cá. Bà thường kể cho các cháu nghe những chuyện ở trên thế giới loài người. Một điều mà các nàng công chúa Cá lấy làm lạ nhất, là hoa trên cõi đời thì có thể tỏa ra mùi thơm, mà hoa ở dưới đáy biển thì hữu sắc vô hương. Rừng cây trên cõi đời mầu xanh biếc, trong rừng có những ‘‘Con Cá’’ bơi qua bơi lại, và ca lên những điệu hát rất vui tai. Các thứ ‘‘Cá’’ mà bà cụ nói đó, thật ra là các loài ‘‘Chim’’. Nếu bà cụ không so sánh như thế, thì các công chúa Cá không thể hiểu được, vì chị em nàng chỉ sống ở đáy biển, chưa bao giờ trông thấy các loài chim trên mặt đất.Các nàng công chúa Cá rất thích nghe bà kể truyện cõi đời. Nhiều lần, các công chúa Cá mê quá, cứ kêu rối rít rồi đòi bà cụ đưa lên xem các cảnh trên mặt biển, nhưng bà cụ thường bảo các cháu rằng:- Phải đợi đến khi các cháu đúng mười lăm tuổi, mới được lên chơi trên mặt biển. Lúc đó, các cháu sẽ ngồi trên mỏm đá nhô khỏi mặt nước, ngắm ánh trăng sáng tỏa khắp bầu trời, và nhìn những chiếc thuyền to lớn chạy qua chạy lại bên cạnh các cháu. Rồi các cháu còn có thể trông thấy cả rừng cây um tùm và những cánh đồng rộng bao la nữa.Năm sau, công chúa Cá lớn nhất vừa đúng 15 tuổi, được lên chơi trên mặt biển lần đầu tiên. Trở về thủy cung, nàng kể lại cho các em nghe tất cả những thứ gì mới lạ đã trông thấy ở trên mặt nước ; các công- chúa em nghe kể chuyện, đều vui thích và náo nức ước ao, chỉ mong cho chóng được 15 tuổi.Chị em công chúa Cá đều hơn nhau một tuổi. Vì vậy nàng công chúa ít tuổi nhất phải đợi đúng 5 năm nữa, mới được lên chơi trên mặt biển để xem thế giới loài người.', 8, 249, 'active', NULL);
INSERT INTO `ebook` VALUES (250, 'T34.0', 'Chiếc Rìu - Gary Paulsen ', 55000.00, 'Nhắc đến Gary Paulsen, người ta thường nghĩ ngay tới các câu chuyện phiêu lưu liên quan đến đề tài rừng hoang và tuổi mới lớn. Niềm say mê ấy đã được nhà văn truyền tải thành công trong tác phẩm nổi tiếng “Chiếc rìu” – cuốn sách được đánh giá là một trong những tác phẩm xuất sắc nhất của Paulsen, không phải chỉ bởi những giải thưởng danh giá mà nó đạt được, mà còn bởi những thông điệp sâu xa về những giá trị tinh thần vĩnh cửu ẩn đằng sau một câu chuyện phiêu lưu đầy ly kỳ, hồi hộp. Tác phẩm nổi tiếng này cũng được cho là có tác động sâu sắc tới nhiều thế hệ thiếu nhi Mỹ trong những thập kỷ qua.\r\n“Chiếc rìu” là một tác phẩm thuộc dòng văn học thiếu nhi nhưng không phải vì thế mà đối tượng độc giả của nó bị bó hẹp trong phạm vi tuổi mới lớn. Bằng ngòi bút tinh tế của một nhà văn giàu kinh nghiệm, câu chuyện của Gary Paulsen đã lôi cuốn được những độc giả khó tính nhất vào cuộc phiêu lưu đến với thế giới tự nhiên vốn đã ẩn chứa nhiều bí ẩn, đó là rừng hoang. Có thể sự so sánh chưa thực tương xứng, nhưng ở một khía cạnh nào đó, có thể nói nếu như cách đây hơn 3 thế kỷ, cuộc phiêu lưu một mình trên hoang đảo của Robinson Crusoe đã làm say đắm trái tim của triệu triệu độc giả thì ngày nay, cuộc phiêu lưu của cậu bé Brian cũng phần nào làm người ta nhớ lại Daniel Defoe và tác phẩm xuất sắc nhất trong sự nghiệp sáng tác của ông.', 8, 250, 'active', NULL);
INSERT INTO `ebook` VALUES (251, 'T35.0', 'Chó Xanh Lông Dài', 66000.00, 'Lông Dài từ khi sinh ra đã cùng gia đình sống trong mảnh sân nhỏ nhà lão To Giọng. Chứng kiến các anh em lần lượt bị người lạ đến bắt đi, Lông Dài trở nên cảnh giác để bảo vệ các thành viên trong gia đình. Nhưng rồi cũng đến ngày, mảnh sân chỉ còn lại mình nó, loay hoay cùng câu hỏi: liệu còn có nơi nào tốt hơn “nhà”, nơi nó không phải mất thêm bất kỳ ai thương yêu nữa.Chia ly rồi gặp gỡ, sum vầy lại lìa xa, Lông Dài hết lần này đến lần khác đương đầu với những trải nghiệm bắt buộc của cuộc sống. Song nó không bao giờ bỏ cuộc, vẫn kiên cường bước tiếp để cuối cùng tìm ra câu trả lời rất đỗi giản dị về nơi chốn lý tưởng ấy.Cùng với Cô gà mái xổng chuồng, Chó xanh Lông Dài nằm trong bộ sách “Văn học về loài vật” đã gặt hái nhiều giải thưởng của nhà văn Hàn Quốc viết cho thiếu nhi.***Review sách Chó Xanh Lông Dài – Ý Văn(Có một vài chi tiết spoil vì mình đã chẳng thể ngừng lại khi nói về cuốn sách này. Mình in nghiêng tất cả những dòng có liên quan đến chi tiết ấy!)\r\nMình đã nối tiếp tình yêu với câu chuyện của cô Sun-mi chỉ bằng một cuốn sách nho nhỏ đáng yêu ấy. Đó vẫn là một cuốn sách kể về các loài vật, song lần này mọi thứ đã lại bắt đầu với một cuộc đời khác – “Chó xanh lông dài”.Còn nhớ khoảnh khắc mình bắt gặp cuốn sách này lần đầu tiên, mình đã yêu ngay mà không đợi thời khắc. Cuốn hút từ trang bìa cho đến cả cái tên. Mọi thứ đập vào mắt mình rất đỗi tình cờ mà hữu ý. Mình đã không ngần ngại mà cầm lấy cuốn sách này trên tay, săm soi từng câu từng chữ dòng tóm tắt. Và mình biết, mình lại yêu nữa rồi.”Chó xanh lông dài” đã tiếp tục khẳng định mình khi là một cuốn sách không phải chỉ dành cho thiếu nhi. Những lẽ sống về cuộc đời mà dù sống bao năm mình khó có thể hiểu thấu nay lại được khắc họa rõ ràng qua từng nhân vật của cô Sun-mi. Lão To Giọng, Dong Yi, Lông Dài, Gori, Em Chồng hay mụ mèo ở nhà hàng xóm,… Và mỗi một nhân vật đó lại mang trong mình một câu chuyện riêng. Rằng tại sao họ lại cư xử như thế, rằng họ đã làm thế nào để vượt qua những nỗi đau.Cuộc đời của Lông Dài có thể được xem là những chuỗi ngày với đầy đủ vị mùi của cuộc sống. Từ thuở mới lọt lòng cho đến lúc trở thành một cô chó xinh đẹp rồi trở thành một người mẹ tháo vát. Cô chó nhỏ năm nào đã trải qua nhiều chuyện đời. Với một tuổi thơ luôn tự nghĩ mình bị mẹ hắt hủi. Với một tuổi thơ chẳng còn anh chị em. Lông Dài đã lớn lên một mình như vậy đó với vài ba câu chuyện từ mụ mèo nhà bên.Những tưởng rằng từ đây cuộc đời Lông Dài sẽ tốt hơn nhưng nào ngờ cô lại lần nữa rơi vào tấn bi kịch. Lông Dài đã rơi vào tình yêu với một chú chó dũng mãnh và rồi Gori hoạt bát ra đời. Thằng bé hiếu động lắm, nó chẳng lúc nào chịu ngơi chân. Lông Dài đã yêu thương đứa con ấy của mình vô cùng. Ấy vậy mà đến một ngày, hai mẹ con lại phải chia xa. Khi mọi thứ đã quá khó khăn, Lão To Giọng chẳng còn cách nào khác…Ai bảo vì Lông Dài quá yêu thương Lão To Giọng nên chẳng thể căm giận lão lâu. Ai bảo cuộc đời sinh ra khiến Lông Dài thương người khác còn hơn thương chính mình. Cuộc đời, cho Lông Dài câu trả lời được không?Mình đã lần theo mạch cảm xúc của các nhân vật và rồi mình nhận ra chẳng có thứ gì đẹp như mình tưởng tượng cả. Thế giới ngoài kia vốn đầy rẫy những sự dối lừa. Và chỉ trong vòng tay của “nhà”, mình mới yên tâm ngủ tròn một giấc.Trong suốt những năm tháng còn lại của đời mình, Lông Dài đã không ngừng tìm kiếm lại Gori. Cô lang thang từ khu phố này đến khu phố khác mãi cho tới chiều muộn mới về nhà. Cô thầm mong mỏi Gori sẽ còn sống, cô mong mỏi thật nhiều như cái cách cô mong về mẹ, về các anh chị em của mình.Có lẽ, lời nguyện cầu của Lông Dài cuối cùng đã chạm đến trời cao khi một ngày cô cũng tìm ra Gori – với một dáng vẻ tự tin và mạnh mẽ hệt như bố của nó. Nhìn Gori hạnh phúc, Lông Dài đã quyết sẽ cứ để con sống bình yên và quay về những tháng ngày của mình như trước đó. Và Lông Dài trở về, tiếp tục cuộc chờ đợi trong hạnh phúc khi Lão To Giọng lạch cạch kéo xe về.Lão To Giọng, lão cũng đã lớn tuổi rồi Lông Dài nhỉ? Lão ho nhiều đêm, ho đến bật cả máu mà vẫn cố chấp chẳng chịu đi viện để làm gì. Con cái lão lo cho lão, và lão thì cứ vấn vương suy nghĩ về ngôi nhà và Lông Dài. Nhưng mọi thứ đang dần đi đến hồi kết, tất cả sẽ chóng kết thúc thôi.Mình đã hi vọng nhiều rằng Lão To Giọng sẽ khỏe lại và Lông Dài cũng sẽ chẳng bị tuổi tác ảnh hưởng gì. Mình hi vọng về một thế giới đẹp như thơ mà cô Sun-mi vẽ nên ấy. Nơi có những ước mơ, những cuộc đời…Cuối cùng, cô Sun-mi đã chẳng làm mình thất vọng khi vẽ nên một thế giới nơi những điều tốt đẹp nhất thuộc về. Lông Dài đã tìm lại được những gì mình mong mỏi. Lão To Giọng thì mỉm cười thật tươi.Cuốn sách này đã tạo nên một bất ngờ đầy ý vị cho mình. Mọi chi tiết đều có chút gì đó day dứt, nghẹn ngào. Dù chẳng phải mình là người chịu những tấn bi kịch ấy nhưng mình lại thấy đau hệt như người trong cuộc đấy thôi.”Chó xanh lông dài” đã gợi ra cho mình nhiều cảm xúc như thế. Và chính nó cũng đã lấy đi của mình biết bao giọt nước mắt mình cố kiềm để không rơi. Một góc vườn yên ả năm nào và câu chuyện về những cuộc đời.Tóm lại, cô Sun-mi đã rất thành công trong cuốn sách này. Từ việc khắc họa lại ngôi nhà giản đơn xuyên suốt cả câu chuyện cho đến việc khắc họa tính cách mỗi nhân vật thế nào.”Chó xanh lông dài” không chỉ thành công về mặt nội dung mà còn thành công về cả mặt hình thức. Hình minh họa trong cuốn sách thật sự rất đẹp, rất đáng yêu và cũng buồn không kém.Mình hi vọng bạn sẽ thử đọc cuốn sách này, trong một tâm thế sẵn sàng cho mọi chuyện. Rồi bạn sẽ thấy mọi thứ đều bất ngờ, trong từng câu chữ đến nỗi dù bạn đã sẵn sàng nhưng trái tim bạn vẫn còn đang lay động.***Bạn đã từng nuôi một chú chó trong nhà rồi hay chưa? Và nếu có, liệu bạn có bao giờ hiểu được những tâm tư, suy nghĩ của chúng không? “Chó xanh lông dài” sẽ giúp bạn hiểu được động vật cũng I hệt con người vậy, cũng có những câu chuyện, nỗi niềm riêng mà đôi khi chúng ta cứ nghĩ chúng đơn giản hoặc chẳng biết gì. Một áng truyện ngắn, đầy giản dị nhưng cũng để lại chút xót xa trong lòng mỗi người.Cuốn sách kể về cuộc đời của chú chó Ja Ang của ông lão To Giọng. Chú chó sở hữu một bộ lông dài khá ấn tượng và rất được ông lão yêu quý. Cuộc sống của Lông Dài cũng không thiếu những biến cố như an hem bị bắt đi hoặc bị đem bán, thậm chí có con còn chết tức tưởi. Khi lớn lên, chính những đứa con của Lông Dài cũng lâm vào hoàn cảnh tương tự như vậy.Không những thế, cuộc sống của Lông Dài cũng gắn với những sự kiện, biến cố trong cuộc đời ông lão To Giọng, bà vợ và những đứa con của ông, những người hàng xóm, những vật nuôi khác trong khu vực… Những cuộc chia ly, những cuộc gặp gỡ, những biến cố cứ liên tiếp xảy ra đã để lại nhiều trải nghiệm quý giá cho Lông Dài và kể cả người đọc. Cho đến tận trang cuối cùng của cuốn sách, Lông Dài vẫn kiên cường, vẫn mạnh mẽ và song hành cùng với người chủ cho đến tận cùng thế giới.Đọc hết cuốn sách, người đọc sẽ không khỏi xót xa trước những cuộc chia ly đầy bi lụy tràn khắp mạch truyện. Những mảnh đời nhỏ nhắn cứ liên tục bị tước đi, để lại những nỗi đau dai dẳng trong lòng Lông Dài, một chú chó vô cùng tình cảm, luôn yêu quý tất cả mọi người xung quanh. Chú luôn bị đẩy vào tình trạng cô độc từ khi còn bé cho đến tận ngày từ giã cõi đời.Loài người có thể không hiểu được tiếng của loài chó nhưng Lông Dài lại có thể hiểu và cảm nhận hết những lời nói mà mọi người dành cho mình. Chỉ tiếc rằng, chú chỉ là một chú chó nhỏ nhắn, là một sinh vật khó hiểu trong mắt con người. Từ khi những người anh em bị bắt mất, bị bán đi, cho đến những đứa con cũng lần lượt rời bỏ Lông Dài, chú chó vẫn cố gắng để người chủ hiểu được, thậm chí dỗi hờn và van xin, nhưng chẳng ai hiểu cho điều đó, vì họ còn bận giải quyết những vấn đề của riêng họ. Đau đớn nhưng rất chân thật? Nếu là bạn, bạn có thể nỡ lòng nào chứng kiến từng người thân rời xa ngay trước mắt? Lông Dài đã chứng kiến tất cả ngay từ khi còn bé, còn bạn thì sao? Liệu bạn có hiểu được?Có lẽ vì thế mà đọc đến hết cuốn sách, không biết lũ trẻ sẽ nghĩ như thế nào nhưng tôi lại thấm đượm một nỗi buồn dài dằng dặc. Không chỉ là thương xót mà còn một chút oán trách cho loài người, cho chính mình.May thay, dù người đọc có thể đoán trước được số phận của những vật nuôi nhỏ nhắn này, tác giả cũng vô cùng tinh tế khi không dùng những từ ngữ hay hình ảnh nặng nề cho lắm vì dù sao, cuốn sách cũng dành cho những độc giả nhỏ tuổi. Tất nhiên, cũng có rất nhiều phân đoạn tươi sáng, đáng yêu như những lần các chú chó đùa giỡn với nhau, các đoạn hội thoại giữa Lông Dài với con mèo già hay khi Lông Dài đùa giỡn với đứa cháu của ông To Giọng… khiến câu chuyện bớt đi phần nào u ám, để người đọc tạm quên đi những nỗi đau đã qua, và an lòng một chút cho những nỗi đau về sau.Đối với mình, có lẽ đoạn mà mình thích nhất cũng chính là phần cuối của tác phẩm nơi Lông Dài được đoàn tụ với mọi người, với ông To Giọng, nơi mà sự chia ly không còn, mà chỉ còn lại những tình yêu, những niềm vui khi ở bên cạnh những người mà mình yêu thương. Ngoài ra, một điểm cộng của tác phẩm này là phần hình ảnh minh họa rất đẹp và thu hút, người đọc có thể nhìn vào và cảm nhận được không khí của câu chuyện như thế nào. Hơn nữa, vì là sách dành cho trẻ em nên có ảnh minh họa sẽ tốt hơn, giúp trẻ không cảm thấy nhàm chán khi đọc vì quá nhiều chữ.Không chỉ dành cho những đứa trẻ, người lớn cũng nên đọc qua “Chó xanh lông dài” để cảm nhận những ý nghĩa nhân văn cao đẹp đằng sau đó, một câu chuyện thiếu nhi những đậm triết lý người lớn.', 8, 251, 'active', NULL);
INSERT INTO `ebook` VALUES (253, 'V1.0', 'Tuổi Thơ Dữ Dội', 99000.00, 'Tuổi thơ dữ dội là cuốn sách không những chứa đựng một câu chuyện đầy xúc động mà lối viết của Phùng Quán còn rất hóm hỉnh, thông minh. Mình tin rằng Tuổi thơ dữ dội là chất liệu rất tuyệt vời để giáo dục các em nhỏ thời nay về lòng yêu nước cũng như những phẩm chất đạo đức tốt đẹp, hiếm có.', 9, 253, 'active', NULL);
INSERT INTO `ebook` VALUES (254, 'V2.0', 'Chị Em Khác Mẹ', 58000.00, 'Đề tài “mẹ ghẻ con chồng” không còn là mới lạ\r\n\r\nViệc nuôi một đứa con gái khác của người đàn ông mình yêu thương, phải chịu sự hiện diện vô hình của một người phụ nữ nữa, bóng hình họ xuất hiện bên cạnh đứa con riêng đó dù họ đã không còn trên đời, sự cay đắng ghen tị khi bản thân mình phải chăm sóc thêm cho một người không phải con mình, mà còn là kết quả từ tình yêu của chồng với cô gái khác,…tâm trạng và cảm giác đó không ai trải qua sẽ không thể nào hiểu nổi\r\n\r\nNhưng nói đi cũng nói lại\r\nCon gái riêng của chồng cũng chỉ là một đứa bé, nó không có tội gì cả, nó càng không phải chịu sai lầm gì cho ba mẹ vì họ cũng đến với nhau trong yêu thương chính đáng, chỉ là không may mắn mà người mẹ ra đi quá sớm. Chính vì vậy mới có “mẹ ghẻ” và những đứa “chị em khác mẹ”\r\nVậy thì cô bé nào có làm gì sai? Cớ gì phải gánh chịu sự khinh thường, bất công, sự đánh đập, chửi rủa như vậy???\r\nMột người mẹ hết mực thương yêu chồng con, chỉ có điều không chịu được một chút sạn, không bao dung nổi cô bé ấy\r\nMột cô con gái đáng thương, mẹ ra đi mãi mãi, cha không còn quan tâm yêu thương cô, quá mềm yếu và không bảo vệ được cô\r\nMột đứa em gái khác mẹ lại rất mực yêu quý cô, thương cô bằng cả tấm lòng, như muốn trao trả lại cho xứng đáng với tâm hồn trong sáng, lương thiện của cô\r\n…\r\nLiệu gia đình họ có thể êm ấm mà chung sống hòa bình với nhau?\r\nLiệu  những thành kiến, những gút mắc có được tháo gỡ?\r\nNgười tốt liệu sẽ gặp lành?\r\n“Cô bé lọ lem” có thể thay đổi số mệnh của mình chăng??', 9, 254, 'active', NULL);
INSERT INTO `ebook` VALUES (255, 'V3.0', 'Ranh Giới', 79000.00, 'Đây là một câu truyện nói về cuộc sống, gia đình, tình yêu, tâm sinh lý con người qua những trải nghiệm của một thanh niên thuộc thế hệ nửa đầu 8x. Với những đấu tranh nội tâm gay gắt khi đứng trước ngưỡng cửa của cuộc đời, bước vào mối tình đầu. Giữa tốt đẹp và xấu xa, giữa thiên thần và ác quỷ, tình yêu và bản năng,  đôi khi chỉ cách nhau bằng một “Ranh Giới” thật mong manh… buộc lý trí sẽ phải lựa chọn…\r\n\r\nTruyện lấy bối cảnh đầu tiên vào năm 2001. Mở đầu là những góc nhìn của cậu thanh niên ấy đang ở độ tuổi dậy thì với những tò mò về giới tính…Và nhen nhúm mối tình đầu với cô bạn cùng lớp. Bắt đầu là những đấu tranh giữa tình yêu trong sáng và những suy nghĩ vẩn đục đang tồn tại trong tâm trí, cậu ấy sẽ phải lựa chọn hướng đi đúng đắn cho bản thân để có thể chiển thắng những bản năng đang tồn tại ở chính con người mình với hy vọng tìm thấy một lý tưởng yêu cao đẹp trong cuộc đời. Cậu ấy sẽ phải làm sao?', 9, 255, 'active', NULL);
INSERT INTO `ebook` VALUES (256, 'V4.0', 'Chiếc Ngai Vàng', 88000.00, 'Tiểu thuyết chủ đề lịch sử của nhà văn Lan Khai được xuất bản vào năm 1937. Ông được đánh giá là một cây bút sung mãn, một nhà văn “đường rừng” sáng giá. Dù ở thể loại nào ngòi bút của ông vẫn thuyết phục được cảm tình và lí tính của độc giả.', 9, 256, 'active', NULL);
INSERT INTO `ebook` VALUES (257, 'V5.0', 'Dứt Tình', 45000.00, 'Vũ Trọng Phụng là một nhà văn, nhà báo, một cây bút phóng sự với nhiều bài tiêu biểu. Năm 1930, ông có bài đăng trên Ngọ báo, nhưng lúc này tên tuổi ông chưa thực sự được chú ý trong giới văn học Việt Nam. Mãi đến 1931, vở kịnh Không một tiếng vang ra đời, thì mới bắt đầu gây được sự chú ý của bạn đọc. Năm 1934, Vũ Trọng Phụng có tiểu thuyết đầu tay “Dứt tình” (còn có tên khác là Bởi không duyên kiếp) đăng trên tờ Hải Phòng tuần báo. Với tiểu thuyết này, Vũ Trọng Phụng được khen là “ngòi bút tả chân thực đã khéo léo”.“Dứt tình” là cuốn tiểu thuyết mang tư tưởng định mệnh siêu hình.', 9, 257, 'active', NULL);
INSERT INTO `ebook` VALUES (258, 'V6.0', 'Ván Bài Lật Ngửa', 45000.00, 'Trong ngày toàn thắng vĩ đại 30 tháng 4 nǎm 1975 kết thúc quá trình phấn đấu lâu dài của dân tộc có phần hy sinh đóng góp thầm lặng của những chiến sĩ tình báo. Mặt trận mà họ chiến đấu hầu hết không nổ súng, lại là nơi thử thách nghiêm khắc nhất bộ thần kinh cùng các đòi hỏi cao lòng dũng cảm, trí thông minh, sự nhạy bén.\r\n\r\nVán bài lật ngửa phản ánh một trong vô số khía cạnh phong phú của cuộc đấu tranh giữa một thời điểm hết sức tế nhị của đất nước: sau hiệp định Genève. Câu chuyện có diễn biến nhanh, cách viết thông minh, lôi cuốn, lời thoại sắc sảo, Ván bài lật ngửa vừa tái hiện một cách sống động lịch sử, đồng thời mang lịch sử đến với người đọc một cách tinh tế, chân thực, gần gũi.\r\n\r\nVới Ván bài lật ngửa, nhà văn Nguyễn Trương Thiên Lý không chỉ mô tả lịch sử “chính thống” ở cái bề nổi của nó, mà đi sâu khám phá cuộc sống muôn vẻ, sinh động diễn tiến bên dưới, cho chúng ta một cái nhìn bao quát mà chi tiết về cuộc đấu tranh ngầm nhưng không kém phần gay go, quyết liệt, góp phần làm nên thắng lợi chung.', 9, 258, 'active', NULL);
INSERT INTO `ebook` VALUES (259, 'V7.0', 'Đốc Rác Cũ - Trọn Bộ', 97000.00, 'Đống Rác Cũ phản ánh cuộc sống xã hội cũ bằng bút pháp hiện thực phê phán. Bạn đọc gặp ở Đống Rác Cũ những trang miêu tả xã hội, miêu tả con người từ thời kỳ trước những năm thứ 12 triều vua Bảo Đại, bằng bút pháp sắc sảo, với con mắt tinh đời, tính nhân đạo của nhà văn, cùng nụ cười của ông trước các thói dởm dở, những đạo đức giả của một bọn người mà thực chất bên trong lại chứa đựng một kho rác rưởi tởm lợm.\r\n\r\nQua các trang sách, tác giả phanh phui mưu đồ lừa đảo xảo quyệt của những kẻ bất lương cố ngoi lên chiếm danh vị xã hội, những liên kết ma quái, những cuộc đọ tài của những kẻ chuyên nghề bịp bợm. Người đọc phải thổn thức và phẫn nộ khi chứng kiến biết bao số phận lành hiền mộc mạc như Múi, như Xi, như mẹ Mão… những con người quá tốt bụng, cả tin đến ngây thơ rồi bị rơi vào cạm bẫy để trở thành những vật hy sinh cho phường lừa đảo. Đống Rác Cũ mang tính tố cáo mạnh mẽ, lên án bọn sâu mọt hợm hĩnh đạo đức giả…', 9, 259, 'active', NULL);
INSERT INTO `ebook` VALUES (260, 'V8.0', 'Quân Khu Nam Đồng', 78000.00, 'Khu tập thể Nam Đồng là khu gia binh lớn nhất thủ đô Hà Nội, được hình thành cách đây hơn 50 năm. Là nơi ở của hơn 500 gia đình cán bộ quân đội trung, cao cấp, hơn 70 vị tướng đã từng sinh sống và trưởng thành từ Khu tập thể Nam Đồng, nhiều gia đình có cả hai thế hệ “tướng cha” và “tướng con”. Đây là một khu gia binh điển hình, một đại gia đình quân nhân thu nhỏ thời chiến và hậu chiến.\r\n\r\nQuân khu Nam Đồng là tiểu thuyết được viết bằng bút pháp hiện thực bởi một cây bút lần đầu tiên xuất hiện trên văn đàn, và cũng là một người con của khu tập thể Nam Đồng. Tác giả vừa là nhân chứng, vừa là nhân vật trực tiếp tham gia vào các sự kiện; lại cũng là người quan sát tỉnh táo có độ lùi thời gian để rút ra những chiêm nghiệm và thông điệp sâu sắc về một giai đoạn lịch sử đặc biệt của đất nước chúng ta.\r\n\r\nMột cuốn sách lôi cuốn, ly kỳ, hấp dẫn, khiến ta khó rời mắt trước khi lật đến trang cuối cùng…Một cuốn sách sẽ mang tới rất nhiều tiếng cười và lấy đi của chúng ta rất nhiều nước mắt…', 9, 260, 'active', NULL);
INSERT INTO `ebook` VALUES (261, 'V9.0', 'Sau Cành Violet', 56000.00, 'Sau Cành Violet là cuốn truyện tình báo của Ngô Tất Thắng viết về những chiến tích hào hùng của các chiến sĩ tình báo Việt Nam trong cuộc kháng chiến chống Mỹ cứu nước, giải phóng miền Nam. \r\n\r\nCuốn sách không tái hiện lại cuộc chiến đấu giữa ta và địch trên chiến trường đầy bom đạn mà đưa người đọc đến với một trận tuyến thầm lặng. Đó là hình ảnh của những chiến sĩ tình báo (như Hồng Giang và Hoài Phương – hai nhân vật trong truyện). Các chiến sĩ của ta ngày đêm vượt khó khăn, hiểm nguy tiến hành các hoạt động phản gián ngay trong guồng máy chính quyền ngụy và tổ chức gián điệp CIA của Mỹ tại Sài Gòn. \r\n\r\nNhững chiến công của họ chưa một lần được nêu danh trên đài báo nhưng đã góp phần không nhỏ vào thắng lợi chung của toàn dân tộc. Qua đó, người đọc thấy rõ sự mưu trí tài tình, lòng dũng cảm và trên hết là một đức hy sinh, hết lòng vì dân, vì nước của các chiến sĩ tình báo Việt Nam.', 9, 261, 'active', NULL);
INSERT INTO `ebook` VALUES (262, 'V10.0', 'Cuộc Đời Ngoài Cửa', 65000.00, 'Trong vai một người viết tiểu thuyết, Nguyễn Danh Lam hẳn là mẫu nhà văn không thích, thậm chí rất dị ứng, việc cưng nựng chiều chuộng các nhân vật của mình. Từ những “Bến vô thường”, “Giữa vòng vây trần gian”, đến “Giữa dòng chảy lạc”, đã là thế. Và rồi đến cuốn tiểu thuyết mới nhất này, vẫn là thế. Nguyễn Danh Lam không thèm hạ cố ban cho nhân vật một danh tính rõ ràng. Cũng rất hiếm khi nhà văn gắn cho họ những nét phẩm chất tính cách hoặc những năng lực cá nhân trên mức trung bình. Đã vậy, anh lại hay đẩy các nhân vật vào những cảnh huống trớ trêu, những trạng thái sinh tồn nếu không bi đát thì cũng dở khóc dở cười.\r\n\r\nĐiều, vừa quan trọng lại vừa oái oăm, là ở chỗ: trong những cảnh huống những trạng thái ấy, các nhân vật của Nguyễn Danh Lam luôn có một sự tự nhận thức, thường trực và đầy ám ảnh, về cái bất túc và bất lực của mình… Ở cuốn tiểu thuyết mới nhất này,Nguyễn Danh Lam cho nhân vật chính “lên đường”, làm một chuyến du lịch bụi cùng với cô con gái cả ngày chỉ biết dán mắt vào chơi game trên điện thoại di động và luôn miệng kêu than. Sau lưng họ, là một gia đình rạn nứt. Trước mặt họ, là những khúc rẽ bất ngờ, những đứt gãy nhân sinh còn tồi tệ hơn gấp bội. Nguyễn Danh Lam đã kể những chuyện ấy, một cách bình thản và đầy tiết chế.', 9, 262, 'active', NULL);
INSERT INTO `ebook` VALUES (263, 'V11.0', 'Những Ngã Tư Và Những Cái Cột Đèn', 75000.00, 'Một cuốn tiểu thuyết sau gần nửa thế kỷ mới được xuất bản, nhưng đọc rất mới, đọc rồi đọc lại vẫn mới, vẫn bất ngờ trước từng trang, vẫn không dễ nắm bắt nội dung, đó là Những ngã tư và những cột đèn của nhà văn Trần Dần.\r\n\r\nChuyện rằng: vào giữa những năm 1960, nhà văn Trần Dần, khi đang trong hoàn cảnh hết sức ngặt nghèo của bản thân đã được một vài cán bộ công an hảo tâm tìm cách cho đi thâm nhập một số trại giam do Bộ Công an quản lý đang giam giữ những ngụy quân thời Pháp sau ngày tiếp quản Thủ đô. Kiểu đi như thế gọi là “đi thực tế” để khi về viết văn trên những cứ liệu của thực tế chuyến đi đó. Công thức ở đây là: cơ sở cung cấp tài liệu về một vấn đề cụ thể, nhà văn đi cho thấy, tiếp xúc cho biết, và cái viết ra thường chỉ là một báo cáo, một sơ đồ, dù có được vẽ vời thêm cho có vị văn chương.\r\n\r\nVậy, với Trần Dần, bài toán đặt ra là: viết về hoàn cảnh của những người ngụy quân Pháp ở Hà Nội khi chiến tranh kết thúc, phần thắng thuộc về đội quân cách mạng, với định hướng viết đã rõ ràng là họ phải quy phục chế độ mới.\r\n\r\nĐề bài này không khó đối với ngòi bút Trần Dần. Nếu an phận, viết theo lối trả bài (trả cả ơn nghĩa nữa, nếu có), ông dễ phóng bút viết được nhanh, được trơn tru, nộp quyển, và quên đi nhanh chóng cái viết ra đó. Nhưng ông đã không làm thế, vì nhân cách là văn cách của ông không cho phép làm thế. Trần Dần, nhà văn luôn táo bạo quyết liệt trong từng câu chữ, hiểu theo nghĩa đen và nghĩa bóng, trong từng cái viết. Viết, với ông, bao giờ cũng là phải mới, phải khác, phải cách tân. Vì vậy, kết quả chuyến thực tế ấy, dưới tay ông đã thành tiểu thuyết Những ngã tư và những cột đèn (NNTVNCĐ). Trần Dần đã giải được bài toán văn chương một cách xuất sắc.', 9, 263, 'active', NULL);
INSERT INTO `ebook` VALUES (264, 'V12.0', 'Ngày Vui', 71000.00, 'Ðặng Trần Huân sinh ngày 07 tháng 6 năm 1929 tại Bắc Ninh, cựu thiếu tá QLVNCH, làm việc tại Cục Tâm Lý Chiến, ngành thông tin báo chí. Khởi viết năm 1953. Ông là tác giả tập truyền cười nổi tiếng ” Chuyện Cấm Đàn Bà I & II (1969, 1970)” , rồi Chuyện Vợ Chồng (1970). \r\n\r\nSau năm 1975, ông đi học tập cải tạo, và định cư tại Hoa Kỳ từ năm 1992. Mặc dù qua Mỹ muộn màng, sức khỏe sa sút, tuổi tác lại cao nhưng nhà văn Đặng Trần Huân đã cầm bút trở lại, và viết một cách hăng say, qua nhiều thể tài khác nhau. Chỉ trong vòng 5 năm mà ông đã xuất bản 3 tác phẩm, gồm có: Hành Trình Một Hát Ô (bút ký, 1995), Những Người Thích Dấu Huyền (1998), và Chữ Nghĩa Bề Bề (chuyện văn nghệ, 2000). \r\n\r\nMọi người biết đến nhà văn Đặng Trần Huân qua chuyện cười nổi tiếng của ông, nhưng ít ai biết ông còn tác giả tập truyện ngắn Ngày Vui (1962), truyện dịch Hải Đảo Thần Tiên (1963) và bút ký: Thành Phố Buồn Thiu (1970). ', 9, 264, 'active', NULL);
INSERT INTO `ebook` VALUES (265, 'V13.0', 'Tuyển Tập Truyện Ngắn Vũ Trọng Phụng', 52000.00, 'Nhắc đến Vũ Trọng Phụng người ta nghĩ ngay tới một nhà văn tài hoa nhưng bạc mệnh. Có năng khiếu nghệ thuật từ nhỏ, ông sáng tác từ rất sớm và thử nghiệm mình trên nhiều thể loại: viết báo, viết kịch, sáng tác truyện ngắn, truyện vừa, tiểu thuyết, phê bình văn học… Nhưng có thể nói, tiểu thuyết và phóng sự là hai thể loại thành công nhất của nhà văn tài hoa này. Vũ Trọng Phụng được báo giới thời bấy giờ mệnh danh là “ông vua phóng sự đất Bắc”, là “nhà tiểu thuyết trác việt”.\r\n\r\nVới giọng văn sắc sảo, mang đậm chất châm biếm, trào phúng và nội dung tư tưởng sâu sắc, các tác phẩm của Vũ Trọng Phụng đều hướng tới chủ đề hiện thực, tố cáo và vạch trần xã hội Việt Nam trước cách mạng tháng 8 – một xã hội bê bối với những tấn trò đời bi kịch. Đọc những trang văn của ông, người ta không khỏi ngậm ngùi, chua chát. Ra đi vì bệnh tật khi mới 27 tuổi đời, khi tài năng đang độ phát triển rực rỡ, Vũ Trọng Phụng để lại trong làng văn và trong lòng độc giả một chỗ trống không dễ gì khỏa lấp.', 9, 265, 'active', NULL);
INSERT INTO `ebook` VALUES (266, 'V14.0', 'Con Hoang', 67000.00, 'Lại đêm nữa, bà đơn phương vùi khát thèm bằng trắng đêm giã gạo. Những đêm trăng quê yên tĩnh trải rộng miên man dài. Những đêm giã gạo toát mồ hôi, gió vừa đủ lạnh thấm lỗ chân lông gời gợi. Những đêm không chịu nổi, bà ôm chặt cái thân cối giã gạo, òa khóc cho hả lòng hả dạ, cho bớt tủi nhục cô đơn. Trong đêm, cái khúc gỗ nhãn làm thân cối giã gạo được bào nhẵn vuông tròn mịn màng hiển hiện như một thân thể đàn ông. Tại sao không cho bà được yêu thương, được ôm ấp, được giận hờn…', 9, 266, 'active', NULL);
INSERT INTO `ebook` VALUES (267, 'V15.0', 'Đoạn Tình', 90000.00, '“Ban đêm trời mát, nhưng mà cô Vân đọc thơ rồi thì cô toát mồ hôi.\r\n\r\nGia đình của anh Thuần đã tan nát rồi! Anh Thuần đi đâu? Chị Hòa liệu thế nào? Hai đứa nhỏ ra làm sao? Ấy là mấy câu cô Vân tự hỏi thầm trong trí, hỏi mà không đáp ứng, chỉ nhìn ngọn đèn, nước mắt chảy ròng ròng.\r\n\r\nTheo lời nói trong thơ, thì tại sao vợ chồng không đồng tâm hiệp ý, nên gia đình mới tan rã. Nhưng mà vợ chồng đã ở với nhau năm, sáu năm, đã có hai mặt con, vì cớ gì anh Thuần đành đoạn tình vợ chồng, đành dứt nghĩa cha con như vậy? Cô Vân suy nghĩ rồi muốn biết cái duyên cớ ấy nên cô lau nước mắt và giwor tập “Đoạn tình nhật ký” ra mà đọc.”', 9, 267, 'active', NULL);
INSERT INTO `ebook` VALUES (268, 'V16.0', 'Một Đứa Con Đã Khôn Ngoan', 60000.00, 'Trong truyện Một đứa con đã khôn ngoan, nhà văn giáo dục trẻ em đức tính yêu lấy tiếng Việt. “Ta có tiếng nói riêng. Bổn phận ta là phải giữ lấy tiếng ta, vì tiếng ta tức là tinh thần nước ta”. Cậu bé Chỉ trong truyện này chỉ mê tiếng Pháp và cho rằng tiếng Việt không đủ để diễn tả hết mọi suy nghĩ và sự vật. Ngay cả lúc viết thư cho bạn, cậu cũng phải dùng thêm tiếng Pháp. Cậu (bố) của cậu bé Chỉ không đồng ý và phân tích cho cậu rằng: “Con thấy thiếu chứ tiếng ta không thiếu. Nếu thiếu chăng, thì nó thiếu ở ý mới, vật mới xưa kia không có. Còn những ý cũ vật cũ thì tiếng nước ta vẫn đủ như thường.\r\n\r\nXem ngay như về gia đình, ta có biết bao nhiêu tiếng: kỵ, cụ, ông, bà, cha, mẹ, con, cháu, chắt, chút, bác, cậu, mợ, dì, cô, thím, âu yếm, thân, hiếu, đễ, từ và biết bao nhiêu tiếng nữa. Lại nói như cách mang đồ đạc, ta có đội, gánh, xách, vác, cầm, khênh, ôm, cõng, bẽ, tải, cắp, khuân, bế, mỗi tiếng một nghĩa riêng” và “Cậu dám đánh cược với ông cử, ông nghè Tây dùng tiếng Pháp mà dịch nổi tiếng “lôi thôi” của ta đấy”.', 9, 268, 'active', NULL);
INSERT INTO `ebook` VALUES (269, 'V17.0', 'Những Mảnh Đời Đen Trắng', 45000.00, 'Những mảnh đời đen trắng là một tác phẩm mạnh và dứt khoát. Là cuộc xung đột giữa hai tầng lớp xã hội, hai quan điểm sống khác nhau. Giữa hai thế hệ già và trẻ, giữa lớp người có quá khứ oai hùng và lớp ngưới không được quyền có quá khứ. Giữa lớp bần cố nông làm chủ tập thể, làm chủ tình thế và lớp trí thức tiểu tư sản “đầu thai nhầm thế kỷ, bị quê hương ruồng bỏ giống nòi khinh”. Cả hai giai tầng đều đáng thương mà không đáng trách. Một bên có khả năng nhận thức mà không được sử dụng. Một bên không có khả năng mà phải gánh vác những công việc quá sức mình.\r\n\r\n“Họa sĩ Tư và Thùy Linh đứng cúi đầu trước nấm mồ trắng lạnh, hương trầm đang nghi ngút. Dưới nấm mồ kia là đại úy Thìn, con người vừa đáng trọng vừa đáng khinh, vừa đáng thương vừa đáng ghét…\r\n\r\n… Thùy Linh rơm rớm nước mắt. Cô quỳ xuống vái. Nắng chiều đã nhạt, từng đụn cát trắng sẫm màu hoàng hôn. Họ ra về, cả hai cúi đầu bước, thổn thức về một thời họ đã sống với con người ấy dưới nấm mồ kia…”', 9, 269, 'active', NULL);
INSERT INTO `ebook` VALUES (270, 'V18.0', 'Ăn Mày Dĩ Vãng', 34000.00, 'Hòa bình, những người lính kiêu dũng trong chiến tranh phần lớn đã “về vườn, ăn theo, núp váy vợ. Đứa thì say xỉn tối ngày nằm trên võng nắng; đứa thì lụi hụi trồng tỉa ngoài bưng, mở mồm là càu cạu; đứa thì thở dài phìn phịt giữa một bên là bầy con nhem nhuốc, một bên là thạp gạo chỉ còn cám mùn đọng quẩn dưới đáy; thằng kia sống trụi thùi lụi một mình, hỏi nhà cửa vợ con đâu chỉ giơ cái chai đế lên cười xệch xẹo”. Nhưng cũng có những người như Quân trước là cậu bé giao liên, nay là phó chủ tịch huyện, biết làm giàu cho quê hương và cho bản thân; hoặc như Tuấn, như Tám Tính đã hòa nhập tự nhiên với cuộc sống đời thường và không những thế còn vươn lên làm chủ cuộc sống mới. Trên hết vẫn là nhân vật Hai Hùng, “không vợ không con, không cắc bạc dính túi nhưng có mảnh quá khứ đập phập phồng trong lồng ngực”, với lý tưởng “Cuộc đời một thằng lính còn có gì khác hơn là khôn nguôi hướng về dĩ vãng và cầu mong cho dĩ vãng đó luôn trong lành chân thật”, một cá tính ít nhiều lạc điệu trong thời hiện tại, nơi “người ta đã hầu hết đều bảo nhau quay lưng lại với quá khứ”.\r\n\r\nMột ngày như mọi ngày trong thời hậu chiến tại một nhà hàng sang trọng, Hai Hùng tình cờ gặp một người đàn bà với tất cả phong thái, dáng nét của người yêu cũ Ba Sương từ thời chiến tranh của anh. Người con gái bị cho là đã chết mà chính Hai Hùng là người tiến hành cướp xác và chôn cất, ngờ đâu giờ vẫn còn hiện hữu giữa nhân gian với một cái tên khác, Tư Lan, và đang rất thành đạt trên cương vị một nữ giám đốc Sở lâm nghiệp đầy quyền uy, làm ăn nức tiếng lục tỉnh miền Tây. Màn sương mờ phủ của thời gian, những hoài nghi hư thực từ lý trí của nhân vật chính không ngăn nổi linh cảm, rung động và tiếng gọi tự con tim khẳng định chắc chắn người đàn bà thành đạt kia chính là cố nhân của anh. Tất cả đã thôi thúc Hai Hùng tìm về quá khứ, sống lại một thời hoa lửa hào hùng và bi tráng ở cương vị một chiến sĩ, người đội trưởng đặc nhiệm, với những kỷ niệm tình yêu ngọt ngào bên cô y tá, xã đội trưởng Ba Sương. Đây là một hành trình lần ngược ký ức với những day dứt, ân hận của nhân vật tôi vì đã chạy vào hầm trước và không chạy ra cứu người mình yêu khi khoảng cách chỉ là ba chục mét để có thể sống chết bên nhau, để rồi thất lạc nhau từ đó và cùng cuộc tráo xác với Hai Hợi đã khiến Hai Hùng đinh ninh sự thật là Ba Sương đã hy sinh.', 9, 270, 'active', NULL);
INSERT INTO `ebook` VALUES (271, 'V19.0', 'Đời Callboy', 87000.00, 'Đời Callboy có những đoạn trần trụi khiến người ta hoài nghi về độ thật của nó và tự hỏi: “Xã hội thực sự là thế ư?”, nhưng nếu một lần tận mắt chứng kiến những gì đang xảy ra, mọi người sẽ hiểu rằng “Đời Callboy” của Nguyễn Ngọc Thạch đã đi đến được những góc khuất nhất của “nghề nghiệp” bị người đời coi khinh này.\r\n\r\nCallboy, những người thanh niên dùng thân xác đổi lấy đồng tiền, vẫn tồn tại trong thế giới bóng tối…\r\n\r\nĐồng tính – cũng không còn là một chủ đề mới của văn đàn, nhưng đa phần chỉ là những tác phẩm được chấp bút ghi lại theo lời kể của một nhân vật có thật. Tuy nhiên nếu một “người trong cuộc” tự viết về chính mình thì mọi việc sẽ khác hẳn.\r\n\r\nHãy đọc “Đời Callboy” của Nguyễn Ngọc Thạch để hiểu hơn về thế giới những người đàn ông yêu nhau nhưng bị chi phối mãnh liệt bởi đồng tiền và tình dục. Và để hiểu hơn rằng, giới tính không phải là thứ quyết định nhân cách sống của bạn.\r\n\r\n “Đôi khi tôi nghĩ, mình có duyên với “đĩ”.', 9, 271, 'active', NULL);
INSERT INTO `ebook` VALUES (272, 'V20.0', 'Đêm Hội Long Trì', 100000.00, 'Đêm hội Long Trì là một cuốn tiểu thuyết lịch sử của nhà văn Nguyễn Huy Tưởng.\r\n\r\nTác phẩm chọn một thời đoạn lịch sử điển hình cho sự suy thoái và phân rã của xã hội, nên có nhiều đất đai cho việc khai thác các mâu thuẫn và xung đột; cho sự mở rộng và đào sâu vào thế giới nhân vật; cho sự triển khai các mạch truyện và chủ đề; và cho sự gửi gắm nhiều ý tưởng rút từ lịch sử, trong gắn nối và soi sáng các vấn đề của thời hiện tại.', 9, 272, 'active', NULL);
INSERT INTO `ebook` VALUES (273, 'V21.0', 'Cạm Bẫy Người ', 96000.00, 'Cạm bẫy người (1933) viết về nạn cờ bạc bịp ở Hà Nội.\r\n\r\nĐể thấy cái tệ nạn cờ bạc rộng lớn và tai hại đến đâu, Vũ Trọng Phụng đã điều tra cái làng bịp, vạch ra tổ chức của nó, phác họa chân dung, mô tả chân tướng của dân làng bịp, tường thuật cách hành nghề của họ rõ ràng, sinh động…\r\n\r\nViết Cạm bẫy người là tố cáo một tệ nạn xã hội và nêu lên những bi kịch do những tay săn mòng gây ra cho những gia đình của bọn tín đồ “tôn giáo đỏ đen”.', 9, 273, 'active', NULL);
INSERT INTO `ebook` VALUES (274, 'V22.0', 'Bỉ Vỏ ', 98000.00, 'Bỉ vỏ là tác phẩm đầu tay của Nguyên Hồng được Tự Lực Văn Đoàn tặng giải nhì năm 1937.\r\n\r\nBính là cô gái nghèo làng Sòi. Vì nhẹ dạ, yêu một gã Tham đạc điền và bị hắn bỏ rơi giữa lúc bụng mang dạ chửa. Cô bị cha mẹ hắt hủi, đay nghiến và đứa bé sinh ra phải đem bán đi vì sợ làng bắt vạ. Đau đớn, Bính trốn nhà đi Hải Phòng mong tìm được người tình. Sau mấy ngày đêm lang thang đói khát, có lần suýt bị làm nhục ở một vườn hoa, Bính gặp một gã trẻ tuổi nhà giàu. Gã lừa cô vào nhà hãm hiếp và đổ bệnh lậu cho cô. Vợ gã bắt gặp, đánh đập Bính tàn nhẫn và lôi cô ra Sở cẩm, vu là gái đĩ. Thế là Bính bị đưa vào nhà “lục xì”, sau đó rơi vào nhà chứa của mụ Tài sế cấu. Sống ê chề cực nhục ở nơi bẩn thỉu hôi hám, Bính ốm nặng.\r\n\r\nĐau khổ, tuyệt vọng, Bính toan tự tử nhưng được Năm Sài Gòn, trùm lưu manh ở Hải Phòng, chuộc ra khỏi nhà chứa, đem về chăm sóc hết lòng. Nhưng rồi Năm bị bắt. Tuy túng bấn nhưng Bính nhất định không nhận tiền “bồi” (tiền bọn ăn cắp trích nộp “đàn anh”) mà sống bằng buôn bán lương thiện, hy vọng khi Năm trở về sẽ khuyên y từ bỏ cái nghề bất lương và nguy hiểm. Năm được tha nhưng dứt khoát không nghe lời khuyên của Bính. Thế là, bất đắc dĩ, Bính cũng bị lôi kéo vào con đường lưu manh, trở thành một “bỉ vỏ” – người đàn bà ăn cắp. Do một sự hiểu lầm và ghen tuông, Năm Sài Gòn đuổi Bính đi. Bính về Nam Định, gồng thuê gánh mướn kiếm ăn. Được tin bố mẹ ở gặp tai họa có thể bị tù, Bính không còn cách nào khác, đã phải nhận lời lấy một viên mật thám để có tiền gửi về cứu bố mẹ.', 9, 274, 'active', NULL);
INSERT INTO `ebook` VALUES (275, 'V23.0', 'Làm Đĩ', 56000.00, 'Vũ Trong Phụng viết Làm đĩ vào năm 1936, một thời đại thực sự hỗn loạn như đã hiện lên qua nhiều trang viết của ông và các nhà văn cùng thời. Xã hội thành thị Việt Nam thời ấy đang “Âu hóa” một cách nửa mùa – cái cũ chưa qua, cái mới chưa tới, đầy rẫy sự nhốn nháo, lừa lọc, sa đọa và đau khổ.\r\n\r\nLàm đĩ được viết dưới dạng tự truyện của nhân vật chính tên Huyền. Sinh ra trong một gia đình có cha làm việc cho Tây nhưng lại cực kỳ hủ bại, từ nhỏ Huyền đã luôn bị người lớn lảng tránh và nạt nộ khi cô bé thắc mắc về những vấn đề giới tính.\r\n\r\nThứ cô tiếp thu được chỉ là lời nói bậy bạ, thô tục của kẻ ăn người ở trong nhà và những bài “tự học” của đám trẻ thơ. Sự tò mò ấy làm bùng lên nỗi khát khao ở người thiếu nữ bước vào tuổi dậy thì, để rồi một ngày cô ngã vào vòng tay Lưu – một người anh họ xa đang trọ học tại nhà – trong cái đêm mất ngủ vì âm thanh “sự thị uy của ái tình” giữa cha và vợ bé chỉ cách giường cô một bức vách. Mối tình vụng dại kết thúc bi thảm hệt như những bộ phim lãng mạn thời bấy giờ.\r\nLưu tự tử chết, Huyền bị ép gả cho Kim. Kim mắc bệnh giang mai do thói ăn chơi bừa bãi của giới thượng lưu nên chỉ có thể quấy rấy vợ bằng “cách nửa đời nửa đoạn.” Vì tiền, Kim đem vợ ra làm mồi nhử Tân, một “đại gia” đào hoa, giàu có.', 9, 275, 'active', NULL);
INSERT INTO `ebook` VALUES (276, 'V24.0', 'Cuộc Đời Dài Lắm', 45000.00, 'Những cuốn tiểu thuyết của nhà văn Chu Lai luôn đem lại cho người đọc những cảm xúc rất thật, đi đến tận cùng của những suy nghĩ, quan điểm cũng như cảm xúc. Lúc cười thì cười rất tự nhiên, lúc buồn thì cảm giác như cả bầu trời chỉ còn lại một màu của khói thuốc trong đêm gác của anh lính tân binh… \r\n\r\nVới giọng văn đậm chất lính, mộc mạc, chân thành, hóm hỉnh và có lúc ầm ầm như cơn lốc, có lúc ưu tư như mặt hồ mùa thu đầy chất thơ. \r\n\r\nĐặc biệt tình yêu trong tiểu thuyết Chu Lai rất khắc khoải, rất sâu nặng mà cũng rất…bụi. Bụi theo kiểu lính. \r\n\r\nCuộc đời dài lắm là một tác phẩm như vậy. Hà Vũ Nguyên là một người lính, một người lính đẹp với đầy đủ nghĩa đen và nghĩa bóng của từ đó. Một người đẹp thì tình yêu luôn trắc trở-cái quy luật ấy hình như cũng chẳng nể gì người lính. Nguyên về nhận chức giám đốc của một công ty đang tụt dốc. Cá tính, nhân cách, tài năng của anh đã làm nhiều người cảm phục nhưng cũng không ít kẻ ganh ghét và rắp tâm hãm hại…', 9, 276, 'active', NULL);
INSERT INTO `ebook` VALUES (277, 'V25.0', 'Nhiều Cách Sống', 78000.00, 'Nhiều cách sống của nhà văn 8X Nguyễn Quỳnh Trang, cũng như tác phẩm của những nhà văn trẻ khác, đề cập đến sự hoang mang của giới trẻ – “căn bệnh” phổ biến hiện nay.\r\n\r\nLâm Lâm, một phóng viên trẻ tuổi có đời tư phức tạp, có cơ hội được tiếp xúc với những người trẻ làm nghệ thuật ở Hà Nội và thành phố Hồ Chí Minh.\r\n\r\nĐằng sau những buổi triển lãm muôn sắc màu của hội họa, của nghệ thuật trình diễn và sắp đặt là một thế giới phức tạp, có phần điên rồ của mỗi cá nhân. Bản thân Lâm Lâm cũng bị cuốn vào bức tranh sáng tối ấy, với cậu bạn trai người Mĩ, những người bạn thân thiết của cô hay một vài người làm nghệ thuật đi lướt qua cuộc sống của Lâm Lâm. Cô đồng cảm với họ, nhìn thấu niềm say mê, nỗi dằn vặt về mặt tinh thần của họ thể hiện qua các tác phẩm hội họa đương đại. Song song với những trải nghiệm trong đời sống của mình, Lâm Lâm có cơ hội va chạm với một thế giới của tình yêu đồng giới, của những bạn trẻ mang những ưu tư, nỗi khát khao ám ảnh vượt lên những quy chuẩn thông thường trong hội họa. Qua đó, một cái nhìn đa chiều về thế giới nội tâm phức tạp của con người đã dần hình thành trong suy nghĩ của Lâm Lâm. “Cứ cho, có nhiều cách sống và nhiều cách chết để sống”', 9, 277, 'active', NULL);
INSERT INTO `ebook` VALUES (278, 'V26.0', 'Nỗi Buồn Chiến Tranh', 90000.00, 'Nỗi Buồn Chiến Tranh là một tác phẩm dễ làm người đọc ám ảnh vì câu chữ sâu xa, đau đớn, tàn khốc của một đời chiến binh với từng đoạn hồi ức đứt đoạn bởi cảm xúc, bởi những đoạn đời ngắn ngủi mà cho dù cố ghép lại cũng không thể liền mạch.\r\n\r\nKiên – người kể chuyện, trong mười năm chiến tranh và mười năm hoà bình với gia đình lạc loài không hoàn hảo, với tình yêu mãnh liệt, điên cuồng, với hiện thực chẳng thanh cao mà chỉ nhuốm đầy ti tiện của con người. Trong thế giới ấy, Kiên sống mà như đang mộng, mộng trên chiến trường đầy máu, mộng trong cuộc đời liều lĩnh và theo đuổi sự tự do vĩnh cửu.\r\n\r\nNỗi Buồn Chiến Tranh day dứt nhiều hơn buồn. Người đọc lạc vào những trang sách như đang cất bước trong mê cung tâm tưởng với đủ loại người, đủ loại tính cách, đủ loại quan điểm sống mà ít nhiều đều mang tính huỷ diệt. Nhận diện chiến tranh dưới góc nhìn bi quan và tiêu cực, Nỗi Buồn Chiến Tranh khắc hoạ cái định nghĩa bi thảm về chiến tranh, rằng “Chiến tranh là cõi không nhà không cửa, lang thang khốn khổ và phiêu bạt vĩ đại, là cõi không đàn ông, không đàn bà, là thế giới thảm sầu, vô cảm, là tuyệt tự khủng khiếp nhất của dòng giống con người.” Trong cái cõi ấy, có hàng ngàn thanh niên, như Kiên, dù đã tự hỏi mình nhưng vẫn nhiệt tình cống hiến, để rồi khi nó qua đi, cả cuộc đời đã không còn lại gì nữa', 9, 278, 'active', NULL);
INSERT INTO `ebook` VALUES (279, 'V27.0', 'Lều Chõng', 67000.00, 'Từ gần một trăm năm nay, “ Khoa cử Hán học” với “ Lều chõng” đã vắng bóng trên đất nước ta.   Là nhân chứng và cũng là nạn nhân của trận cuồng phong “ giáo dục hán học sụp đổ”, Ngô Tất Tố có “đủ tư cách, đủ thẩm quyền” mà ít ai sánh kịp, để thỏa sức viết về học hành, thi cử, về giới nhà Nho của thời xưa.\r\n\r\nLều chõng đã tái hiện một cách sinh động, sắc nét, giúp các thế hệ hậu sinh lội ngược dòng thời gian để khám phá về   Lều chõng – không gian có ý nghĩa đặc biệt, không chỉ liên quan chuyện văn chương, chữ nghĩa mà còn gắn bó mật thiết đến vận mệnh đại sự của quốc gia, đến sự tồn vong, hưng thịnh của đất nước.\r\n\r\nThành công đặc sắc của Lều Chõng là nói lên “ bi kịch” của giới nhà Nho – lớp trí thức thời xưa.  Vô cũng ngám ngấm với kiếp sống đam mê nuôi ảo tưởng khát khao “ cuộc đời vàng son” khi thành đạt, suốt đời lăn lộn, lao đao tìm đường tiến thân bằng “ khoa cử”, sau khi vỡ mộng, “ kẽ sĩ” đã thức tỉnh, rũ bỏ tâm lý “đam mê hoài vọng về khoa cử” để trở về với đời thường.', 9, 279, 'active', NULL);
INSERT INTO `ebook` VALUES (280, 'V28.0', 'Vết Thù Hằn Trên Lưng Ngựa Hoang', 56000.00, 'Trong tác phẩm Vết Thù Hằn Trên Lưng Ngựa Hoang ( 1967 ) nhân vật chính là Hoàng, đờn guitar rất giỏi nên có biệt danh là Hoàng guitar, Hoàng có địa vị cao trong một băng du đãng , sau đó muốn hoàn lương, về mở lớp dạy đàn, nhưng đồng bọn vẫn muốn kéo anh vào những việc bất lương. Ngày cuối vì mong có điều kiện xây dựng tương lai hạnh phúc, anh đã nhận lời làm một phi vụ cuối cùng và bị lộ. Những phát đạn oan nghiệt cắm sâu vào lưng Hoàng như những vết thù đời không bao giờ xoá được và cũng chấm dứt kiếp ngựa hoang.', 9, 280, 'active', NULL);
INSERT INTO `ebook` VALUES (281, 'V29.0', 'Hương Sắc Trong Vườn Văn', 67000.00, 'Nghệ thuật có mục đích ghi và thực hiện được cái Đẹp trong vũ trụ; mà trong các nghệ thuật, văn chương và âm nhạc phổ cập hơn hết, cảm người ta sâu hơn hết; riêng văn chương lại có công dụng giảng giải, truyền bá các nghệ thuật khác; nên từ khi nhân loại có chữ viết, thì bất kỳ ở thời nào và xứ nào, nó cũng được coi trọng hơn mọi môn và được dạy nhiều nhất trong các trường học…', 9, 281, 'active', NULL);
INSERT INTO `ebook` VALUES (282, 'V30.0', 'Đời Viết Văn Của Tôi', 98000.00, 'Trong bộ Hồi Ký dầy trên bảy trăm trang tôi chép về gia đình tôi, đời sống, đời viết văn của tôi, và ghi những nét chính về xã hội Việt Nam từ sau thế chiến thứ nhất tới nay.\r\n\r\nTôi theo thứ tự thời gian nên những trang về đời viết văn rải rác trong suốt bộ, chỗ thì vài trang, chỗ thì trọn một chương, có chỗ năm chương liên tiếp.\r\n\r\nNay tôi tách những đoạn, chỗ đó ra, gom chung vào tập này. Để nối những đoạn, chương rải rác, tôi đã phải thêm đó đây ít hàng hoặc một đoạn mà tôi viết lùi vào trong một chút cho dễ nhận. Tôi đã bỏ nhiều đoạn nhưng cũng thêm nhiều chi tiết không chép trong bộ Hồi Ký.\r\n\r\nĐời tôi có thể tóm tắt trong hai chữ HỌC và VIẾT. Hai việc đó liên quan mật thiết với nhau gần suốt đời, tôi viết để học, và học để viết. Cho nên chép về đời văn của tôi, tôi phải nhắc trước hết đến việc tự học, mà hai môn quan trọng nhất tôi tự học là Hán tự và Anh ngữ, nhờ đó tôi mới có những chìa khoá để mở mang thêm kiến thức, mới viết được nhiều và được độc giả chú ý tới.\r\n\r\nLong Xuyên, ngày 15.10.1980\r\n\r\nNguyễn Hiến Lê', 9, 282, 'active', NULL);
INSERT INTO `ebook` VALUES (283, 'V31.0', 'Đời Nghệ SĨ', 99000.00, '“Đa tài thường đa tật: nhất là các nghệ sĩ phương Tây ở thế kỷ XIX, thế kỷ lãng mạn, đam mê, cuồng loạn thì lại càng nhiều tật vì không khí chung của thời đại. Nhưng họ có tài, cảm xúc sâu sắc hơn ta, tưởng tượng dồi dào hơn ta, phô diễn được nỗi lòng cùng tư tưởng một cách tinh tế hơn ta, miêu tả được thiên nhiên một cách chân xác, bóng bẩy hơn ta. Họ vừa là những đại biểu của nhân loại – vì là người thường như chúng ta, có tâm tư của chúng ta – vừa là những vì sao lấp lánh, những bông hoa rực rỡ tô điểm cho vũ trụ.\r\n\r\nVà ngay cả những kẻ nhiều tật nhất, tâm hồn cũng có một vài điểm khả ái: Chateaubriand về già chịu nghèo để giữ thanh danh, Goethe rất khiêm tốn, nhận rằng đã mang ơn rất nhiều của tiền nhân cũng như của người đồng thời… Đáng quí hơn cả là hết thảy đều có đức chung này: càng có tài lại càng trau giồi cái tài, cần cù làm việc suốt đời, chỉ nhắm mỗi mục đích là lưu lại cái đẹp cho hậu thế.”', 9, 283, 'active', NULL);
INSERT INTO `ebook` VALUES (284, 'V32.0', 'Tuyển Tập Nguyễn Hiến Lê - Tập 4: Văn Học', 45000.00, 'Nguyễn Hiến Lê là một học giả, một nhà văn lớn của Việt Nam. Ông là tác giả của hơn 100 công trình văn học, văn hóa, văn chương Việt Nam, Anh, Pháp, Trung Quốc. Tác phẩm của ông là những đóng góp lớn cho văn hóa sử Việt Nam hiện đại.\r\nBộ sách Tuyển tập Nguyễn Hiến Lê do Nguyễn Q. Thắng sưu tầm, tuyển chọn và giới thiệu.\r\nBộ sách Tuyển tập Nguyễn Hiến Lê gồm có 4 cuốn: Triết học, Sử học, Ngữ học, Văn học\r\nTuyển Tập Nguyễn Hiến Lê – Tập IV: Văn Học\r\n\r\nCái đẹp bao trùm cả cái Chân và cái Thiện; mà mục đích của đời người là tìm tòi thực hiện rồi hưởng cái Đẹp. Chúng ta càng văn minh bao nhiêu thì càng bỏ nhiều thì giờ để theo đuổi mục đích đó bấy nhiêu. Ngay từ hồi tiền sử, cả ức vạn năm về trước, tổ tiên ta mỗi khi được rảnh rang, khỏi phải lo cái ăn cái mặt, đã tỉ mỉ đục trên đá hình vạn vật ở chung quanh, nét đục rất tinh xảo, rồi họ lại biết tạo ra những xa xỉ phẩm, chê trái cây trong rừng là không ngon…\r\nNghệ thuật có mục đích ghi và thực hiện được cái đẹp trong vũ trụ; mà trong các nghệ thuật, văn chương và âm nhạc phổ cập hơn hết, cảm người ta sâu hơn hết, riêng văn chương lại có công dụng giảng giải, truyền bá các nghệ thuật khác, nên từ khi nhân loại có chữ viết thì bất kỳ ở thời nào và xứ nào, nó cũng được coi trọng hơn mọi môn khác và đựơc dạy nhiều nhất trong các trường học.', 9, 284, 'active', NULL);
INSERT INTO `ebook` VALUES (285, 'V33.0', 'Điều Bí Mật', 34000.00, 'Một cô gái nhỏ nhắn mà từng câu từng chữ đều mạnh mẽ, cá tính, Hân Như trong Điều bí mật là người kể chuyện xuất sắc đến kinh ngạc. Với lối viết dày tình tết, giàu cảm xúc và chín chắn, Hân Như đã đi vào lòng độc giả bằng ngòi bút hồ hởi, nhiệt thành như phong cách đặc trưng vốn có của cô.\r\n\r\nCó ai đó nói rằng, những điều bí mật như một củ hành, bóc hết lớp nọ đến lớp kia, cuối cùng thứ nhận được chỉ toàn là nước mắt. Những điều bí mật khiến cho cuộc sống trở nên muôn màu muôn vẻ, nhưng cũng có lúc, chỉ một bí mật nhỏ nhoi cũng đủ làm nên số phận của cả một con người.\r\n\r\nCâu chuyện vẫn còn tiếp diễn như một bản nhạc đầy mâu thuẫn với những bí mật nối tiếp nhau hé mở.\r\n\r\nĐại và Linh có vượt qua được tất cả khó khăn của hoàn cảnh và định kiến trong lòng để đến với nhau trọn vẹn?\r\n\r\nNhững mưu mô, toan tính của Phong sẽ dẫn họ đi đến kết cục nào?\r\n\r\nQuanh họ, tình anh em, tình cha con, tình yêu đơn phương day dứt luôn khiến không gian của câu chuyện thật ám ảnh lòng người. Để rồi khi chợt còn nhận ra nhau giữ đời trong trái tim rung động yêu thương của mỗi người họ chỉ còn chỗ cho niềm tin và hi vọng.', 9, 285, 'active', NULL);
INSERT INTO `ebook` VALUES (286, 'V34.0', 'Cơ Hội Của Chúa', 54000.00, 'Cơ hội của Chúa là một tác phẩm đầy ắp các không gian trong một hình thức đa diện nhất: truyện trong truyện, chuyện tình yêu, tình bạn, quan hệ tay ba, chuyện tôn giáo và thế tục, chuyện cuộc đời của các thế hệ sống ở một Hà Nội buổi giao thời khi bước vào giai đoạn kinh tế mở cửa những năm cuối thập niên 1980. Những nhân vật chính của tiểu thuyết tiêu biểu cho một thế hệ trẻ Hà Nội đã yêu và sống đầy khắc khoải nhưng cũng yếm thế buông xuôi. Nguyễn Việt Hà đã nói được trạng thái tâm lý của một thế hệ “mất mát”, cái trạng thái điển hình gặp ở nhiều nền văn học, nhưng trong Cơ hội của Chúa, nó mang cảm xúc của những góc phố Hà Nội đang biến đổi, cái biến đổi một đi không trở lại.', 9, 286, 'active', NULL);
INSERT INTO `ebook` VALUES (287, 'V35.0', 'Khách Nợ ', 55000.00, 'Khách Nợ là nét vẽ thực về những con người, những cảnh đời khốn cùng ở làng quê nghèo ngoại thành Hà Nội trước Cách mạng Tháng Tám. Với cách kể chuyện bình dị, nhẹ nhàng, không màu mè, hoa mỹ, từng câu chuyện, từng số phận cứ từ từ xuất hiện, họ sống, chết, đói khổ, đau thương… chân thật đến ngỡ ngàng nhưng cũng xót xa đến ngỡ ngàng. Trong tập truyện không thể không kể đến những trang viết độc đáo, đầy hấp dẫn về loài vật như Đôi ri đá, Chú gà trống ri, Mụ ngan… Những câu chuyện tưởng chừng vô thưởng vô phạt, nhưng góp phần không nhỏ phơi bày những hiện trạng xã hội thời bấy giờ.\r\n\r\nDường như với bất kỳ tác phẩm nào của mình đã xuất bản, Tô Hoài cũng luôn cẩn trọng đọc lại và chỉnh sửa những chi tiết chưa hài lòng. Như chính lời con trai của Cụ, nhà báo Nguyễn Phương Vũ, chia sẻ: “Đã từ lâu từ khi cầm bút bố tôi là người cẩn thận và luôn có trách nhiệm với câu chữ nên mỗi bản in dù là in lại nhưng ông luôn đọc, cắt gọt, chỉnh sửa, “uốn nắn”, tỉ mẩn như người dệt vải. Khi ông trao lại cho tôi để xử lý nhập liệu với một bản thảo chi chít màu mực, chữ, từ, câu mà ông thêm bớt đan xen ngang dọc. Cha tôi là vậy, sự cẩn trọng, kỹ lưỡng trong nghề viết như mối nợ tình với ông.', 9, 287, 'active', NULL);
INSERT INTO `ebook` VALUES (288, 'V36.0', 'Vu Quy', 66000.00, 'Vu quy dường như là một bước ngoặc lớn đánh dấu cuộc đời người con gái. Có người hạnh phúc, vui vẻ vì vu quy như ý nhưng cũng có không ít trường hợp vu quy về nhà chồng lại đầy những giọt nước mắt đau khổ.\r\n\r\n“Vu Quy” của Nam Dao tạo nên bức tranh muôn màu của cuộc sống đầy vất vả, lo toan của những người dân vùng Đất Mũi sau ngày giải phóng đất nước. Nơi ấy không chỉ có mối tình tuyệt vọng của Thẻo và Tư mà còn có tình đồng chí đẹp đẽ giữa Sáu Nhiêm và Tám Hớn, Ba Tri; có tình yêu trong sáng của chị Hai và anh Bảy và cả những mưu toan ích kỷ của những kẻ đục nước béo cò… Nhưng hơn hết, “Vu Quy” gợi cho chúng ta nhiều suy nghĩ về tình người và những số phận gặp nhiều ngang trái, đắng cay nhưng vẫn không ngừng chèo chống con thuyền số phận đến bến bờ mà mình hằng mong ước.', 9, 288, 'active', NULL);
INSERT INTO `ebook` VALUES (289, 'V37.0', 'Trúng Số Độc Đắc', 72000.00, 'Trúng Số Độc Đắc là tác phẩm cuối đời của Vũ Trọng Phụng. Khác với lối viết tiểu thuyết trước, cứ đến ngày báo ra mới viết một chương, đưa in xong hết mới mới thành sách, Trúng Số Độc Đắc được Vũ Trọng Phụng viết một mạch đến khi hoàn thành, tự tay đi đóng thành quyển rồi mới đưa cho nhà xuất bản. Người bạn cố tri của Vũ Trọng Phụng là Ngọc Giao kể lại rằng mấy hôm trước khi qua đời, Vũ Trọng Phụng đã nhờ mình dìu đến tận nhà in, xin mấy tờ bản thảo đã xếp chữ rồi, vẫn còn lấm lem mực in và dấu ta thợ in, đưa và dặn Ngọc Giao giữ lại để lót đầu cho mình khi đăt thi hài mình vào áo quan.\r\n\r\nKhông đậm chất trào phúng khiến người ta phải vỗ đùi bôm bốp, phá lên mà cười như Số Đỏ, mà nhiều lý lẽ sâu sắc, thăng trầm hơn, nhưng vẫn mang giọng kể tự nhiên, châm biến hài hước của Vũ Trọng Phụng.\r\n\r\nCả tiểu thuyết chỉ tập trung vào nhân vật Phúc (nhân vật chính trúng số). Không có trang nào mà không có Phúc, tất cả chỉ để biểu đạt tâm tư suy nghĩ của anh, cả ngoại hình anh cũng chỉ được phác họa vài dòng ngắn gọn. Vũ Trọng Phụng mượn nhân vật Phúc để kể về về nhân tình thế thái, về thói đời, lòng người đổi trắng thay đen. Và cả chính Phúc, được dịp may đổi đời, rồi có cơ hội chứng kiến, hiểu và cười lòng người thế, cũng không tránh khỏi việc bản thân thay đổi theo hoàn cảnh, thời thế. Bởi vì Phúc cũng là con người. ', 9, 289, 'active', NULL);
INSERT INTO `ebook` VALUES (290, 'V38.0', 'Một Chủ Nhật Khác', 69000.00, 'Truyện dài Một Chủ Nhật Khác, tác phẩm sau cùng của Thanh Tâm Tuyền trước năm 1975, được in lại do sự đóng góp của một số bạn hữu nhà văn ở Hoa Kỳ, là ấn phẩm thứ nhất của cơ sở xuất bản Văn.\r\n\r\nMở đầu với tác phẩm một nhà văn lớn hiện đang sống ở quê nhà sau nhiều năm bị giam cầm trong ngục tù cộng sản, chủ đích trước hết của cơ sở vừa thành hình với tái bản Một Chủ Nhật Khác là tạo phương tiện để lần lượt in nhiều tác phẩm khác, lựa chọn trong những tác phẩm chủ yếu đã làm nên 30 năm văn chương của 30 năm tiểu thuyết miền Nam. Và trước hết, của những tác giả còn ở quê nhà như Thanh Tâm Tuyền.\r\nKhông trừ một trường hợp nào, mọi tác phẩm tái bản, tiền lời bán sách nếu có, sẽ được gửi trọn vẹn về cho tác giả hoặc gia đình tác giả ở Việt Nam. Việc làm hoàn toàn đặt trên căn bản bất vụ lợi này của chúng tôi, mong dành được sự hỗ trợ và tiếp tay quý báu của thân hữu và bạn đọc.', 9, 290, 'active', NULL);
INSERT INTO `ebook` VALUES (291, 'V39.0', 'Bên Kia Bờ Ảo Vọng', 100000.00, 'Cái nổi bật của tiểu thuyết nằm ở ngay vấn đề mà tác giả đặt ra: lên án thói giả trá, ti tiện, lột trần thực chất tầm thường của những thần tượng trong cuộc sống thông thường của mỗi người. Ý nghĩa khái quát rút ra là: người ta không nên đem cả cuộc đời mình, hạnh phúc của mình đặt dưới chân những thần tượng có bề ngoài hào nhoáng nhưng thực chất tầm thường, phàm tục. Đây không chỉ là vấn đề của các cá nhân riêng lẻ mà ít nhiều còn là vấn đề của thời đại. Với tiểu thuyết này, tác giả đã tấn công vào thành lũy thói quen ngộ nhận cũ. Sự mạnh mẽ ấy làm cho tiểu thuyết có sức hấp dẫn, lôi cuốn ngay từ khi mới xuất bản.\r\n\r\nCái mạnh của tác giả Bên kia bờ ảo vọng còn ở nghệ thuật xây dựng nhân vật. Tác phẩm của chị không có ý định phán quyết số phận cuộc đời của một con người mà chỉ là một phần, một khúc của đời sống con người. Câu chuyện cũng chỉ xoay quanh chuyện tình ái vặt vãnh của một vài nhân vật thuộc giới văn hóa, văn nghệ, nhà báo, nhà giáo… Thời gian gói tròn trong hơn một năm từ mùa xuân năm nay đến mùa xuân năm sau. Còn không gian thì cũng không quá trải rộng, quá xa nội thành Hà Nội. Mặc dù vậy, nhân vật của chị rất sống, có cá tính riêng. Dương Thu Hương tỏ ra khá già dặn trong việc miêu tả những biến thái tâm lý nhân vật, đôi khi chỉ thông qua những biểu hiện nhỏ nhặt bề ngoài: một câu nói lấp lửng, một vết nhăn hoặc một lằn gân xanh mới xuất hiện, một bàn tay buông thõng trước gối, một sải bước đĩnh đạc. Người đọc như cảm thông đến tận cùng nỗi đau mất vợ, tan vỡ tổ ấm gia đình của Nguyên một nhà báo đã từng phạm một tội lỗi thông thường: vì quá chăm chú cho cuộc sống vợ con nên đã trót “đánh đĩ” ngòi bút, viết lách chiều ý thủ trưởng của mình. Chính cái hành vi ấy khiến anh mất vai trò thần tượng trong mắt vợ và điều này kéo theo sự tan vỡ của hạnh phúc gia đình. Người đọc cũng đau xót trước những lầm lỡ của Phương Linh, cô giáo trẻ xinh đẹp, dạy văn giỏi song khá mơ mộng, dại dột, cả tin, trao gửi niềm tin và hy vọng của mình cho các thần tượng: lúc đầu là Nguyên, chồng mình và sau đó là Trần Phương, một nhạc sĩ nổi danh.', 9, 291, 'active', NULL);
INSERT INTO `ebook` VALUES (292, 'V40.0', 'Thềm Hoang', 60000.00, 'Nhật Tiến, Tên Bùi Nhật Tiến; sinh ngày 24-81936 tại Hà Nội; Di cư vào Nam năm 1954. Viết truyên ngắn, truỵện dài trên các tạp chí: Văn Hóa Ngày Nay, Tân Phong, Đông Phương, Bách Khoa, Văn, Văn Học, chủ trương nhà xuất bản Huyền Trân (1962), chủ biên tuần báo Thiếu Nhi (1971-1975). Dạy Vật lý và Hoá học tại các trường Trung học ở Sài Gòn từ năm 1960. Giải thưởng Văn chương Toàn Quốc năm 1962. Nguyên Phó Chủ tịch Trung Tâm Văn Bút VN (1965-1975), nguyên Hội viên Hội Đồng Văn Hoá Giáo Dục (nhiệm kỳ II,1974). Năm 1979 vượt biển qua Thái Lan rồi định cư tại Hoa Kỳ từ năm 1980; Hoạt động văn hoá ở hải ngoại: Nguyên Phó Chủ tịch Hội Cựu Giáo Chức Việt Nam Hải Ngoại (1982- 1985). Nguyên Chủ tịch Ban Chấp hành Lâm thời Văn Bút Việt Nam Hải Ngoại Nam California (1988). Hiện cư ngụ tại California.', 9, 292, 'active', NULL);

-- ----------------------------
-- Table structure for ebookauthor
-- ----------------------------
DROP TABLE IF EXISTS `ebookauthor`;
CREATE TABLE `ebookauthor`  (
  `ebookID` int NOT NULL,
  `authorID` int NOT NULL,
  `role` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  PRIMARY KEY (`ebookID`, `authorID`) USING BTREE,
  INDEX `authorID`(`authorID` ASC) USING BTREE,
  CONSTRAINT `ebookauthor_ibfk_1` FOREIGN KEY (`ebookID`) REFERENCES `ebook` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `ebookauthor_ibfk_2` FOREIGN KEY (`authorID`) REFERENCES `author` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

