-- ----------------------------
-- Table structure for ebookimage
-- ----------------------------
DROP TABLE IF EXISTS `ebookimage`;
CREATE TABLE `ebookimage`  (
  `ebookID` int NOT NULL,
  `imgID` int NOT NULL,
  `isCover` tinyint(1) NULL DEFAULT 0,
  `sortOrder` int NULL DEFAULT 0,
  PRIMARY KEY (`ebookID`, `imgID`) USING BTREE,
  INDEX `imgID`(`imgID` ASC) USING BTREE,
  CONSTRAINT `ebookimage_ibfk_1` FOREIGN KEY (`ebookID`) REFERENCES `ebook` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `ebookimage_ibfk_2` FOREIGN KEY (`imgID`) REFERENCES `images` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

